function getBrowserSessionStorageArea() {
    if(browser.storage?.session) return browser.storage.session

    const chromeSession = globalThis.chrome?.storage?.session || null
    if(!chromeSession) return null

    return {
        get(defaults = {}) {
            return new Promise((resolve, reject) => {
                chromeSession.get(defaults, result => {
                    const error = globalThis.chrome?.runtime?.lastError
                    if(error) {
                        reject(new Error(error.message || `${error}`))
                        return
                    }
                    resolve(result || {})
                })
            })
        },
        set(payload = {}) {
            return new Promise((resolve, reject) => {
                chromeSession.set(payload, () => {
                    const error = globalThis.chrome?.runtime?.lastError
                    if(error) {
                        reject(new Error(error.message || `${error}`))
                        return
                    }
                    resolve()
                })
            })
        }
    }
}

function hasBrowserSessionStorage() {
    const area = getBrowserSessionStorageArea()
    return !!(
        area &&
        typeof area.get === 'function' &&
        typeof area.set === 'function'
    )
}

function rememberBrowserSessionMarker(reason = 'observed') {
    const area = getBrowserSessionStorageArea()
    if(!area || typeof area.set !== 'function') return Promise.resolve(false)

    return promiseWithTimeout(
        area.set({
            [BROWSER_SESSION_MARKER_KEY]: {
                id: makeId('browser-session'),
                reason,
                extensionVersion: getExtensionVersion(),
                observedAt: Date.now()
            }
        }),
        1000,
        'browser session marker write'
    )
        .then(() => true)
        .catch(() => false)
}

function rememberQuoraRuntimeActivation(reason = 'quora-observed') {
    const area = getBrowserSessionStorageArea()
    if(!area || typeof area.set !== 'function') return Promise.resolve(false)

    return promiseWithTimeout(
        area.set({
            [QUORA_RUNTIME_ACTIVATED_SESSION_KEY]: {
                active: true,
                reason,
                extensionVersion: getExtensionVersion(),
                observedAt: Date.now()
            }
        }),
        1000,
        'quora runtime activation marker write'
    )
        .then(() => true)
        .catch(() => false)
}

function forgetQuoraRuntimeActivation(reason = 'quora-runtime-reset') {
    quoraRuntimeActivated = false
    const area = getBrowserSessionStorageArea()
    if(!area || typeof area.set !== 'function') return Promise.resolve(false)

    return promiseWithTimeout(
        area.set({[QUORA_RUNTIME_ACTIVATED_SESSION_KEY]: null}),
        1000,
        'quora runtime activation marker clear'
    )
        .then(() => {
            pushQueueWakeupJournalEntry({
                kind: 'state-change',
                name: 'quora-runtime-activation-cleared',
                reason,
                result: 'state-changed'
            })
            return true
        })
        .catch(() => false)
}

function ensureBrowserSessionStartupMetricsReset() {
    if(browserSessionStartupResetChecked) return Promise.resolve(false)
    if(browserSessionStartupResetPromise) return browserSessionStartupResetPromise
    if(!hasBrowserSessionStorage()) {
        browserSessionStartupResetChecked = true
        return Promise.resolve(false)
    }

    const area = getBrowserSessionStorageArea()
    browserSessionStartupResetPromise = promiseWithTimeout(
        area.get({[BROWSER_SESSION_MARKER_KEY]: null}),
        1000,
        'browser session marker load'
    )
        .then(async stored => {
            if(stored?.[BROWSER_SESSION_MARKER_KEY]) return false

            await rememberBrowserSessionMarker('browser-startup')
            pendingQueueWakeupMetricsReset = {
                reason: 'browser-startup',
                requestedAt: Date.now()
            }
            return true
        })
        .catch(() => false)
        .finally(() => {
            browserSessionStartupResetChecked = true
            browserSessionStartupResetPromise = null
        })

    return browserSessionStartupResetPromise
}

function clearSchedulerAlarms(reason = 'clear-scheduler-alarms') {
    if(!browser.alarms?.clear) return Promise.resolve(false)

    return Promise.all([
        browser.alarms.clear(COORDINATOR_RESUME_ALARM_NAME).catch(() => false),
        browser.alarms.clear(COORDINATOR_RECONCILE_ALARM_NAME).catch(() => false),
        browser.alarms.clear(PERSISTENT_FAILED_RETRY_ALARM_NAME).catch(() => false)
    ])
        .then(results => {
            pushQueueWakeupJournalEntry({
                kind: 'state-change',
                name: 'scheduler-alarms-cleared',
                reason,
                result: results.some(Boolean) ? 'state-changed' : 'no-op'
            })
            return results.some(Boolean)
        })
        .catch(() => false)
}

async function resetQueueWakeupMetricsEpochAfterLoad(reason = 'manual', options = {}) {
    if(queueWakeupMetricsReadyPromise) {
        await queueWakeupMetricsReadyPromise.catch(() => null)
    }
    else if(!queueWakeupMetricsLoaded) {
        await ensureQueueWakeupMetricsLoaded().catch(() => null)
    }
    pendingQueueWakeupMetricsReset = null
    if(isFreshQueueWakeupMetricsEpoch(reason)) {
        await flushQueueWakeupMetrics()
        return {
            reset: true,
            coalesced: true,
            deferred: options.deferUntilQuora === true && !quoraRuntimeActivated,
            resetReason: reason,
            epochId: getQueueWakeupMetricEpoch().epochId,
            startedAt: getQueueWakeupMetricEpoch().startedAt
        }
    }
    resetQueueWakeupMetricsEpoch(reason)
    await flushQueueWakeupMetrics()
    return {
        reset: true,
        deferred: options.deferUntilQuora === true && !quoraRuntimeActivated,
        resetReason: reason,
        epochId: getQueueWakeupMetricEpoch().epochId,
        startedAt: getQueueWakeupMetricEpoch().startedAt
    }
}

function startQueueWakeupMetricsBackedStartupWork(options = {}) {
    if(!quoraRuntimeActivated && options.force !== true) {
        return Promise.resolve(null)
    }

    const metricsReady = ensureBrowserSessionStartupMetricsReset()
        .then(() => ensureQueueWakeupMetricsLoaded())
        .then(async () => {
            if(pendingQueueWakeupMetricsReset) {
                const reset = pendingQueueWakeupMetricsReset
                pendingQueueWakeupMetricsReset = null
                resetQueueWakeupMetricsEpoch(reset.reason || 'browser-startup')
                await flushQueueWakeupMetrics()
            }
        })
        .catch(() => null)

    void metricsReady
    return metricsReady
}

function markQuoraRuntimeActivated(reason = 'quora-observed') {
    if(quoraRuntimeActivated) {
        void rememberQuoraRuntimeActivation(reason)
        return false
    }
    quoraRuntimeActivated = true
    incrementQueueWakeupMetric('runtime.quoraActivated')
    pushQueueWakeupJournalEntry({
        kind: 'state-change',
        name: 'quora-runtime-activated',
        reason,
        result: 'state-changed'
    })
    void rememberQuoraRuntimeActivation(reason)
    void startQueueWakeupMetricsBackedStartupWork({force: true})
    scheduleQueuedWorkerActionSurfaceCleanup('quora-runtime-activated-idle', 5000)
    if(coordinatorResumePromise || queuedTabFillPromise) {
        incrementQueueWakeupMetric('runtime.quoraActivatedResumeAlreadyActive')
        return true
    }
    void resumeStoredWorkAfterQuoraActivation(reason).catch(() => null)
    return true
}

async function resumeStoredWorkAfterQuoraActivation(reason = 'quora-observed') {
    const currentAuthorityState = await loadCoordinatorCurrentAuthorityState({
        [COORDINATOR_PAUSED_KEY]: false,
        [COORDINATOR_PAUSE_GENERATION_KEY]: 0
    }).catch(() => null)
    const queue = currentAuthorityState?.queue || {}
    if(!hasStoredCoordinatorWork(queue)) return {resumed: false, reason: 'no-stored-work'}

    const stored = currentAuthorityState?.stored || {}
    const wasPaused = stored?.[COORDINATOR_PAUSED_KEY] === true
    const storedPauseGeneration = Number.parseInt(stored?.[COORDINATOR_PAUSE_GENERATION_KEY], 10) || 0
    if(wasPaused && storedPauseGeneration) {
        incrementQueueWakeupMetric('pump.deferredExplicitPause')
        pushQueueWakeupJournalEntry({
            kind: 'state-change',
            name: 'coordinator-explicit-pause-preserved',
            reason,
            result: 'no-op',
            details: {
                pauseGeneration: storedPauseGeneration
            }
        })
        return {resumed: false, paused: true, reason: 'coordinator-paused'}
    }
    if(wasPaused) {
        await setCoordinatorPauseControlState(false, 0, 'ordinaryMutation')
        void setCoordinatorRunsPaused(false).catch(() => null)
        incrementQueueWakeupMetric('pump.changed.stalePauseCleared')
        pushQueueWakeupJournalEntry({
            kind: 'state-change',
            name: 'coordinator-stale-pause-cleared',
            reason,
            result: 'state-changed',
            details: {
                pauseGeneration: storedPauseGeneration
            }
        })
    }

    return runCoordinatorQueueExecutorFastPath('quora-runtime-activated-auto-resume', {
        currentAuthorityState: {
            ...currentAuthorityState,
            stored: {
                ...(currentAuthorityState?.stored || {}),
                [COORDINATOR_PAUSED_KEY]: false,
                [COORDINATOR_PAUSE_GENERATION_KEY]: 0
            }
        },
        awaitFill: true,
        skipAuthorityReconcile: true,
        forceDurableQueueReload: false,
        skipPauseStorageCheck: wasPaused
    })
}

function markQuoraRuntimeActivatedFromRequest(request = {}, sender = {}, reason = 'message') {
    const urls = [
        sender?.tab?.url,
        request?.url,
        request?.profileHref,
        request?.href,
        request?.targetProfileHref,
        request?.requestedUrl,
        request?.sourcePageUrl,
        request?.source?.pageUrl,
        request?.run?.sourcePageUrl
    ]
    if(Array.isArray(request?.items)) {
        for(const item of request.items) {
            urls.push(
                item?.url,
                item?.href,
                item?.profileHref,
                item?.targetProfileHref,
                item?.requestedUrl,
                item?.sourcePageUrl
            )
        }
    }
    if(Array.isArray(request?.urls)) urls.push(...request.urls)
    if(Array.isArray(request?.profileHrefs)) urls.push(...request.profileHrefs)
    if(urls.some(isQuoraRuntimeUrl)) {
        return markQuoraRuntimeActivated(reason)
    }
    return false
}

async function observeExistingQuoraRuntimeTabs(reason = 'existing-quora-tab') {
    if(quoraRuntimeActivated) return true

    let tabs = []
    try {
        tabs = await promiseWithTimeout(
            browser.tabs.query({url: 'https://*.quora.com/*'}),
            QUORA_RUNTIME_TAB_QUERY_TIMEOUT_MS,
            'quora runtime tab query'
        )
    }
    catch {
        return false
    }

    if(tabs.some(tab => isQuoraRuntimeUrl(tab?.url || ''))) {
        markQuoraRuntimeActivated(reason)
        return true
    }

    return false
}

async function restoreQuoraRuntimeActivationFromSession(reason = 'session-activation-restore') {
    if(quoraRuntimeActivated) return true

    const area = getBrowserSessionStorageArea()
    if(!area || typeof area.get !== 'function') return false

    let stored = null
    try {
        stored = await promiseWithTimeout(
            area.get({[QUORA_RUNTIME_ACTIVATED_SESSION_KEY]: null}),
            1000,
            'quora runtime activation marker load'
        )
    }
    catch {
        return false
    }

    const marker = stored?.[QUORA_RUNTIME_ACTIVATED_SESSION_KEY] || null
    if(marker?.active !== true) return false

    quoraRuntimeActivated = true
    incrementQueueWakeupMetric('runtime.quoraActivationRestored')
    pushQueueWakeupJournalEntry({
        kind: 'state-change',
        name: 'quora-runtime-activation-restored',
        reason,
        result: 'state-changed',
        details: {
            observedAt: marker.observedAt || 0,
            originalReason: marker.reason || ''
        }
    })
    void startQueueWakeupMetricsBackedStartupWork({force: true})
    return true
}

async function ensureQuoraRuntimeActivatedForScheduler(reason = 'scheduler') {
    if(quoraRuntimeActivated) return true
    if(await restoreQuoraRuntimeActivationFromSession(reason)) return true
    return observeExistingQuoraRuntimeTabs(reason)
}

function makeQuoraRuntimeNotActivatedResult(reason = 'quora-runtime-not-activated') {
    return {
        recovered: false,
        reason,
        requiresQuoraVisit: true,
        alarmCreated: false,
        fallbackScheduled: false,
        resumeScheduled: false,
        reconcileScheduled: false,
        scheduledOnly: true
    }
}

async function isCoordinatorAutoStartOnBrowserStartEnabled() {
    const stored = await metricStorageGet({
        [COORDINATOR_AUTO_START_ON_BROWSER_START_KEY]:
            defaults[COORDINATOR_AUTO_START_ON_BROWSER_START_KEY] === true
    }, {
        phase: 'startupPreferenceGet'
    }).catch(() => null)

    return stored?.[COORDINATOR_AUTO_START_ON_BROWSER_START_KEY] === true
}

async function handleCoordinatorBrowserStartup() {
    await Promise.all([
        forgetQuoraRuntimeActivation('browser-startup'),
        resetQueueWakeupMetricsEpochAfterLoad('browser-startup', {deferUntilQuora: true})
    ]).catch(() => null)

    if(await isCoordinatorPausedInStorage('browser-startup-paused-check')) {
        incrementQueueWakeupMetric('pump.noop.startupPaused')
        return {
            autoStart: false,
            paused: true,
            reason: 'coordinator-paused'
        }
    }

    if(!await isCoordinatorAutoStartOnBrowserStartEnabled()) {
        return {
            autoStart: false,
            reason: 'browser-startup-auto-start-disabled'
        }
    }

    return kickCoordinatorQueueResume('browser-startup-auto-start', {
        allowBeforeQuora: true,
        backgroundFastPath: true,
        skipAuthorityReconcile: true,
        forceDurableQueueReload: true
    })
}

async function rearmStoredWorkAfterExtensionReload(reason = 'extension-updated') {
    if(await isCoordinatorPausedInStorage(`${reason || 'extension-updated'}-paused-check`)) {
        incrementQueueWakeupMetric('pump.noop.rearmPaused')
        return {rearmed: false, paused: true, reason: 'coordinator-paused'}
    }

    if(await refreshStaleCompactQueueViewIfNeeded(reason, 'pump.changed.staleQueueViewRefreshed')) {
        return {rearmed: false, reason: 'stale-queue-view-refreshed'}
    }

    const storedWorkReason = `${reason || 'extension-updated'}-stored-work`
    const queueViewHasStoredWork = await hasUnpausedStoredCoordinatorWorkInQueueView(storedWorkReason)
    let hasStoredWork = false
    if(queueViewHasStoredWork) {
        hasStoredWork = true
    }
    else {
        hasStoredWork = await hasUnpausedStoredCoordinatorWorkInDurableQueue(storedWorkReason)
    }

    if(!hasStoredWork) {
        return {rearmed: false, reason: 'no-stored-work'}
    }

    const resume = await kickCoordinatorQueueResume(reason, {
        allowBeforeQuora: true,
        backgroundFastPath: true,
        skipAuthorityReconcile: true,
        forceDurableQueueReload: true
    })
    return {
        ...(resume || {}),
        rearmed: true,
        reason: resume?.reason || `${reason || 'extension-updated'}-scheduled`
    }
}

async function refreshStaleCompactQueueViewIfNeeded(reason = 'dashboard-ready', metricName = '', options = {}) {
    const storedWorkReason = `${reason || 'dashboard-ready'}-stored-work`
    const queueViewHasStoredWork = options.ignorePaused === true
        ? hasStoredCoordinatorWorkInQueueView((await metricStorageGet({
            [COORDINATOR_QUEUE_VIEW_KEY]: null
        }, {
            phase: storedWorkReason
        }).catch(() => null))?.[COORDINATOR_QUEUE_VIEW_KEY] || null)
        : await hasUnpausedStoredCoordinatorWorkInQueueView(storedWorkReason)
    if(!queueViewHasStoredWork) return false

    const durableQueueHasStoredWork = options.ignorePaused === true
        ? hasStoredCoordinatorWork((await loadCoordinatorQueueProjection({
            metricPath: storedWorkReason
        }).catch(() => null))?.queue || {})
        : await hasUnpausedStoredCoordinatorWorkInDurableQueue(storedWorkReason)
    if(durableQueueHasStoredWork) return false

    await refreshCoordinatorQueueViewForDashboard(`${reason || 'dashboard-ready'}-stale-queue-view`)
        .catch(() => null)
    if(metricName) incrementQueueWakeupMetric(metricName)
    return true
}

async function rearmStoredWorkAfterServiceWorkerReload(reason = 'service-worker-reload') {
    if(!hasBrowserSessionStorage()) return {rearmed: false, reason: 'missing-session-storage'}

    const area = getBrowserSessionStorageArea()
    const stored = await promiseWithTimeout(
        area.get({[BROWSER_SESSION_MARKER_KEY]: null}),
        1000,
        'browser session marker load'
    ).catch(() => null)
    if(!stored?.[BROWSER_SESSION_MARKER_KEY]) return {rearmed: false, reason: 'new-browser-session'}

    return rearmStoredWorkAfterExtensionReload(reason)
}

function scheduleStoredWorkRearmAfterExtensionReload(reason = 'extension-updated') {
    setTimeout(() => {
        void rearmStoredWorkAfterExtensionReload(reason).catch(() => null)
    }, 1000)
}

function scheduleStoredWorkRearmAfterServiceWorkerReload(reason = 'service-worker-reload') {
    setTimeout(() => {
        void rearmStoredWorkAfterServiceWorkerReload(reason).catch(() => null)
    }, 1000)
}

function normalizeObjectNumberMap(value = null) {
    const result = {}
    for(const [key, raw] of Object.entries(value && typeof value === 'object' ? value : {})) {
        const normalizedKey = `${key || ''}`.trim()
        const number = Number(raw) || 0
        if(normalizedKey && Number.isFinite(number)) result[normalizedKey] = number
    }
    return result
}

function normalizeQueueWakeupPhaseMap(value = null) {
    const result = {}
    for(const [key, raw] of Object.entries(value && typeof value === 'object' ? value : {})) {
        const name = `${key || ''}`.trim()
        if(!name || !raw || typeof raw !== 'object') continue
        const count = Math.max(0, Number.parseInt(raw.count, 10) || 0)
        const totalMs = Math.max(0, Number(raw.totalMs) || 0)
        result[name] = {
            count,
            totalMs,
            lastMs: Math.max(0, Number(raw.lastMs) || 0),
            maxMs: Math.max(0, Number(raw.maxMs) || 0),
            lastAt: Number.parseInt(raw.lastAt, 10) || 0
        }
    }
    return result
}

const storageMetrics = createStorageMetrics({
    constants: {
        COORDINATOR_QUEUE_KEY,
        COORDINATOR_QUEUE_WAL_KEY,
        COORDINATOR_QUEUE_VIEW_KEY,
        COORDINATOR_CONTENT_QUEUE_INDEX_KEY,
        COORDINATOR_CONTENT_SOURCE_INDEX_PREFIX,
        COORDINATOR_RUNS_KEY,
        COORDINATOR_EVENTS_KEY,
        QUEUE_WAKEUP_METRICS_VIEW_KEY,
        PROFILE_NUKE_PROGRESS_VIEW_KEY,
        PROFILE_NUKE_PROGRESS_SHARD_PREFIX,
        SPACE_PENDING_NUKED_POSTS_KEY,
        SPACE_NUKED_POSTS_KEY,
        OWNED_TAB_STATE_KEY,
        COORDINATOR_PAUSED_KEY,
        COORDINATOR_PAUSE_GENERATION_KEY,
        COORDINATOR_TAB_KEY,
        QUEUE_WAKEUP_METRICS_KEY
    },
    handlers: {
        incrementQueueWakeupMetric,
        recordQueueWakeupMetricMax,
        incrementActiveStorageMetricDetail,
        setActiveStorageMetricDetail,
        getActiveStorageContext
    },
    state: {
        getSnapshotObserver: () => coordinatorAuthoritySnapshotObserver
    }
})
const {
    getStorageMetricKeyName,
    getJsonByteSize,
    getStoragePayloadRowCount,
    normalizeStorageMetricPathName,
    getStorageMetricPathName,
    recordStoragePathPayloadMetrics,
    recordStoragePathLatencyMetrics,
    normalizeSnapshotWriteReason,
    recordSnapshotWriteReasonMetrics,
    normalizeQueueWriteOperationName,
    getQueueWriteMetricReason,
    recordQueueWriteOperationMetricValue,
    recordQueueWriteOperationMetrics,
    recordStoragePayloadMetrics,
    recordStorageReadPayloadMetrics,
    notifyCoordinatorAuthorityPersistedSnapshot
} = storageMetrics

const coordinatorStorageAdapter = createChromeLocalStorageAdapter(() => browser.storage.local)
const storageUpdateState = createSerializedStorageUpdateState()
const serializedStorageUpdateQueue = createSerializedStorageUpdateQueue({
    state: storageUpdateState,
    setTimeout,
    clearTimeout,
    now: () => Date.now(),
    defaultTimeoutMs: SPACE_FEED_STORAGE_UPDATE_TIMEOUT_MS,
    finishCycle: (cycle, status, reason, details) => finishQueueWakeupMetricCycle(cycle, status, reason, details),
    getJournalDetails: context => getStorageContextJournalDetails(context),
    getTimeoutPhase: context => getStorageTimeoutBucket(context),
    incrementMetric: (name, amount) => incrementQueueWakeupMetric(name, amount),
    onCompleted: context => recordStorageIdleChurnCounters(context),
    onIdle: async context => {
        await flushPendingCoordinatorDiagnosticEventsIfIdle(context)
        scheduleQueueWakeupMetricsFlush()
        flushPostStorageQueuedWorkContinuation()
    },
    onNested: () => incrementQueueWakeupMetric('storageUpdate.nested'),
    onQueueWait: queueWaitMs => recordQueueWakeupPhase('storageQueueWait', queueWaitMs),
    onTimeoutRecovery: (context, reason, serializedTailPromise) => {
        requestStorageTimeoutRecoveryContinuation(context, reason)
        recoverStorageGetTimeoutSerializedTail(context, reason, serializedTailPromise)
    },
    pushJournalEntry: entry => pushQueueWakeupJournalEntry(entry),
    startCycle: reason => startQueueWakeupMetricCycle('storage', 'enqueueSpaceFeedStorageUpdate', reason || '')
})
let coordinatorAuthoritySnapshotObserver = null

function getActiveStorageUpdateToken() {
    return storageUpdateState.getActiveToken()
}

function getActiveStorageContext() {
    return storageUpdateState.getActiveContext()
}

function isStorageUpdateAbandoned(updateToken = getActiveStorageUpdateToken()) {
    return storageUpdateState.isAbandoned(updateToken)
}

function suppressAbandonedStorageOperation(operation = 'storage') {
    if(!isStorageUpdateAbandoned()) return false
    incrementQueueWakeupMetric('storageUpdate.lateWriteSuppressed')
    setActiveStorageMetricDetail('lateWriteSuppressed', true)
    setActiveStorageMetricDetail('abortedOperation', operation)
    return true
}

async function metricStorageGet(defaults = {}, options = {}) {
    incrementQueueWakeupMetric('storageGetCalls')
    incrementActiveStorageMetricDetail('storageGetCalls')
    const pathName = getStorageMetricPathName(options)
    const updateToken = getActiveStorageUpdateToken()
    const storageContext = getActiveStorageContext()
    const startedAt = Date.now()
    let result = null
    try {
        result = await runQueueWakeupMetricPhase(options.phase || 'storageGet', () => coordinatorStorageAdapter.get(defaults))
    }
    finally {
        recordStoragePathLatencyMetrics('read', pathName, Date.now() - startedAt)
    }
    if(updateToken && isStorageUpdateAbandoned(updateToken)) {
        if(storageContext) {
            storageContext.lateWriteSuppressed = true
            storageContext.abortedOperation = 'storageGet'
        }
        incrementQueueWakeupMetric('storageUpdate.lateWriteSuppressed')
        setActiveStorageMetricDetail('lateWriteSuppressed', true)
        setActiveStorageMetricDetail('abortedOperation', 'storageGet')
        throw new Error('abandoned storage update suppressed after storageGet')
    }
    recordStorageReadPayloadMetrics(result, pathName)
    return result
}

async function metricStorageSet(payload = {}, options = {}) {
    const storageContext = getActiveStorageContext()
    if(payload &&
        typeof payload === 'object' &&
        Object.prototype.hasOwnProperty.call(payload, COORDINATOR_QUEUE_KEY) &&
        storageContext?.coordinatorAuthorityQueueMutationApplied === true &&
        options.coordinatorAuthorityWrite !== true) {
        incrementQueueWakeupMetric('coordinatorAuthority.postMutationQueueStorageSetRejected')
        setActiveStorageMetricDetail('rejectedOperation', 'postAuthorityQueueStorageSet')
        return false
    }
    payload = addContentPageStateProjectionPayload(payload)
    const keys = Object.keys(payload || {})
    if(!keys.length) return
    if(suppressAbandonedStorageOperation('storageSet')) return false
    if(options.snapshotWriteReason) {
        recordSnapshotWriteReasonMetrics(options.snapshotWriteReason, payload)
    }
    const pathName = getStorageMetricPathName(options)
    const isProfileProgressProjectionWrite = keys.includes(PROFILE_NUKE_PROGRESS_VIEW_KEY) ||
        keys.some(key => `${key || ''}`.startsWith(PROFILE_NUKE_PROGRESS_SHARD_PREFIX))
    const isOnlyProfileProgressProjectionWrite = isProfileProgressProjectionWrite &&
        keys.every(key => key === PROFILE_NUKE_PROGRESS_VIEW_KEY ||
            `${key || ''}`.startsWith(PROFILE_NUKE_PROGRESS_SHARD_PREFIX))
    const suppressDurableIdleResume = isProfileProgressProjectionWrite &&
        /(?:^|\.)projection(?:\.|$)/.test(pathName)
    recordStoragePayloadMetrics(payload, pathName)
    recordQueueWriteOperationMetrics(payload, options)
    incrementQueueWakeupMetric('storageSetCalls')
    incrementActiveStorageMetricDetail('storageSetCalls')
    if(storageContext) {
        if(isOnlyProfileProgressProjectionWrite) {
            storageContext.profileProgressProjectionOnlyWrites =
                (Number.parseInt(storageContext.profileProgressProjectionOnlyWrites, 10) || 0) + 1
        }
        if(suppressDurableIdleResume) {
            storageContext.suppressDurableIdleResume = true
        }
        else {
            storageContext.nonProgressProjectionWrite = true
        }
    }
    const startedAt = Date.now()
    let result = null
    try {
        if(isProfileProgressProjectionWrite) profileNukeProgressProjectionWriteDepth += 1
        result = await runQueueWakeupMetricPhase(options.phase || 'storageSet', () => coordinatorStorageAdapter.set(payload))
    }
    finally {
        if(isProfileProgressProjectionWrite) {
            profileNukeProgressProjectionWriteDepth = Math.max(0, profileNukeProgressProjectionWriteDepth - 1)
        }
        recordStoragePathLatencyMetrics('write', pathName, Date.now() - startedAt)
    }
    if(isProfileProgressProjectionWrite) {
        profileNukeProgressProjectionVersion += 1
    }
    notifyCoordinatorAuthorityPersistedSnapshot(payload)
    notifyCoordinatorDashboardStateChanged(keys, pathName)
    return result
}

async function metricStorageRemove(keys = [], options = {}) {
    const normalizedKeys = Array.from(new Set((Array.isArray(keys) ? keys : [keys])
        .map(key => `${key || ''}`.trim())
        .filter(Boolean)))
    if(!normalizedKeys.length) return true
    if(suppressAbandonedStorageOperation('storageRemove')) return false

    const pathName = getStorageMetricPathName(options)
    incrementQueueWakeupMetric('storageRemoveCalls')
    incrementQueueWakeupMetric(`storageRemove.${normalizeStorageMetricPathName(pathName)}.keys`, normalizedKeys.length)
    recordQueueWakeupMetricMax(`storageRemove.${normalizeStorageMetricPathName(pathName)}.maxKeys`, normalizedKeys.length)
    incrementActiveStorageMetricDetail('storageRemoveCalls')
    setActiveStorageMetricDetail('removeKeys', normalizedKeys.slice(0, 12).join(','))
    setActiveStorageMetricDetail('removePath', normalizeStorageMetricPathName(pathName))

    const startedAt = Date.now()
    try {
        await runQueueWakeupMetricPhase(options.phase || 'storageRemove', () => coordinatorStorageAdapter.remove(normalizedKeys))
        return true
    }
    finally {
        recordStoragePathLatencyMetrics('write', pathName, Date.now() - startedAt)
    }
}

function notifyCoordinatorDashboardStateChanged(keys = [], reason = '') {
    const changedKeys = Array.from(new Set(keys || []))
        .filter(key => COORDINATOR_DASHBOARD_STATE_KEYS.has(key))
    if(!changedKeys.length) return

    void browser.runtime.sendMessage({
        action: 'coordinator-dashboard-state-changed',
        reason: normalizeStorageMetricPathName(reason),
        keys: changedKeys
    }).catch(() => {})
}

function requestPostStorageQueuedWorkContinuation(reason = 'queued-work-continuation') {
    const options = arguments[1] && typeof arguments[1] === 'object' ? arguments[1] : {}
    postStorageQueuedWorkContinuationReason = `${reason || 'queued-work-continuation'}`.trim() || 'queued-work-continuation'
    postStorageQueuedWorkContinuationForceDurableQueueReload =
        postStorageQueuedWorkContinuationForceDurableQueueReload ||
        options.forceDurableQueueReload === true
}

function flushPostStorageQueuedWorkContinuation() {
    const reason = postStorageQueuedWorkContinuationReason
    const forceDurableQueueReload = postStorageQueuedWorkContinuationForceDurableQueueReload === true
    postStorageQueuedWorkContinuationReason = ''
    postStorageQueuedWorkContinuationForceDurableQueueReload = false
    if(!reason) return false

    void kickCoordinatorQueueResume(reason, {
        backgroundFastPath: true,
        allowBeforeQuora: true,
        skipAuthorityReconcile: true,
        forceDurableQueueReload
    }).catch(() => null)
    return true
}

function isDurablyActiveQueuedTab(tabId) {
    const metadata = getQueuedTabMetadata(tabId)
    return Number.isFinite(metadata?.durableActiveAt) && metadata.durableActiveAt > 0
}

function getDurablyActiveQueuedTabCount() {
    let count = 0
    for(const tabId of queueRuntime.listActiveQueuedTabIds()) {
        if(isDurablyActiveQueuedTab(tabId)) count += 1
    }
    return count
}

function getDurablyActiveCoordinatorAuthorityRowCount() {
    const currentAuthorityState = getHydratedCoordinatorAuthorityState()
    if(!currentAuthorityState?.queue) return 0

    return getCoordinatorQueueWorkCounts(currentAuthorityState.queue).durableActiveRows
}

function getFreshQueuedTabRuntimeStartupAnchor(metadata = null) {
    return Math.max(
        Number.parseInt(metadata?.durableActiveAt, 10) || 0,
        Number.parseInt(metadata?.activeTransitionContinuedAt, 10) || 0,
        Number.parseInt(metadata?.activeTransitionUnconfirmedAt, 10) || 0,
        Number.parseInt(metadata?.activeTransitionPendingAt, 10) || 0,
        Number.parseInt(metadata?.openedAt, 10) || 0,
        Number.parseInt(metadata?.tabOpenedAt, 10) || 0,
        Number.parseInt(metadata?.tabCreatedAt, 10) || 0
    )
}

function isFreshQueuedTabRuntimeStartup(metadata = null, now = Date.now()) {
    if(!metadata || metadata?.closeRequestedAt || metadata?.closeReason) return false

    const startupAnchor = getFreshQueuedTabRuntimeStartupAnchor(metadata)
    return startupAnchor > 0 && now - startupAnchor < STALE_ACTIVE_QUEUED_TAB_MS
}

function shouldDeferQueuedTabReleaseRollback(metadata = null, now = Date.now()) {
    if(!metadata || metadata?.retryRequestedAt || metadata?.closeRequestedAt || metadata?.closeReason) return false
    if(!isFreshQueuedTabRuntimeStartup(metadata, now)) return false
    if(!Number.isFinite(metadata?.durableActiveAt) || metadata.durableActiveAt <= 0) return false

    const contentScriptRecoveryActive = Math.max(
        Number.parseInt(metadata?.contentScriptEnsureStartedAt, 10) || 0,
        Number.parseInt(metadata?.contentScriptEnsureFailedAt, 10) || 0,
        Number.parseInt(metadata?.contentScriptInjectedAt, 10) || 0,
        Number.parseInt(metadata?.contentScriptPresentAt, 10) || 0,
        Number.parseInt(metadata?.lastNudgeFailedAt, 10) || 0,
        Number.parseInt(metadata?.activeTransitionContinuedAt, 10) || 0,
        Number.parseInt(metadata?.activeTransitionUnconfirmedAt, 10) || 0
    )
    if(contentScriptRecoveryActive > 0 && now - contentScriptRecoveryActive < STALE_BACKGROUND_OPENING_QUEUED_TAB_MS) {
        return true
    }

    return storageUpdateState.getDepth() > 0
}

function queuedTabRuntimeMetadataMatchesCoordinatorItem(item = null, record = null, itemKey = '', metadata = null) {
    if(!item || !metadata) return false

    const expectedHref = getCoordinatorItemHref(item) ||
        normalizeQuoraProfileUrl(itemKey) ||
        normalizeQuoraProfileUrl(record?.profileHref || '')
    const metadataHref = normalizeQuoraProfileUrl(metadata.profileHref || metadata.targetProfileHref || metadata.requestedUrl || '')
    if(expectedHref && metadataHref && metadataHref !== expectedHref) return false

    const expectedCoordinatorKey = getCoordinatorItemQueueKey(item, itemKey)
    const metadataCoordinatorKey = `${metadata.coordinatorKey || ''}`.trim()
    if(expectedCoordinatorKey && metadataCoordinatorKey && metadataCoordinatorKey !== expectedCoordinatorKey) return false

    const expectedAttemptId = getAttemptIdFromValue(item) || getAttemptIdFromValue(record)
    const expectedAttemptNumber = getAttemptNumberFromValue(item) || getAttemptNumberFromValue(record)
    const metadataAttemptId = getAttemptIdFromValue(metadata)
    const metadataAttemptNumber = getAttemptNumberFromValue(metadata)
    if(expectedAttemptId && metadataAttemptId !== expectedAttemptId) return false
    if(expectedAttemptNumber && metadataAttemptNumber !== expectedAttemptNumber) return false

    const expectedActionKind = getCoordinatorActionKindForRequestedAction(
        item.actionKind ||
        item.executorTabAction ||
        item.tabAction ||
        record?.actionKind ||
        ''
    )
    const metadataActionKind = getCoordinatorActionKindForRequestedAction(metadata.actionKind || metadata.tabAction || '')
    if(expectedActionKind && metadataActionKind && metadataActionKind !== expectedActionKind) return false

    return true
}

function getFreshQueuedTabStartupRuntimeActorForCoordinatorItem(
    item = null,
    record = null,
    itemKey = '',
    now = Date.now(),
    expectedTabId = null,
    options = {}
) {
    if(!item || !isActiveCoordinatorStatus(item?.status)) return null

    const requireDurable = options.requireDurable !== false
    const candidateTabIds = expectedTabId
        ? [normalizeTabId(expectedTabId)]
        : queueRuntime.listActiveQueuedTabIds()
    for(const candidateTabId of candidateTabIds) {
        const tabId = normalizeTabId(candidateTabId)
        if(!tabId || !queueRuntime.hasActiveQueuedTab(tabId)) continue
        if(requireDurable && !isDurablyActiveQueuedTab(tabId)) continue

        const metadata = getQueuedTabMetadata(tabId)
        if(!isFreshQueuedTabRuntimeStartup(metadata, now)) continue
        if(!queuedTabRuntimeMetadataMatchesCoordinatorItem(item, record, itemKey, metadata)) continue

        return {tabId, metadata}
    }

    return null
}

function getSchedulerBlockingQueuedExecutorCount() {
    return Math.max(
        getDurablyActiveQueuedTabCount(),
        getDurablyActiveCoordinatorAuthorityRowCount()
    )
}

async function getLiveQueuedWorkerSurfaceProfileTabCount(targetProfileHref = '') {
    if(!browser.tabs?.query) return 0

    const normalizedTargetProfileHref = normalizeQuoraProfileUrl(targetProfileHref || '')
    const tabs = await browser.tabs.query({}).catch(() => [])
    const tabsByWindow = new Map()
    const surfaceWindowIds = new Set()
    const addSurfaceWindowId = value => {
        const windowId = Number.parseInt(value, 10) || 0
        if(windowId) surfaceWindowIds.add(windowId)
    }

    addSurfaceWindowId(queuedActionSurfaceWindowId)
    for(const tab of tabs || []) {
        const windowId = Number.parseInt(tab?.windowId, 10) || 0
        if(!windowId) continue
        if(!tabsByWindow.has(windowId)) tabsByWindow.set(windowId, [])
        tabsByWindow.get(windowId).push(tab)
        if(isQueuedWorkerActionSurfaceUrl(tab?.url || '')) addSurfaceWindowId(windowId)
    }

    for(const tabId of queueRuntime.listActiveQueuedTabIds()) {
        const metadata = getQueuedTabMetadata(tabId)
        addSurfaceWindowId(metadata?.actionSurfaceWindowId)
        addSurfaceWindowId(metadata?.ownerWindowId)
    }
    for(const action of queueRuntime.listPendingTabActions()) {
        if(action?.actionSurfaceMode !== 'worker-window') continue
        addSurfaceWindowId(action?.actionSurfaceWindowId)
        addSurfaceWindowId(action?.ownerWindowId)
    }
    for(const action of queueRuntime.listActivationIntents()) {
        if(action?.actionSurfaceMode !== 'worker-window') continue
        addSurfaceWindowId(action?.actionSurfaceWindowId)
        addSurfaceWindowId(action?.ownerWindowId)
    }

    let count = 0
    for(const windowId of surfaceWindowIds) {
        const windowTabs = tabsByWindow.get(windowId) || []
        for(const tab of windowTabs) {
            const tabProfileHref = normalizeQuoraProfileUrl(tab?.url || '')
            if(!tabProfileHref) continue
            if(normalizedTargetProfileHref && tabProfileHref !== normalizedTargetProfileHref) continue
            count += 1
        }
    }
    return count
}

async function getLiveQueuedProfileTabCount() {
    if(!browser.tabs?.query) return 0

    const tabs = await browser.tabs.query({}).catch(() => [])
    return (tabs || []).filter(tab => normalizeQuoraProfileUrl(tab?.url || '')).length
}

const activationGuardRuntime = createActivationGuardRuntime({
    now: () => Date.now(),
    constants: {
        QUEUED_PROFILE_OPEN_RESERVATION_TTL_MS,
        QUEUED_ACTIVATION_GUARD_TTL_MS,
        SERVICE_WORKER_QUEUE_OWNER_ID
    },
    handlers: {
        queueRuntime,
        incrementQueueWakeupMetric,
        pushQueueWakeupJournalEntry,
        recordFlightRecorderEvent,
        normalizeQuoraProfileUrl,
        normalizeTabId,
        getCoordinatorItemQueueKey,
        getAttemptIdFromValue,
        getAttemptNumberFromValue,
        getCoordinatorActionKindForRequestedAction,
        getCoordinatorItemHref,
        getQueuedTabActionKey,
        getCoordinatorItemExecutorTabAction,
        queuedRuntimeActionHasActiveOrPendingSurface,
        shouldDropQueuedActionForCurrentAuthority
    },
    state: {
        getCoordinatorAuthority: () => coordinatorAuthority
    }
})
const {
    pruneQueuedProfileOpenReservations,
    getQueuedProfileOpenReservationCount,
    clearDetachedQueuedProfileOpenReservations,
    getQueuedProfileOpenReservationKey,
    reserveQueuedProfileOpen,
    releaseQueuedProfileOpenReservation,
    getQueuedActivationGuardKey,
    getQueuedRuntimeActionSubjectHref,
    getQueuedRuntimeActionFillKey,
    pruneQueuedActivationGuards,
    hasQueuedActivationGuard,
    claimQueuedActivationGuard,
    releaseQueuedActivationGuard,
    releaseQueuedActivationGuardForTab,
    filterRestorableActivationIntents,
    pruneDuplicateQueuedTabActions,
    mergeActivationGuardTabInfo,
    deleteActivationGuardByKey
} = activationGuardRuntime

function markQueuedTabDurablyActive(tabId, reason = '') {
    const metadata = getQueuedTabMetadata(tabId)
    const durableActiveAt = Number.isFinite(metadata?.durableActiveAt) && metadata.durableActiveAt > 0
        ? metadata.durableActiveAt
        : Date.now()
    setQueuedTabMetadata(tabId, {
        durableActiveAt,
        durableActiveReason: `${reason || ''}`.trim()
    })
}

function getCoordinatorQueueWorkCounts(queue = {}) {
    const counts = {
        durableActiveRows: 0,
        durableQueuedRows: 0,
        durableTerminalRows: 0
    }

    for(const item of Object.values(queue || {})) {
        if(isTerminalCoordinatorStatus(item?.status)) counts.durableTerminalRows += 1
        else if(isActiveCoordinatorStatus(item?.status)) counts.durableActiveRows += 1
        else if(`${item?.status || ''}` === 'queued') counts.durableQueuedRows += 1
    }

    return counts
}

function getCoordinatorAuthorityMismatchCounts(queue = {}, progress = {}, liveProfileTabsByHref = new Map(), options = {}) {
    const rowBudget = Math.max(1, Number.parseInt(options.rowBudget, 10) || COORDINATOR_RECONCILE_OBSERVE_ROW_BUDGET)
    const counts = {
        durableActiveWithoutActor: 0,
        durableActiveObserved: 0,
        provisionalActorWithoutDurable: 0,
        runtimeActorsObserved: queueRuntime.getActiveQueuedTabCount(),
        rowBudgetExceeded: false
    }
    const activeEntries = []

    for(const [itemKey, item] of Object.entries(queue || {})) {
        if(!isActiveCoordinatorStatus(item?.status)) continue
        if(activeEntries.length >= rowBudget) {
            counts.rowBudgetExceeded = true
            break
        }

        const record = getCoordinatorProgressRecordForItem(itemKey, item, progress)
        activeEntries.push({itemKey, item, record})
        counts.durableActiveObserved += 1
        if(!hasConfirmedLiveRuntimeActorForCoordinatorItem(item, record, liveProfileTabsByHref)) {
            counts.durableActiveWithoutActor += 1
        }
    }

    for(const tabId of queueRuntime.listActiveQueuedTabIds()) {
        if(!isDurablyActiveQueuedTab(tabId)) {
            counts.provisionalActorWithoutDurable += 1
            continue
        }

        const matched = activeEntries.some(({item, record}) => {
            const persistedTabId = getPersistedQueuedTabId(item, record)
            return persistedTabId === tabId && hasConfirmedRuntimeActorForCoordinatorItem(item, record)
        })
        if(!matched) counts.provisionalActorWithoutDurable += 1
    }

    return counts
}

function getCoordinatorReconcileActionBudget(options = {}) {
    return Math.max(1, Number.parseInt(options.actionBudget, 10) || COORDINATOR_RECONCILE_ACTION_BUDGET)
}

function getTokenMatchedLiveTabForCoordinatorItem(item = null, record = null, itemKey = '', liveProfileTabsByHref = new Map()) {
    const tabId = getPersistedQueuedTabId(item, record)
    const expectedAttemptId = getAttemptIdFromValue(item) || getAttemptIdFromValue(record)
    const expectedAttemptNumber = getAttemptNumberFromValue(item) || getAttemptNumberFromValue(record)
    if(!tabId || !expectedAttemptId || !expectedAttemptNumber) return null

    const href = getCoordinatorItemHref(item) || normalizeQuoraProfileUrl(itemKey) || normalizeQuoraProfileUrl(record?.profileHref || '')
    const candidates = href ? getLiveTabsForProfileHref(liveProfileTabsByHref, href) : []
    return candidates.find(tab => normalizeTabId(tab?.id) === tabId) || null
}

function hasActiveCoordinatorMilestoneEvidence(item = null) {
    const milestones = item?.milestones || {}
    return getFirstPositiveNumber(
        milestones.actionClaimedAt,
        milestones.contentOpenedAt,
        milestones.navigationStartedAt,
        milestones.profileReadyAt,
        milestones.muteAttemptedAt,
        milestones.blockAttemptedAt,
        item?.activeAt
    ) > 0
}

function hasStrongActiveCoordinatorReclaimEvidence(item = null, record = null) {
    const milestones = item?.milestones || {}
    return getFirstPositiveNumber(
        milestones.actionClaimedAt,
        milestones.contentOpenedAt,
        milestones.profileReadyAt,
        milestones.muteAttemptedAt,
        milestones.blockAttemptedAt,
        item?.actionClaimedAt,
        item?.contentOpenedAt,
        item?.profileReadyAt,
        item?.muteAttemptedAt,
        item?.blockAttemptedAt,
        record?.actionReadyAt,
        record?.contentOpenedAt,
        record?.profileReadyAt,
        record?.muteAttemptedAt,
        record?.blockAttemptedAt
    ) > 0
}

function getLiveProfileTabForActiveCoordinatorReclaim(item = null, record = null, itemKey = '', liveProfileTabsByHref = new Map()) {
    if(!item || !isActiveCoordinatorStatus(item.status)) return null
    if(isTerminalProfileNukeRecord(record)) return null
    if(hasConfirmedRuntimeActorForCoordinatorItem(item, record)) return null
    if(normalizeCoordinatorActionLease(item.actionLease)) return null
    if(!hasActiveCoordinatorMilestoneEvidence(item)) return null
    const actionPhaseActive = hasActiveQueuedTabActionPhaseProgress(record, item)
    if((actionPhaseActive || getPersistedQueuedTabId(item, record)) &&
        !hasStrongActiveCoordinatorReclaimEvidence(item, record)) {
        return null
    }

    const expectedAttemptId = getAttemptIdFromValue(item)
    const expectedAttemptNumber = getAttemptNumberFromValue(item)
    if(!expectedAttemptId || !expectedAttemptNumber) return null

    const href = getCoordinatorItemHref(item) || normalizeQuoraProfileUrl(itemKey) || normalizeQuoraProfileUrl(record?.profileHref || '')
    const candidates = href ? getLiveTabsForProfileHref(liveProfileTabsByHref, href) : []
    if(candidates.length !== 1) return null

    const candidate = candidates[0]
    const candidateTabId = normalizeTabId(candidate?.id)
    if(!candidateTabId || hasOwnedQueuedTabState(candidateTabId)) return null

    return candidate
}

function chooseCoordinatorReclaimProfileTab(candidates = []) {
    return [...(candidates || [])]
        .filter(tab => normalizeTabId(tab?.id) && !hasOwnedQueuedTabState(tab.id))
        .sort((left, right) => {
            const activeDelta = (right?.active === true ? 1 : 0) - (left?.active === true ? 1 : 0)
            if(activeDelta) return activeDelta

            const accessedDelta = (Number.parseInt(right?.lastAccessed, 10) || 0) -
                (Number.parseInt(left?.lastAccessed, 10) || 0)
            if(accessedDelta) return accessedDelta

            return normalizeTabId(right?.id) - normalizeTabId(left?.id)
        })[0] || null
}

function mergeLiveTabsById(...lists) {
    const merged = []
    const seen = new Set()
    for(const list of lists) {
        for(const tab of list || []) {
            const tabId = normalizeTabId(tab?.id)
            if(!tabId || seen.has(tabId)) continue
            seen.add(tabId)
            merged.push(tab)
        }
    }
    return merged
}

function isQueuedCoordinatorLiveTabReclaimReason(reason = '') {
    const normalizedReason = `${reason || ''}`.trim()
    return normalizedReason === 'active-transition-failed' ||
        /(?:^|-)queued-live-tab-adoption-load-pressure(?:-|$)/.test(normalizedReason) ||
        /(?:^|-)active-transition-retry-budget-recovered(?:-|$)/.test(normalizedReason) ||
        /active-missing-tab$/.test(normalizedReason)
}

function getLiveProfileTabForRolledBackQueuedCoordinatorReclaim(item = null, record = null, itemKey = '', liveProfileTabsByHref = new Map()) {
    if(!item || `${item.status || ''}`.trim() !== 'queued') return null
    if(!isQueuedCoordinatorLiveTabReclaimReason(item.actionLeaseReleaseReason)) return null
    if(isTerminalProfileNukeRecord(record)) return null
    if(hasActiveQueuedTabActionPhaseProgress(record, item)) return null

    const expectedAttemptId = getAttemptIdFromValue(item)
    const expectedAttemptNumber = getAttemptNumberFromValue(item)
    if(!expectedAttemptId || !expectedAttemptNumber) return null

    const href = getCoordinatorItemHref(item) || normalizeQuoraProfileUrl(itemKey) || normalizeQuoraProfileUrl(record?.profileHref || '')
    const candidates = href ? getLiveTabsForProfileHref(liveProfileTabsByHref, href) : []
    return chooseCoordinatorReclaimProfileTab(candidates)
}

async function getQueuedExecutorTabStatusWithTimeout(tabId = null, reason = 'queued-executor-tab-get') {
    const normalizedTabId = normalizeTabId(tabId)
    if(!normalizedTabId) {
        return {
            tab: null,
            found: false,
            missing: false,
            timedOut: false,
            error: 'missing-tab-id'
        }
    }

    try {
        const tab = await promiseWithTimeout(
            browser.tabs.get(normalizedTabId),
            QUEUED_TAB_GET_TIMEOUT_MS,
            `${reason || 'queued-executor-tab-get'} ${normalizedTabId}`
        )
        return {
            tab: tab || null,
            found: !!tab,
            missing: !tab,
            timedOut: false,
            error: ''
        }
    }
    catch(error) {
        const message = error?.message || `${error || ''}`
        const timedOut = /timed out/i.test(message)
        incrementQueueWakeupMetric('job.tabGetFailed')
        if(timedOut) {
            incrementQueueWakeupMetric('job.tabGetTimedOut')
            const queryResult = await getQueuedExecutorTabStatusFromTabList(normalizedTabId, reason)
            if(queryResult.found || queryResult.missing) {
                return {
                    ...queryResult,
                    timedOut: true,
                    error: message
                }
            }
        }
        return {
            tab: null,
            found: false,
            missing: !timedOut && /no tab|no fake tab|invalid tab|cannot find tab|not found/i.test(message),
            timedOut,
            error: message
        }
    }
}

async function getQueuedExecutorTabStatusFromTabList(tabId = null, reason = 'queued-executor-tab-list') {
    const normalizedTabId = normalizeTabId(tabId)
    if(!normalizedTabId) {
        return {
            tab: null,
            found: false,
            missing: false,
            timedOut: false,
            error: 'missing-tab-id'
        }
    }

    try {
        const tabs = await promiseWithTimeout(
            browser.tabs.query({}),
            QUEUED_TAB_GET_TIMEOUT_MS,
            `${reason || 'queued-executor-tab-list'} tab-list ${normalizedTabId}`
        )
        const tab = (tabs || []).find(candidate => normalizeTabId(candidate?.id) === normalizedTabId) || null
        return {
            tab,
            found: !!tab,
            missing: !tab,
            timedOut: false,
            error: ''
        }
    }
    catch(error) {
        const message = error?.message || `${error || ''}`
        const timedOut = /timed out/i.test(message)
        if(timedOut) incrementQueueWakeupMetric('job.tabListTimedOut')
        return {
            tab: null,
            found: false,
            missing: false,
            timedOut,
            error: message
        }
    }
}

async function getQueuedExecutorTabWithTimeout(tabId = null, reason = 'queued-executor-tab-get') {
    const result = await getQueuedExecutorTabStatusWithTimeout(tabId, reason)
    return result.tab || null
}

function getCoordinatorItemExpectedExecutorHref(item = null, record = null, itemKey = '') {
    return getCoordinatorItemHref(item) ||
        normalizeQuoraProfileUrl(itemKey) ||
        normalizeQuoraProfileUrl(record?.profileHref || '')
}

function getCoordinatorItemExpectedExecutorUrl(item = null, record = null, itemKey = '') {
    return normalizeCoordinatorRequestedUrl(
        item?.requestedUrl ||
        getCoordinatorItemOpenUrl(item) ||
        getCoordinatorItemExpectedExecutorHref(item, record, itemKey) ||
        record?.requestedUrl ||
        record?.profileHref ||
        ''
    )
}

function getTabObservedUrls(tab = null) {
    return [
        tab?.url,
        tab?.pendingUrl
    ]
        .map(value => `${value || ''}`.trim())
        .filter(Boolean)
}

function isBlankOrUncommittedTabUrl(value = '') {
    return /^(?:about:blank|about:newtab)$/i.test(`${value || ''}`.trim())
}

function isBrowserErrorTabUrl(value = '') {
    return /^(?:chrome|edge)-error:/i.test(`${value || ''}`.trim())
}

function isCoordinatorProfileLandingWork(item = null, itemKey = '', record = null) {
    const href = getCoordinatorItemExpectedExecutorHref(item, record, itemKey)
    return !!href && !isProfileResolutionItem(item)
}

function shouldTerminalizeCoordinatorNonProfileLanding(item = null, record = null, itemKey = '', landingUrl = '') {
    if(!item || typeof item !== 'object') return false
    if(!isActiveCoordinatorStatus(item.status)) return false
    if(isTerminalProfileNukeRecord(record)) return false
    if(hasActiveQueuedTabActionPhaseProgress(record, item)) return false
    if(!isCoordinatorProfileLandingWork(item, itemKey, record)) return false
    return isNonProfileQuoraHttpLandingUrl(landingUrl || record?.lastUrl || record?.errorPageUrl || '')
}

function isSafeToCloseNonProfileLandingTab(item = null, record = null, tab = null) {
    const tabId = normalizeTabId(tab?.id)
    if(!tabId || getPersistedQueuedTabId(item, record) !== tabId) return false
    if(!isNonProfileQuoraHttpLandingUrl(tab?.url || tab?.pendingUrl || '')) return false
    if(hasOwnedQueuedTabState(tabId)) return true

    const actionSurfaceWindowId = Number.parseInt(
        record?.actionSurfaceWindowId ||
        item?.actionSurfaceWindowId ||
        item?.ownerWindowId,
        10
    ) || 0
    return !!actionSurfaceWindowId && Number.parseInt(tab?.windowId, 10) === actionSurfaceWindowId
}

function getPersistedExecutorObservedAgeMs(item = null, record = null, now = Date.now()) {
    const anchor = getPersistedActiveCoordinatorStaleAnchor(item, record)
    if(!anchor || anchor > now) return Number.POSITIVE_INFINITY
    return now - anchor
}

function isPersistedLiveTabPlausibleForCoordinatorItem(item = null, record = null, itemKey = '', tab = null, now = Date.now()) {
    const tabId = getPersistedQueuedTabId(item, record)
    if(!tabId || normalizeTabId(tab?.id) !== tabId) return false

    const expectedHref = getCoordinatorItemExpectedExecutorHref(item, record, itemKey)
    const expectedUrl = getCoordinatorItemExpectedExecutorUrl(item, record, itemKey)
    const observedUrls = getTabObservedUrls(tab)
    for(const observedUrl of observedUrls) {
        if(expectedHref && normalizeQuoraProfileUrl(observedUrl) === expectedHref) return true
        if(expectedUrl &&
            (isProfileResolutionItem(item) || !expectedHref) &&
            normalizeCoordinatorRequestedUrl(observedUrl) === expectedUrl) {
            return true
        }
    }
    if(expectedHref && !isProfileResolutionItem(item)) {
        if(observedUrls.some(isNonProfileQuoraHttpLandingUrl)) return false
    }

    if(hasConfirmedRuntimeActorForCoordinatorItem(item, record)) return true

    const ageMs = getPersistedExecutorObservedAgeMs(item, record, now)
    const freshTransient = ageMs <= PERSISTED_EXECUTOR_TRANSIENT_URL_MAX_AGE_MS
    if(!freshTransient) return false

    if(observedUrls.some(isBlankOrUncommittedTabUrl)) return true
    if(observedUrls.some(isQuoraChallengeLikeUrl)) return true
    if(observedUrls.some(isBrowserErrorTabUrl) && (
        isExplicitSecurityVerificationRecord(record) ||
        isQuoraHttpUrl(record?.lastUrl || '') ||
        isQuoraHttpUrl(record?.errorPageUrl || '') ||
        !!expectedHref ||
        !!expectedUrl
    )) {
        return true
    }

    return false
}

async function getPersistedLiveTabForCoordinatorItem(item = null, record = null, itemKey = '') {
    const result = await getPersistedLiveTabStatusForCoordinatorItem(item, record, itemKey)
    return result.tab || null
}

async function getPersistedLiveTabStatusForCoordinatorItem(item = null, record = null, itemKey = '') {
    const tabId = getPersistedQueuedTabId(item, record)
    const expectedAttemptId = getAttemptIdFromValue(item) || getAttemptIdFromValue(record)
    const expectedAttemptNumber = getAttemptNumberFromValue(item) || getAttemptNumberFromValue(record)
    if(!tabId || !expectedAttemptId || !expectedAttemptNumber) {
        return {
            tab: null,
            found: false,
            missing: false,
            timedOut: false,
            error: 'missing-persisted-tab-identity'
        }
    }

    const result = await getQueuedExecutorTabStatusWithTimeout(tabId, 'persisted-live-tab')
    if(!result.tab) return result
    if(isPersistedLiveTabPlausibleForCoordinatorItem(item, record, itemKey, result.tab)) return result

    return {
        ...result,
        tab: null,
        found: false,
        missing: false,
        timedOut: false,
        implausible: true,
        error: result.error || 'persisted-tab-implausible'
    }
}

async function getTokenMatchedLiveOrPersistedTabForCoordinatorItem(item = null, record = null, itemKey = '', liveProfileTabsByHref = new Map()) {
    return getTokenMatchedLiveTabForCoordinatorItem(item, record, itemKey, liveProfileTabsByHref) ||
        await getPersistedLiveTabForCoordinatorItem(item, record, itemKey)
}

function shouldTreatTimedOutPersistedTabLookupAsMissingForStaleActive(item = null, record = null, status = null, now = Date.now()) {
    if(!status?.timedOut) return false
    if(!item || !isActiveCoordinatorStatus(item.status)) return false
    if(isTerminalProfileNukeRecord(record)) return false
    if(hasConfirmedRuntimeActorForCoordinatorItem(item, record)) return false
    if(!getPersistedQueuedTabId(item, record)) return false

    return isActorlessActiveCoordinatorJobExpired(item, record, now) ||
        isDurableActiveCoordinatorReclaimStale(item, record, now)
}

function shouldDeferActiveWithoutActorReconcileForPersistedTabStatus(status = null, item = null, record = null, now = Date.now()) {
    if(shouldTreatTimedOutPersistedTabLookupAsMissingForStaleActive(item, record, status, now)) {
        incrementQueueWakeupMetric('reconcile.persistedTabLookupTimeoutTreatedMissing')
        return false
    }

    return !!(status?.timedOut ||
        (status?.error &&
            status.error !== 'missing-persisted-tab-identity' &&
            !status.missing &&
            !status.implausible))
}

async function getActionPhaseLiveTabProtectionForCoordinatorItem(item = null, record = null, itemKey = '') {
    if(!hasActiveQueuedTabActionPhaseProgress(record, item)) {
        return {
            protected: false,
            reason: 'not-action-phase-progress'
        }
    }
    if(isQueuedTabAttemptBudgetExhausted(item, record)) {
        return {
            protected: false,
            reason: 'action-phase-progress-retry-budget-exhausted'
        }
    }

    const persistedTabStatus = await getPersistedLiveTabStatusForCoordinatorItem(item, record, itemKey)
    if(persistedTabStatus.tab) {
        return {
            protected: true,
            reason: 'action-phase-progress-live-tab',
            tabStatus: persistedTabStatus
        }
    }
    if(shouldDeferActiveWithoutActorReconcileForPersistedTabStatus(persistedTabStatus)) {
        scheduleCoordinatorQueueResume(1000, 'action-phase-progress-persisted-tab-lookup-deferred', {
            allowBeforeQuora: true
        })
        return {
            protected: true,
            reason: persistedTabStatus.timedOut
                ? 'action-phase-progress-tab-lookup-timeout'
                : 'action-phase-progress-tab-lookup-deferred',
            error: persistedTabStatus.error || '',
            tabStatus: persistedTabStatus
        }
    }

    return {
        protected: false,
        reason: persistedTabStatus.missing
            ? 'action-phase-progress-tab-missing'
            : persistedTabStatus.error || 'action-phase-progress-tab-not-live',
        tabStatus: persistedTabStatus
    }
}

function getQueuedTabActorReadinessAnchor(item = null, record = null, metadata = null) {
    return Math.max(
        Number.parseInt(metadata?.contentScriptPresentAt, 10) || 0,
        Number.parseInt(metadata?.contentScriptInjectedAt, 10) || 0,
        Number.parseInt(metadata?.contentScriptEnsureStartedAt, 10) || 0,
        Number.parseInt(metadata?.durableActiveAt, 10) || 0,
        Number.parseInt(metadata?.activeTransitionContinuedAt, 10) || 0,
        Number.parseInt(metadata?.activeTransitionUnconfirmedAt, 10) || 0,
        Number.parseInt(metadata?.activeTransitionPendingAt, 10) || 0,
        Number.parseInt(metadata?.openedAt, 10) || 0,
        Number.parseInt(metadata?.tabOpenedAt, 10) || 0,
        Number.parseInt(metadata?.tabCreatedAt, 10) || 0,
        Number.parseInt(record?.contentOpenedAt, 10) || 0,
        Number.parseInt(record?.tabOpenedAt, 10) || 0,
        Number.parseInt(record?.tabCreatedAt, 10) || 0,
        Number.parseInt(item?.activeAt, 10) || 0
    )
}

function summarizeQueuedTabStatusForRecorder(status = null) {
    const tab = status?.tab || null
    return {
        found: status?.found === true,
        missing: status?.missing === true,
        timedOut: status?.timedOut === true,
        implausible: status?.implausible === true,
        error: status?.error || '',
        tabUrl: tab?.url || '',
        tabPendingUrl: tab?.pendingUrl || '',
        tabStatus: tab?.status || '',
        tabTitle: tab?.title || '',
        tabWindowId: tab?.windowId || null
    }
}

async function deferActiveWithoutActorForFreshContentReadiness(itemKey = '', expectedItem = null, expectedRecord = null, reason = 'reconcile-active-without-actor', options = {}) {
    const tabId = getPersistedQueuedTabId(expectedItem, expectedRecord)
    if(!tabId) return {deferred: false, reason: 'missing-tab-id'}

    const href = getCoordinatorItemHref(expectedItem) ||
        normalizeQuoraProfileUrl(itemKey) ||
        normalizeQuoraProfileUrl(expectedRecord?.profileHref || '')
    const metadata = getQueuedTabMetadata(tabId) || null
    const tabStatus = await getQueuedExecutorTabStatusWithTimeout(tabId, 'queued-tab-runtime-missing')
    const now = Date.now()
    const readinessAnchor = getQueuedTabActorReadinessAnchor(expectedItem, expectedRecord, metadata)
    const readinessAgeMs = readinessAnchor ? now - readinessAnchor : Number.POSITIVE_INFINITY
    const insideReadinessWindow = readinessAnchor > 0 &&
        readinessAgeMs >= 0 &&
        readinessAgeMs < QUEUED_TAB_CONTENT_ACTOR_READINESS_WINDOW_MS

    recordFlightRecorderEvent({
        kind: 'queued-tab-runtime-missing',
        source: 'deferActiveWithoutActorForFreshContentReadiness',
        rowKey: itemKey,
        targetUrl: href || itemKey,
        attemptId: getAttemptIdFromValue(expectedItem),
        attemptNumber: getAttemptNumberFromValue(expectedItem),
        runId: expectedItem?.runId || '',
        tabId,
        accepted: !!tabStatus.tab && insideReadinessWindow,
        reason,
        readinessAgeMs: Number.isFinite(readinessAgeMs) ? readinessAgeMs : -1,
        readinessWindowMs: QUEUED_TAB_CONTENT_ACTOR_READINESS_WINDOW_MS,
        ...summarizeQueuedTabStatusForRecorder(tabStatus)
    })

    if(!tabStatus.tab || !insideReadinessWindow) {
        return {
            deferred: false,
            reason: tabStatus.tab
                ? 'content-actor-readiness-window-expired'
                : tabStatus.missing
                ? 'tab-missing'
                : tabStatus.timedOut
                ? 'tab-lookup-timeout'
                : tabStatus.error || 'tab-not-found',
            tabStatus
        }
    }

    let adopted = false
    if(!hasOwnedQueuedTabState(tabId)) {
        adopted = await adoptLiveCoordinatorQueuedTab(
            expectedItem,
            itemKey,
            tabStatus.tab,
            SERVICE_WORKER_QUEUE_OWNER_ID,
            {currentAuthorityState: options.currentAuthorityState || null}
        ).catch(() => false)
    }

    const ensureResult = await promiseWithTimeout(
        ensureQueuedTabContentScript(tabId, `${reason || 'actorless'}-runtime-missing-readiness`),
        QUEUED_TAB_CONTENT_SCRIPT_ENSURE_TIMEOUT_MS,
        'queued tab runtime missing content readiness'
    ).catch(error => ({
        ensured: false,
        reason: 'content-readiness-ensure-timeout',
        error: error?.message || `${error || ''}`
    }))

    setQueuedTabMetadata(tabId, {
        actorReadinessDeferredAt: now,
        actorReadinessDeferredReason: reason,
        actorReadinessEnsureReason: ensureResult?.reason || ensureResult?.nudge?.reason || '',
        actorReadinessEnsureError: ensureResult?.error || '',
        actorReadinessAdopted: adopted === true
    })

    recordFlightRecorderEvent({
        kind: 'queued-tab-runtime-missing',
        source: 'deferActiveWithoutActorForFreshContentReadiness',
        rowKey: itemKey,
        targetUrl: href || itemKey,
        attemptId: getAttemptIdFromValue(expectedItem),
        attemptNumber: getAttemptNumberFromValue(expectedItem),
        runId: expectedItem?.runId || '',
        tabId,
        accepted: true,
        changed: adopted === true || ensureResult?.ensured === true,
        reason: ensureResult?.reason || ensureResult?.nudge?.reason || 'content-actor-readiness-deferred',
        adopted: adopted === true,
        ensured: ensureResult?.ensured === true,
        nudged: ensureResult?.nudge?.nudged === true,
        injected: ensureResult?.injected === true,
        alreadyPresent: ensureResult?.alreadyPresent === true,
        reloaded: ensureResult?.reloaded === true,
        ensureError: ensureResult?.error || ''
    })

    scheduleCoordinatorQueueResume(1500, `${reason || 'actorless'}-content-readiness-deferred`, {
        allowBeforeQuora: true
    })
    scheduleCoordinatorReconcile(2000, {
        reason: `${reason || 'actorless'}-content-readiness-deferred`,
        edgeTriggered: true,
        allowBeforeQuora: true
    })
    return {
        deferred: true,
        reason: 'content-actor-readiness-deferred',
        adopted,
        ensureResult,
        tabStatus
    }
}

function getFreshWorkerWindowStartupProgressAnchor(item = null, record = null) {
    return Math.max(
        Number.parseInt(record?.actionSurfaceActivatedAt, 10) || 0,
        Number.parseInt(record?.tabOpenedAt, 10) || 0,
        Number.parseInt(record?.tabCreatedAt, 10) || 0,
        Number.parseInt(item?.activeAt, 10) || 0,
        Number.parseInt(item?.updatedAt, 10) || 0
    )
}

function hasFreshWorkerWindowStartupProgressForCoordinatorItem(item = null, record = null, now = Date.now()) {
    if(!item || !isActiveCoordinatorStatus(item.status)) return false
    if(!record || isTerminalProfileNukeRecord(record)) return false
    if(hasMismatchedCoordinatorAttempt(item, record)) return false
    if(hasActiveQueuedTabActionPhaseProgress(record, item)) return false

    const actionSurfaceMode = `${record.actionSurfaceMode || item.actionSurfaceMode || ''}`.trim()
    if(actionSurfaceMode !== 'worker-window') return false
    if(item.executorNoForegroundFallback !== true && record.noForegroundFallback !== true) return false
    if(record.closeRequestedAt || record.slotReleasedAt || record.terminalAt) return false

    const status = `${record.status || ''}`.trim()
    if(status && status !== 'tab-opening' && status !== 'tab-opened') return false

    const startupAnchor = getFreshWorkerWindowStartupProgressAnchor(item, record)
    return startupAnchor > 0 && now - startupAnchor < STALE_ACTIVE_QUEUED_TAB_MS
}

function isActorlessActiveCoordinatorJobExpired(item = null, record = null, now = Date.now()) {
    if(!item || !isActiveCoordinatorStatus(item.status)) return false
    if(isTerminalProfileNukeRecord(record)) return false
    if(hasConfirmedRuntimeActorForCoordinatorItem(item, record)) return false

    const actionPhaseActive = hasActiveQueuedTabActionPhaseProgress(record, item)
    const activeStartedAt = actionPhaseActive
        ? getActiveQueuedTabAgeAnchor(item, record)
        : Number.isFinite(item?.activeAt) ? item.activeAt : 0
    const activeJobMaxMs = actionPhaseActive
        ? COORDINATOR_ACTIVE_ACTION_JOB_MAX_MS
        : COORDINATOR_ACTIVE_JOB_MAX_MS

    return activeStartedAt > 0 && now - activeStartedAt >= activeJobMaxMs
}

function isDurableActiveCoordinatorReclaimStale(item = null, record = null, now = Date.now()) {
    const staleAnchor = getPersistedActiveCoordinatorStaleAnchor(item, record)
    if(!staleAnchor) return true

    const timeoutMs = hasActiveQueuedTabActionPhaseProgress(record, item)
        ? COORDINATOR_ACTIVE_ACTION_JOB_MAX_MS
        : COORDINATOR_ACTIVE_JOB_MAX_MS
    return now - staleAnchor >= timeoutMs
}

function isQueuedTabAttemptBudgetExhausted(item = null, record = null) {
    const retryAttempt = getQueuedTabRetryAttempt(item, record)
    const maxRetries = getQueuedTabMaxRetries(item, record)
    const attemptNumber = getAttemptNumberFromValue(item) || getAttemptNumberFromValue(record)
    const itemMaxAttempts = Number.parseInt(item?.maxAttempts || item?.attempt?.max, 10)
    const recordMaxAttempts = Number.parseInt(record?.maxAttempts || record?.attempt?.max, 10)
    const configuredMaxAttempts = maxRetries + 1
    const storedMaxAttempts = Math.max(
        Number.isFinite(itemMaxAttempts) && itemMaxAttempts > 0 ? itemMaxAttempts : 0,
        Number.isFinite(recordMaxAttempts) && recordMaxAttempts > 0 ? recordMaxAttempts : 0
    )
    const maxAttempts = Math.max(configuredMaxAttempts, storedMaxAttempts)
    return retryAttempt >= maxRetries ||
        (attemptNumber > 0 && attemptNumber >= maxAttempts)
}

function isQueuedAuthorityNoSurfaceRetryBudgetExhausted(item = null, record = null) {
    if(isQueuedTabAttemptBudgetExhausted(item, record)) return true

    const attemptNumber = getAttemptNumberFromValue(item) || getAttemptNumberFromValue(record)
    const maxRetries = getQueuedTabMaxRetries(item, record)
    return attemptNumber > 0 && attemptNumber >= maxRetries + 1
}

function hasDurableQueueMatchForRuntimeTab(tabId = null, queue = {}, progress = {}) {
    const normalizedTabId = normalizeTabId(tabId)
    if(!normalizedTabId || !queueRuntime.hasActiveQueuedTab(normalizedTabId)) return false

    for(const [itemKey, item] of Object.entries(queue || {})) {
        if(!isActiveCoordinatorStatus(item?.status)) continue

        const record = getCoordinatorProgressRecordForItem(itemKey, item, progress)
        const persistedTabId = getPersistedQueuedTabId(item, record)
        if(persistedTabId && persistedTabId !== normalizedTabId) continue
        if(persistedTabId === normalizedTabId && hasConfirmedRuntimeActorForCoordinatorItem(item, record)) return true
        if(getFreshQueuedTabStartupRuntimeActorForCoordinatorItem(
            item,
            record,
            itemKey,
            Date.now(),
            normalizedTabId
        )) return true
    }

    return false
}

function buildRequeuedActiveCoordinatorItemWithoutActor(item = {}, record = null, now = Date.now(), reason = 'reconcile-active-without-actor', options = {}) {
    const retryAttempt = getQueuedTabRetryAttempt(item, record)
    const maxRetries = getQueuedTabMaxRetries(item, record)
    if(isQueuedTabAttemptBudgetExhausted(item, record) && options.forceRequeueExhaustedActorless !== true) {
        return buildTerminalCoordinatorQueueItem(item, {
            status: 'failed',
            outcome: 'timeout',
            error: 'Durable active queue row had no confirmed runtime actor',
            reason,
            eventType: JOB_EVENT_TAB_REMOVED,
            now
        })
    }

    const attemptId = makeAttemptId()
    const attemptNumber = Math.max(
        getAttemptNumberFromValue(item),
        getAttemptNumberFromValue(record)
    ) + 1
    const nextRetryAttempt = retryAttempt + 1
    const effectiveMaxRetries = Math.max(maxRetries, nextRetryAttempt + 1)
    const configuredMaxAttempts = Math.max(
        Number.parseInt(item?.attempt?.max, 10) || 0,
        Number.parseInt(item?.maxAttempts, 10) || 0
    )
    const effectiveMaxAttempts = Math.max(configuredMaxAttempts, attemptNumber + 1, effectiveMaxRetries + 1)
    const actionKind = getCoordinatorActionKindForRequestedAction(item.actionKind || item.tabAction || item.executorTabAction || '')
    const reducedRetry = reduceJobEvent(item, {
        type: JOB_EVENT_RETRY,
        attemptId,
        attemptNumber,
        at: now,
        retryCount: nextRetryAttempt,
        lastRetryAt: item.lastRetryAt || 0
    })
    const retryBase = reducedRetry.accepted ? reducedRetry.item : item

    return applyCoordinatorJobEnvelope({
        ...retryBase,
        attemptId,
        attemptNumber,
        actionKind,
        status: 'queued',
        outcome: '',
        error: '',
        updatedAt: now,
        queuedAt: now,
        activeAt: 0,
        terminalAt: 0,
        tabId: null,
        attempt: effectiveMaxAttempts > 0
            ? {
                id: attemptId,
                number: attemptNumber,
                max: effectiveMaxAttempts
            }
            : 0,
        retryAttempt: nextRetryAttempt,
        maxRetries: effectiveMaxRetries,
        ...(effectiveMaxAttempts > 0
            ? {maxAttempts: effectiveMaxAttempts}
            : {}),
        actionLease: null,
        actionLeaseReleasedAt: now,
        actionLeaseReleaseReason: reason,
        milestones: makeEmptyCoordinatorMilestones()
    }, {
        runInput: {id: item.runId || '', sourceType: item.source?.type || item.scope?.type || ''},
        source: item.source || {},
        runId: item.runId || '',
        targetProfileHref: getCoordinatorItemHref(item),
        requestedUrl: item.requestedUrl || getCoordinatorItemHref(item),
        coordinatorKey: item.coordinatorKey || getCoordinatorItemHref(item),
        actionKind
    })
}

async function requeueDurableActiveCoordinatorItemWithoutActor(itemKey = '', expectedItem = null, expectedRecord = null, reason = 'reconcile-active-without-actor', options = {}) {
    if(!expectedItem || typeof expectedItem !== 'object') return {changed: false, reason: 'invalid-item'}
    if(isTerminalProfileNukeRecord(expectedRecord)) return {changed: false, reason: 'terminal-progress'}
    let contentReadinessReason = ''
    if(options.skipActionPhaseProtection !== true) {
        const actionPhaseProtection = await getActionPhaseLiveTabProtectionForCoordinatorItem(expectedItem, expectedRecord, itemKey)
        if(actionPhaseProtection.protected) {
            return {
                changed: false,
                reason: actionPhaseProtection.reason,
                error: actionPhaseProtection.error || ''
            }
        }
    }
    if(options.skipFreshContentReadiness !== true) {
        const contentReadiness = await deferActiveWithoutActorForFreshContentReadiness(
            itemKey,
            expectedItem,
            expectedRecord,
            reason,
            {currentAuthorityState: options.currentAuthorityState || null}
        )
        contentReadinessReason = contentReadiness.reason || ''
        if(contentReadiness.deferred) {
            return {
                changed: false,
                reason: contentReadiness.reason,
                adopted: contentReadiness.adopted === true,
                ensured: contentReadiness.ensureResult?.ensured === true,
                nudged: contentReadiness.ensureResult?.nudge?.nudged === true,
                error: contentReadiness.ensureResult?.error || contentReadiness.tabStatus?.error || ''
            }
        }
    }
    const expectedPersistedTabStatus = await getPersistedLiveTabStatusForCoordinatorItem(expectedItem, expectedRecord, itemKey)
    const retryBudgetExhausted = isQueuedTabAttemptBudgetExhausted(expectedItem, expectedRecord)
    const timedOutPersistedTabLookupTreatedMissing = shouldTreatTimedOutPersistedTabLookupAsMissingForStaleActive(
        expectedItem,
        expectedRecord,
        expectedPersistedTabStatus
    )
    const shouldRecoverExhaustedMissingActor = retryBudgetExhausted === true &&
        isCoordinatorQueueAuthoritativeItem(expectedItem) &&
        !expectedPersistedTabStatus.tab &&
        (expectedPersistedTabStatus.timedOut === true ||
            timedOutPersistedTabLookupTreatedMissing ||
            expectedPersistedTabStatus.missing === true ||
            expectedPersistedTabStatus.implausible === true)
    if(expectedPersistedTabStatus.tab &&
        contentReadinessReason !== 'content-actor-readiness-window-expired' &&
        retryBudgetExhausted !== true &&
        !isDurableActiveCoordinatorReclaimStale(expectedItem, expectedRecord)) {
        return {changed: false, reason: 'persisted-tab-still-live'}
    }

    const href = getCoordinatorItemHref(expectedItem) || normalizeQuoraProfileUrl(itemKey) || normalizeQuoraProfileUrl(expectedRecord?.profileHref || '')
    const liveProfileTabsByHref = href ? await getLiveProfileTabsByHref() : new Map()
    const hasExpectedLiveProfileTabs = !!href &&
        getOwnedOrExpectedLiveTabsForProfileHref(expectedItem, expectedRecord, href, liveProfileTabsByHref).length > 0
    if(shouldDeferActiveWithoutActorReconcileForPersistedTabStatus(expectedPersistedTabStatus, expectedItem, expectedRecord) &&
        hasExpectedLiveProfileTabs) {
        scheduleCoordinatorReconcile(1000, {
            reason: 'active-without-actor-persisted-tab-lookup-deferred',
            edgeTriggered: true
        })
        return {
            changed: false,
            reason: expectedPersistedTabStatus.timedOut
                ? 'persisted-tab-lookup-timeout'
                : 'persisted-tab-lookup-deferred',
            error: expectedPersistedTabStatus.error || ''
        }
    }
    const reclaimTab = getLiveProfileTabForActiveCoordinatorReclaim(
        expectedItem,
        expectedRecord,
        itemKey,
        liveProfileTabsByHref
    )
    if(reclaimTab &&
        options.skipLiveReclaimAdoption !== true &&
        contentReadinessReason !== 'content-actor-readiness-window-expired') {
        const adopted = await adoptLiveCoordinatorQueuedTab(
            expectedItem,
            itemKey,
            reclaimTab,
            SERVICE_WORKER_QUEUE_OWNER_ID,
            {currentAuthorityState: options.currentAuthorityState || null}
        )
        if(adopted) {
            return {
                changed: true,
                adopted: true,
                status: 'active',
                href,
                reason: 'active-live-tab-adopted'
            }
        }
    }

    const blockedLiveTabTerminal = await terminalizeActiveCoordinatorItemFromBlockedLiveTab(
        itemKey,
        expectedItem,
        expectedRecord,
        liveProfileTabsByHref,
        reason
    )
    if(blockedLiveTabTerminal.changed) return blockedLiveTabTerminal

    const inFlightKey = makeCoordinatorInFlightMutationKey(
        'active-without-actor',
        itemKey || href,
        expectedItem
    )
    if(activeWithoutActorReconcilePromises.has(inFlightKey)) {
        incrementQueueWakeupMetric('reconcile.activeWithoutActor.coalesced')
        return activeWithoutActorReconcilePromises.get(inFlightKey)
    }

    const reconcilePromise = enqueueSpaceFeedStorageUpdate(() => {
        return mutateCoordinatorActiveWithoutRuntimeActorReconcile({
            reason: 'reconcile',
            itemKey,
            expectedItem,
            expectedRecord,
            currentAuthorityState: options.currentAuthorityState || null,
            reconcileReason: reason,
            contentReadinessReason,
            skipActionPhaseProtection: options.skipActionPhaseProtection === true,
            skipFreshOpenDeferralAfterLeaseRelease: options.skipFreshOpenDeferralAfterLeaseRelease === true,
            forceRequeueExhaustedActorless: options.forceRequeueExhaustedActorless === true || shouldRecoverExhaustedMissingActor,
            extendActorlessRetryBudget: options.extendActorlessRetryBudget === true || shouldRecoverExhaustedMissingActor
        })
    }, {
        timeoutMs: options.timeoutMs || QUEUE_CRITICAL_STORAGE_UPDATE_TIMEOUT_MS,
        reason: 'reconcile-active-without-actor'
    })
        .finally(() => {
            activeWithoutActorReconcilePromises.delete(inFlightKey)
        })
    activeWithoutActorReconcilePromises.set(inFlightKey, reconcilePromise)
    const result = await reconcilePromise
    recordFlightRecorderEvent({
        kind: 'actorless-requeue',
        source: 'requeueDurableActiveCoordinatorItemWithoutActor',
        rowKey: itemKey,
        targetUrl: href || itemKey,
        attemptId: getAttemptIdFromValue(expectedItem),
        attemptNumber: getAttemptNumberFromValue(expectedItem),
        runId: expectedItem.runId || '',
        tabId: getPersistedQueuedTabId(expectedItem, expectedRecord),
        accepted: result?.changed === true,
        changed: result?.changed === true,
        statusBefore: expectedItem.status || '',
        statusAfter: result?.status || '',
        reason: result?.reason || reason
    })

    if(result?.changed === true) {
        if(result.status === 'queued' || isTerminalCoordinatorStatus(result.status)) {
            kickQueuedWorkAfterSlotFreed(`${reason || 'reconcile-active-without-actor'}-slot-freed`)
        }
    }

    return result
}

async function releaseMissingActionLeaseForActiveCoordinatorItem(itemKey = '', expectedItem = null, reason = 'reconcile-action-lease-missing-tab', options = {}) {
    if(!expectedItem || typeof expectedItem !== 'object') return {changed: false, reason: 'invalid-item'}
    if(!isActiveCoordinatorStatus(expectedItem.status)) return {changed: false, reason: 'inactive-item'}
    const expectedRecord = options.expectedRecord || null

    const lease = normalizeCoordinatorActionLease(expectedItem.actionLease)
    if(!lease) return {changed: false, reason: 'missing-action-lease'}

    const leaseTabStatus = await getQueuedExecutorTabStatusWithTimeout(lease.tabId, 'action-lease-active-tab')
    if(leaseTabStatus.tab && !isCoordinatorActionLeaseExpired(lease)) {
        const href = getCoordinatorItemHref(expectedItem) ||
            normalizeQuoraProfileUrl(itemKey) ||
            normalizeQuoraProfileUrl(expectedRecord?.profileHref || lease.profileHref || '')
        const liveProfileTabsByHref = href ? new Map([[href, [leaseTabStatus.tab]]]) : new Map()
        const blockedLiveTabTerminal = await terminalizeActiveCoordinatorItemFromBlockedLiveTab(
            itemKey,
            expectedItem,
            expectedRecord,
            liveProfileTabsByHref,
            reason
        )
        if(blockedLiveTabTerminal.changed) return blockedLiveTabTerminal

        return {changed: false, reason: 'action-lease-tab-still-live'}
    }
    const href = getCoordinatorItemHref(expectedItem) ||
        normalizeQuoraProfileUrl(itemKey) ||
        normalizeQuoraProfileUrl(expectedRecord?.profileHref || lease.profileHref || '')
    const liveProfileTabsByHref = href ? await getLiveProfileTabsByHref() : new Map()
    const hasExpectedLiveProfileTabs = !!href &&
        getOwnedOrExpectedLiveTabsForProfileHref(expectedItem, expectedRecord, href, liveProfileTabsByHref).length > 0
    if(shouldDeferActiveWithoutActorReconcileForPersistedTabStatus(leaseTabStatus, expectedItem, expectedRecord) &&
        hasExpectedLiveProfileTabs) {
        scheduleCoordinatorReconcile(1000, {
            reason: 'action-lease-tab-lookup-deferred',
            edgeTriggered: true
        })
        return {
            changed: false,
            reason: leaseTabStatus.timedOut
                ? 'action-lease-tab-lookup-timeout'
                : 'action-lease-tab-lookup-deferred',
            error: leaseTabStatus.error || ''
        }
    }

    const inFlightKey = makeCoordinatorInFlightMutationKey(
        'missing-action-lease',
        itemKey,
        expectedItem,
        lease.tabId
    )
    if(missingActionLeaseReleasePromises.has(inFlightKey)) {
        incrementQueueWakeupMetric('reconcile.actionLeaseMissingTab.coalesced')
        return missingActionLeaseReleasePromises.get(inFlightKey)
    }

    const now = Date.now()
    const releasePromise = enqueueSpaceFeedStorageUpdate(() => {
        return applyCoordinatorQueueMachineEvent({
            type: 'ACTION_LEASE_TAB_RELEASE',
            tabId: lease.tabId,
            releaseReason: reason,
            now,
            currentAuthorityState: options.currentAuthorityState || null
        })
    }, {
        timeoutMs: options.timeoutMs || QUEUE_CRITICAL_STORAGE_UPDATE_TIMEOUT_MS,
        reason: 'reconcile-action-lease-missing-tab'
    })
        .finally(() => {
            missingActionLeaseReleasePromises.delete(inFlightKey)
        })
    missingActionLeaseReleasePromises.set(inFlightKey, releasePromise)
    const result = await releasePromise
    return {
        ...(result || {}),
        changed: result?.changed === true || result?.released === true
    }
}

async function terminalizeDurableActiveCoordinatorItemFromTerminalProgress(itemKey = '', expectedItem = null, record = null, reason = 'reconcile-terminal-progress-active', options = {}) {
    if(!expectedItem || typeof expectedItem !== 'object') return {changed: false, reason: 'invalid-item'}
    if(!isActiveCoordinatorStatus(expectedItem.status)) return {changed: false, reason: 'inactive-item'}
    if(!record || !isTerminalProfileNukeRecord(record)) return {changed: false, reason: 'missing-terminal-progress'}
    if(hasMismatchedCoordinatorAttempt(expectedItem, record)) return {changed: false, reason: 'progress-attempt-mismatch'}

    const mapped = getCoordinatorStatusFromProgress(record)
    if(!isTerminalCoordinatorStatus(mapped.status)) return {changed: false, reason: 'nonterminal-progress'}

    return enqueueSpaceFeedStorageUpdate(() => {
        return mutateCoordinatorActiveFromTerminalProgress({
            reason: 'reconcile',
            itemKey,
            expectedItem,
            record,
            mapped,
            currentAuthorityState: options.currentAuthorityState || null,
            reconcileReason: reason
        })
    }, {
        timeoutMs: options.timeoutMs || QUEUE_CRITICAL_STORAGE_UPDATE_TIMEOUT_MS,
        reason: 'terminal-progress-active'
    })
}

async function terminalizeActiveCoordinatorNonProfileLanding(itemKey = '', landingUrl = '', options = {}) {
    const key = `${itemKey || ''}`.trim()
    if(!key) return {changed: false, reason: 'missing-item-key'}

    return enqueueSpaceFeedStorageUpdate(() => {
        return mutateCoordinatorActiveNonProfileLandingTerminalize({
            reason: options.reason || 'reconcile',
            itemKey: key,
            landingUrl,
            expectedAttemptId: options.expectedAttemptId || '',
            expectedAttemptNumber: options.expectedAttemptNumber || 0,
            reconcileReason: options.reconcileReason || 'non-profile-landing'
        })
    })
}

async function terminalizeActiveCoordinatorProfileRedirectMismatch(itemKey = '', requestedHref = '', resolvedHref = '', options = {}) {
    const key = `${itemKey || ''}`.trim()
    const requestedProfileHref = normalizeQuoraProfileUrl(requestedHref || '')
    const resolvedProfileHref = normalizeQuoraProfileUrl(resolvedHref || '')
    if(!key || !requestedProfileHref || !resolvedProfileHref || requestedProfileHref === resolvedProfileHref) {
        return {changed: false, reason: 'invalid-profile-redirect-mismatch'}
    }

    return enqueueSpaceFeedStorageUpdate(() => {
        return mutateCoordinatorActiveProfileRedirectMismatchTerminalize({
            reason: options.reason || 'reconcile',
            itemKey: key,
            requestedProfileHref,
            resolvedProfileHref,
            expectedAttemptId: options.expectedAttemptId || '',
            expectedAttemptNumber: options.expectedAttemptNumber || 0,
            reconcileReason: options.reconcileReason || 'profile-redirect-mismatch'
        })
    }, {
        timeoutMs: options.timeoutMs || QUEUE_CRITICAL_STORAGE_UPDATE_TIMEOUT_MS,
        reason: 'terminalize-profile-redirect-mismatch'
    })
}

async function mutateCoordinatorActiveNonProfileLandingTerminalize(operation = {}) {
    const snapshotReason = normalizeSnapshotWriteReason(operation.reason || 'reconcile')
    if(snapshotReason !== 'reconcile' && snapshotReason !== 'ordinaryMutation') {
        return {changed: false, reason: 'invalid-terminalize-reason'}
    }

    const itemKey = `${operation.itemKey || ''}`.trim()
    if(!itemKey) return {changed: false, reason: 'missing-item-key'}

    const state = await loadCoordinatorQueueRunsProgressProjection({
        metricPath: 'reconcile.nonProfileLanding.load'
    })
    let currentAuthorityState = normalizeCoordinatorAuthorityStateInput(state)
    const queue = currentAuthorityState.queue
    const runs = currentAuthorityState.runs
    const progress = state.progress
    const current = queue[itemKey] || null
    if(!current || !isActiveCoordinatorStatus(current.status)) return {changed: false, reason: 'row-changed'}

    const expectedAttemptId = normalizeAttemptId(operation.expectedAttemptId || '')
    const expectedAttemptNumber = Number.parseInt(operation.expectedAttemptNumber, 10) || 0
    if(expectedAttemptId && getAttemptIdFromValue(current) !== expectedAttemptId) return {changed: false, reason: 'attempt-changed'}
    if(expectedAttemptNumber && getAttemptNumberFromValue(current) !== expectedAttemptNumber) return {changed: false, reason: 'attempt-changed'}

    const href = getCoordinatorItemHref(current) || normalizeQuoraProfileUrl(itemKey)
    const currentRecord = getCoordinatorProgressRecordForItem(itemKey, current, progress)
    if(currentRecord && hasMismatchedCoordinatorAttempt(current, currentRecord)) return {changed: false, reason: 'progress-attempt-mismatch'}

    const landingUrl = `${operation.landingUrl || currentRecord?.lastUrl || currentRecord?.errorPageUrl || ''}`.trim()
    if(!shouldTerminalizeCoordinatorNonProfileLanding(current, currentRecord, itemKey, landingUrl)) {
        return {changed: false, reason: 'not-non-profile-landing'}
    }

    const now = Date.now()
    const message = getNonProfileQuoraLandingMessage(landingUrl)
    const nextItem = buildTerminalCoordinatorQueueItem(current, {
        status: 'skipped',
        outcome: 'non-profile-target',
        error: message,
        reason: `${operation.reconcileReason || 'non-profile-landing'}`.trim(),
        eventType: JOB_EVENT_TERMINAL,
        now
    })

    const authorityResult = await coordinatorAuthority.applyWithinStorageUpdate({
        operationKind: 'terminalize-non-profile-landing',
        rowKey: itemKey,
        expectedAttemptId,
        expectedAttemptNumber,
        reason: 'ordinaryMutation',
        metricPath: 'reconcile.nonProfileLanding.save',
        currentAuthorityState,
        mutate(currentItem, context) {
            if(!isActiveCoordinatorStatus(currentItem?.status)) {
                return context.reject('row-changed')
            }
            if(JSON.stringify(currentItem) !== JSON.stringify(current)) {
                return context.reject('row-changed-before-authority-apply')
            }
            return nextItem
        }
    })

    if(authorityResult?.accepted !== true || authorityResult?.durable !== true) {
        return {
            changed: false,
            reason: authorityResult?.reason || 'authority-apply-failed'
        }
    }

    currentAuthorityState = coordinatorAuthority.current()
    const nextQueue = currentAuthorityState.queue

    let progressChanged = false
    if(href) {
        const terminalRecord = normalizeProgressPatch(
            href,
            {
                status: 'profile-unavailable',
                actionKind: nextItem.actionKind || current.actionKind || currentRecord?.actionKind || 'mute-block',
                attemptId: getAttemptIdFromValue(nextItem) || getAttemptIdFromValue(currentRecord),
                attemptNumber: getAttemptNumberFromValue(nextItem) || getAttemptNumberFromValue(currentRecord),
                runId: nextItem.runId || current.runId || currentRecord?.runId || '',
                tabId: getPersistedQueuedTabId(current, currentRecord) || null,
                openedViablePage: false,
                finalError: message,
                unavailableReason: message,
                errorPageUrl: landingUrl,
                closeRequestedAt: now,
                closedByExtension: true,
                closeReason: 'non-profile-landing',
                terminalAt: now,
                event: message
            },
            currentRecord || progress[href] || {}
        )
        if(terminalRecord) {
            progress[href] = terminalRecord
            profileNukeProgress = {
                ...profileNukeProgress,
                [href]: terminalRecord
            }
            progressChanged = true
        }
    }

    const affectedRunIds = new Set()
    if(nextItem.runId) affectedRunIds.add(nextItem.runId)
    if(current.runId) affectedRunIds.add(current.runId)
    if(href) {
        for(const runId of getCoordinatorRunIdsForHref(runs, href)) {
            affectedRunIds.add(runId)
        }
    }
    const nextRuns = affectedRunIds.size
        ? recomputeCoordinatorRuns(nextQueue, runs, affectedRunIds)
        : runs
    const runsChanged = JSON.stringify(nextRuns) !== JSON.stringify(runs)

    if(runsChanged || progressChanged) {
        let derivedSaved = true
        let progressProjectionSaved = {saved: true, rows: 0}
        let openReservationHref = ''
        try {
            progressProjectionSaved = progressChanged
                ? await saveProfileNukeProgressRowProjection({[href]: progress[href]}, {
                    metricPath: 'reconcile.nonProfileLanding.progressProjection'
                })
                : {saved: true, rows: 0}
        }
        catch(error) {
            progressProjectionSaved = false
            recordCoordinatorDiagnosticEvent(
                'terminalize-non-profile-landing-progress-projection-save-failed',
                error?.message || 'Non-profile landing progress projection save failed'
            )
        }
        if(progressProjectionSaved === false || progressProjectionSaved?.saved === false) {
            derivedSaved = false
        }
        if(runsChanged) {
            try {
                derivedSaved = await saveCoordinatorState({
                    runs: nextRuns,
                    progress: undefined
                }, {
                    queue: false,
                    runs: true,
                    progress: false,
                    reason: 'reconcile',
                    queueOperation: 'terminalize-non-profile-landing-derived',
                    queueChangedRows: 0
                }) && derivedSaved
            }
            catch(error) {
                derivedSaved = false
                recordCoordinatorDiagnosticEvent(
                    'terminalize-non-profile-landing-derived-save-failed',
                    error?.message || 'Non-profile landing derived save failed'
                )
            }
        }
        if(derivedSaved === false) {
            incrementQueueWakeupMetric('reconcile.nonProfileLanding.derivedSaveFailed')
            scheduleCoordinatorReconcile(1000, {
                reason: 'terminalize-non-profile-landing-derived-save-failed',
                edgeTriggered: true
            })
        }
    }

    incrementQueueWakeupMetric('reconcile.changed.nonProfileLanding')
    return {
        changed: true,
        status: nextItem.status,
        outcome: nextItem.outcome,
        tabId: getPersistedQueuedTabId(current, currentRecord),
        href,
        progressChanged
    }
}

async function mutateCoordinatorActiveProfileRedirectMismatchTerminalize(operation = {}) {
    const snapshotReason = normalizeSnapshotWriteReason(operation.reason || 'reconcile')
    if(snapshotReason !== 'reconcile' && snapshotReason !== 'ordinaryMutation') {
        return {changed: false, reason: 'invalid-profile-redirect-reason'}
    }

    const itemKey = `${operation.itemKey || ''}`.trim()
    if(!itemKey) return {changed: false, reason: 'missing-item-key'}

    const requestedProfileHref = normalizeQuoraProfileUrl(operation.requestedProfileHref || '')
    const resolvedProfileHref = normalizeQuoraProfileUrl(operation.resolvedProfileHref || '')
    if(!requestedProfileHref || !resolvedProfileHref || requestedProfileHref === resolvedProfileHref) {
        return {changed: false, reason: 'not-profile-redirect-mismatch'}
    }

    const state = await loadCoordinatorQueueRunsProgressProjection({
        metricPath: 'reconcile.profileRedirectMismatch.load'
    })
    let currentAuthorityState = normalizeCoordinatorAuthorityStateInput(state)
    const queue = currentAuthorityState.queue
    const runs = currentAuthorityState.runs
    const progress = state.progress
    const current = queue[itemKey] || null
    if(!current || !isActiveCoordinatorStatus(current.status)) return {changed: false, reason: 'row-changed'}
    if(isProfileResolutionItem(current)) return {changed: false, reason: 'profile-resolution-item'}

    const href = getCoordinatorItemHref(current) || normalizeQuoraProfileUrl(itemKey)
    if(!href || href !== requestedProfileHref) return {changed: false, reason: 'requested-profile-changed'}

    const expectedAttemptId = normalizeAttemptId(operation.expectedAttemptId || '')
    const expectedAttemptNumber = Number.parseInt(operation.expectedAttemptNumber, 10) || 0
    if(expectedAttemptId && getAttemptIdFromValue(current) !== expectedAttemptId) return {changed: false, reason: 'attempt-changed'}
    if(expectedAttemptNumber && getAttemptNumberFromValue(current) !== expectedAttemptNumber) return {changed: false, reason: 'attempt-changed'}

    const currentRecord = getCoordinatorProgressRecordForItem(itemKey, current, progress)
    if(currentRecord && hasMismatchedCoordinatorAttempt(current, currentRecord)) return {changed: false, reason: 'progress-attempt-mismatch'}

    const now = Date.now()
    const message = `Queued profile redirected from ${requestedProfileHref} to ${resolvedProfileHref}`
    const nextItem = buildTerminalCoordinatorQueueItem(current, {
        status: 'skipped',
        outcome: 'profile-redirect-mismatch',
        error: message,
        reason: `${operation.reconcileReason || 'profile-redirect-mismatch'}`.trim(),
        eventType: JOB_EVENT_TERMINAL,
        now
    })
    const currentCoordinatorKey = getCoordinatorItemQueueKey(current, itemKey)

    const authorityResult = await coordinatorAuthority.applyWithinStorageUpdate({
        operationKind: 'terminalize-profile-redirect-mismatch',
        rowKey: itemKey,
        expectedAttemptId,
        expectedAttemptNumber,
        reason: 'ordinaryMutation',
        metricPath: 'reconcile.profileRedirectMismatch.save',
        projectionPayload: 'queueViewOnly',
        includeProjectionInWalSave: true,
        currentAuthorityState,
        mutate(currentItem, context) {
            if(!isActiveCoordinatorStatus(currentItem?.status)) {
                return context.reject('row-changed')
            }
            if(isProfileResolutionItem(currentItem)) {
                return context.reject('profile-resolution-item')
            }
            if((getCoordinatorItemHref(currentItem) || normalizeQuoraProfileUrl(itemKey)) !== href ||
                getCoordinatorItemQueueKey(currentItem, itemKey) !== currentCoordinatorKey) {
                return context.reject('row-target-changed-before-authority-apply')
            }
            return buildTerminalCoordinatorQueueItem(currentItem, {
                status: 'skipped',
                outcome: 'profile-redirect-mismatch',
                error: message,
                reason: `${operation.reconcileReason || 'profile-redirect-mismatch'}`.trim(),
                eventType: JOB_EVENT_TERMINAL,
                now: Date.now()
            })
        }
    })

    if(authorityResult?.accepted !== true || authorityResult?.durable !== true) {
        return {
            changed: false,
            reason: authorityResult?.reason || 'authority-apply-failed'
        }
    }

    currentAuthorityState = coordinatorAuthority.current()
    const nextQueue = currentAuthorityState.queue
    const durableItem = authorityResult.nextRow || nextQueue[itemKey] || nextItem
    const terminalRecord = normalizeProgressPatch(
        href,
        {
            status: 'profile-unavailable',
            actionKind: durableItem.actionKind || current.actionKind || currentRecord?.actionKind || 'mute-block',
            attemptId: getAttemptIdFromValue(durableItem) || getAttemptIdFromValue(currentRecord),
            attemptNumber: getAttemptNumberFromValue(durableItem) || getAttemptNumberFromValue(currentRecord),
            runId: durableItem.runId || current.runId || currentRecord?.runId || '',
            tabId: getPersistedQueuedTabId(current, currentRecord) || null,
            openedViablePage: false,
            finalError: message,
            unavailableReason: message,
            lastUrl: resolvedProfileHref,
            resolvedProfileHref,
            remappedFromRequested: true,
            closeRequestedAt: now,
            closedByExtension: true,
            closeReason: 'profile-redirect-mismatch',
            terminalAt: now,
            event: message
        },
        currentRecord || progress[href] || {}
    )

    let progressProjectionSaved = {saved: true, rows: 0}
    if(terminalRecord) {
        progress[href] = terminalRecord
        profileNukeProgress = {
            ...profileNukeProgress,
            [href]: terminalRecord
        }
        try {
            progressProjectionSaved = await saveProfileNukeProgressRowProjection({[href]: terminalRecord}, {
                metricPath: 'reconcile.profileRedirectMismatch.progressProjection'
            })
        }
        catch(error) {
            progressProjectionSaved = false
            recordCoordinatorDiagnosticEvent(
                'terminalize-profile-redirect-mismatch-progress-projection-save-failed',
                error?.message || 'Profile redirect mismatch progress projection save failed'
            )
        }
        if(progressProjectionSaved === false || progressProjectionSaved?.saved === false) {
            incrementQueueWakeupMetric('reconcile.profileRedirectMismatch.progressProjectionFailed')
            scheduleCoordinatorReconcile(1000, {
                reason: 'terminalize-profile-redirect-mismatch-progress-projection-failed',
                edgeTriggered: true
            })
        }
    }

    const affectedRunIds = new Set()
    if(durableItem.runId) affectedRunIds.add(durableItem.runId)
    if(current.runId) affectedRunIds.add(current.runId)
    for(const runId of getCoordinatorRunIdsForHref(runs, href)) {
        affectedRunIds.add(runId)
    }
    const nextRuns = affectedRunIds.size
        ? recomputeCoordinatorRuns(nextQueue, runs, affectedRunIds)
        : runs
    const runsChanged = affectedRunIds.size && JSON.stringify(nextRuns) !== JSON.stringify(runs)
    if(runsChanged) {
        let derivedSaved = true
        try {
            derivedSaved = await saveCoordinatorState({
                runs: nextRuns,
                progress: undefined
            }, {
                queue: false,
                runs: true,
                progress: false,
                reason: 'reconcile',
                queueOperation: 'terminalize-profile-redirect-mismatch-derived',
                queueChangedRows: 0
            })
        }
        catch(error) {
            derivedSaved = false
            recordCoordinatorDiagnosticEvent(
                'terminalize-profile-redirect-mismatch-derived-save-failed',
                error?.message || 'Profile redirect mismatch derived save failed'
            )
        }
        if(derivedSaved === false) {
            incrementQueueWakeupMetric('reconcile.profileRedirectMismatch.derivedSaveFailed')
            scheduleCoordinatorReconcile(1000, {
                reason: 'terminalize-profile-redirect-mismatch-derived-save-failed',
                edgeTriggered: true
            })
        }
    }

    incrementQueueWakeupMetric('reconcile.changed.profileRedirectMismatch')
    return {
        changed: true,
        status: durableItem.status,
        outcome: durableItem.outcome,
        tabId: getPersistedQueuedTabId(current, currentRecord),
        href,
        resolvedProfileHref,
        progressChanged: !!terminalRecord,
        progressProjectionSaved
    }
}

async function mutateCoordinatorActiveWithoutRuntimeActorReconcile(operation = {}) {
    const snapshotReason = normalizeSnapshotWriteReason(operation.reason || 'reconcile')
    if(snapshotReason !== 'reconcile') return {changed: false, reason: 'invalid-reconcile-reason'}

    const itemKey = `${operation.itemKey || ''}`.trim()
    const expectedItem = operation.expectedItem || null
    if(!itemKey || !expectedItem || typeof expectedItem !== 'object') {
        return {changed: false, reason: 'invalid-item'}
    }

    let currentAuthorityState = null
    if(operation.currentAuthorityState?.queue &&
        operation.currentAuthorityState?.runs) {
        currentAuthorityState = {
            stored: operation.currentAuthorityState.stored || {},
            queue: normalizeCoordinatorMap(cloneCoordinatorAuthorityValue(operation.currentAuthorityState.queue || {})),
            runs: normalizeCoordinatorMap(cloneCoordinatorAuthorityValue(operation.currentAuthorityState.runs || {})),
            progress: cloneCoordinatorAuthorityValue(operation.currentAuthorityState.progress || {})
        }
        incrementQueueWakeupMetric('reconcile.activeWithoutActor.usedResidentAuthority')
    }
    if(!currentAuthorityState) {
        currentAuthorityState = await loadCoordinatorQueueRunsProjection({
            metricPath: 'reconcile.activeWithoutActor.load'
        })
    }
    const queue = currentAuthorityState.queue
    const progress = currentAuthorityState.progress || {}
    const current = queue[itemKey] || null
    if(!current || !isActiveCoordinatorStatus(current.status)) return {changed: false, reason: 'row-changed'}
    const activeLease = normalizeCoordinatorActionLease(current.actionLease)
    const operationReason = `${operation.reconcileReason || operation.reason || ''}`.trim()
    const activeMissingRecovery = /active-missing-tab/.test(operationReason)
    if(!activeMissingRecovery && activeLease && !isCoordinatorActionLeaseExpired(activeLease)) {
        incrementQueueWakeupMetric('reconcile.activeWithoutActor.deferredLiveActionLease')
        scheduleCoordinatorReconcile(1000, {
            reason: `${operation.reconcileReason || 'reconcile'}-active-action-lease`,
            edgeTriggered: true,
            allowBeforeQuora: true
        })
        return {
            changed: false,
            reason: 'active-action-lease-live',
            tabId: activeLease.tabId || null
        }
    }

    const expectedAttemptId = getAttemptIdFromValue(expectedItem)
    const expectedAttemptNumber = getAttemptNumberFromValue(expectedItem)
    if(expectedAttemptId && getAttemptIdFromValue(current) !== expectedAttemptId) return {changed: false, reason: 'attempt-changed'}
    if(expectedAttemptNumber && getAttemptNumberFromValue(current) !== expectedAttemptNumber) return {changed: false, reason: 'attempt-changed'}

    const href = getCoordinatorItemHref(current) || normalizeQuoraProfileUrl(itemKey)
    const loadedRecord = getCoordinatorProgressRecordForItem(itemKey, current, progress)
    const currentRecord = loadedRecord && hasMismatchedCoordinatorAttempt(current, loadedRecord)
        ? null
        : loadedRecord
    if(isTerminalProfileNukeRecord(currentRecord)) return {changed: false, reason: 'terminal-progress'}
    const freshActiveOpenAt = Math.max(
        Number.parseInt(current?.activeAt, 10) || 0,
        Number.parseInt(current?.milestones?.tabCreatedAt, 10) || 0,
        Number.parseInt(current?.milestones?.navigationStartedAt, 10) || 0,
        Number.parseInt(currentRecord?.tabCreatedAt, 10) || 0,
        Number.parseInt(currentRecord?.tabOpenedAt, 10) || 0,
        Number.parseInt(currentRecord?.contentOpenedAt, 10) || 0
    )
    if(operation.skipFreshOpenDeferralAfterLeaseRelease !== true &&
        freshActiveOpenAt > 0 &&
        Date.now() - freshActiveOpenAt < STALE_BACKGROUND_OPENING_QUEUED_TAB_MS) {
        incrementQueueWakeupMetric('reconcile.deferred.freshActiveOpen')
        scheduleCoordinatorReconcile(1000, {
            reason: `${operation.reconcileReason || 'reconcile'}-fresh-active-open`,
            edgeTriggered: true,
            allowBeforeQuora: true
        })
        scheduleCoordinatorQueueResume(1000, 'fresh-active-open-waiting-for-actor', {
            allowBeforeQuora: true
        })
        return {
            changed: false,
            reason: 'fresh-active-open-waiting-for-actor'
        }
    }
    if(operation.skipFreshOpenDeferralAfterLeaseRelease !== true &&
        hasFreshWorkerWindowStartupProgressForCoordinatorItem(current, currentRecord)) {
        incrementQueueWakeupMetric('reconcile.deferred.freshWorkerWindowStartupProgress')
        scheduleCoordinatorReconcile(1000, {
            reason: `${operation.reconcileReason || 'reconcile'}-fresh-worker-window-startup-progress`,
            edgeTriggered: true,
            allowBeforeQuora: true
        })
        return {
            changed: false,
            reason: 'fresh-worker-window-startup-progress'
        }
    }
    if(operation.skipActionPhaseProtection !== true) {
        const actionPhaseProtection = await getActionPhaseLiveTabProtectionForCoordinatorItem(current, currentRecord, itemKey)
        if(actionPhaseProtection.protected) {
            return {
                changed: false,
                reason: actionPhaseProtection.reason,
                error: actionPhaseProtection.error || ''
            }
        }
    }

    const tabId = getPersistedQueuedTabId(current, currentRecord)
    const persistedTabStatus = await getPersistedLiveTabStatusForCoordinatorItem(current, currentRecord, itemKey)
    const retryBudgetExhausted = isQueuedTabAttemptBudgetExhausted(current, currentRecord)
    const contentReadinessReason = `${operation.contentReadinessReason || ''}`.trim()
    if(persistedTabStatus.tab &&
        contentReadinessReason !== 'content-actor-readiness-window-expired' &&
        retryBudgetExhausted !== true &&
        !isDurableActiveCoordinatorReclaimStale(current, currentRecord)) {
        return {changed: false, reason: 'persisted-tab-still-live'}
    }
    const liveProfileTabsByHref = href ? await getLiveProfileTabsByHref() : new Map()
    const hasExpectedLiveProfileTabs = !!href &&
        getOwnedOrExpectedLiveTabsForProfileHref(current, currentRecord, href, liveProfileTabsByHref).length > 0
    if(shouldDeferActiveWithoutActorReconcileForPersistedTabStatus(persistedTabStatus, current, currentRecord) &&
        hasExpectedLiveProfileTabs) {
        scheduleCoordinatorReconcile(1000, {
            reason: 'active-without-actor-persisted-tab-lookup-deferred',
            edgeTriggered: true
        })
        return {
            changed: false,
            reason: persistedTabStatus.timedOut
                ? 'persisted-tab-lookup-timeout'
                : 'persisted-tab-lookup-deferred',
            error: persistedTabStatus.error || ''
        }
    }

    const now = Date.now()
    const reconcileReason = `${operation.reconcileReason || 'reconcile-active-without-actor'}`.trim()
    const actorlessReleaseReason = `${current.actionLeaseReleaseReason || reconcileReason || 'reconcile-active-without-actor'}`.trim()
    const currentHref = getCoordinatorItemHref(current) || normalizeQuoraProfileUrl(itemKey)
    const currentCoordinatorKey = getCoordinatorItemQueueKey(current, itemKey)
    const authorityResult = await coordinatorAuthority.applyWithinStorageUpdate({
        operationKind: 'reconcile-active-without-actor',
        rowKey: itemKey,
        expectedAttemptId,
        expectedAttemptNumber,
        reason: 'ordinaryMutation',
        metricPath: 'reconcile.activeWithoutActor.save',
        projectionPayload: 'queueViewOnly',
        currentAuthorityState,
        forceFreshAuthorityState: true,
        mutate(currentItem, context) {
            if(!isActiveCoordinatorStatus(currentItem?.status)) {
                return context.reject('row-changed')
            }
            if((getCoordinatorItemHref(currentItem) || normalizeQuoraProfileUrl(itemKey)) !== currentHref ||
                getCoordinatorItemQueueKey(currentItem, itemKey) !== currentCoordinatorKey) {
                return context.reject('row-target-changed-before-authority-apply')
            }
            if(currentRecord &&
                isTerminalProfileNukeRecord(currentRecord) &&
                !isRetryableTerminalProfileNukeRecord(currentRecord) &&
                shouldApplyProgressToCoordinatorItem(currentItem, currentRecord) &&
                !hasMismatchedCoordinatorAttempt(currentItem, currentRecord)) {
                const mapped = getCoordinatorStatusFromProgress(currentRecord)
                const terminalItem = transitionCoordinatorItemFromProgress(currentItem, currentRecord, mapped, {
                    now
                })
                if(isTerminalCoordinatorStatus(terminalItem?.status)) {
                    return terminalItem
                }
            }
            const releaseReason = `${currentItem.actionLeaseReleaseReason || actorlessReleaseReason}`.trim()
            return buildRequeuedActiveCoordinatorItemWithoutActor(currentItem, currentRecord, now, releaseReason, {
                forceRequeueExhaustedActorless: operation.forceRequeueExhaustedActorless === true,
                extendActorlessRetryBudget: operation.extendActorlessRetryBudget === true
            })
        }
    })

    if(authorityResult?.accepted !== true || authorityResult?.durable !== true) {
        return {
            changed: false,
            reason: authorityResult?.reason || 'authority-apply-failed'
        }
    }

    currentAuthorityState = coordinatorAuthority.current()
    const nextQueue = currentAuthorityState.queue
    const nextItem = authorityResult.nextRow || nextQueue[itemKey] || null
    if(!nextItem) return {changed: false, reason: 'authority-row-missing-after-apply'}
    recordFlightRecorderEvent({
        kind: 'actorless-requeue',
        source: 'mutateCoordinatorReconcileActiveWithoutRuntimeActor',
        rowKey: itemKey,
        targetUrl: href || itemKey,
        attemptId: expectedAttemptId,
        attemptNumber: expectedAttemptNumber,
        runId: current.runId || '',
        tabId,
        accepted: authorityResult?.accepted === true,
        durable: authorityResult?.durable === true,
        changed: authorityResult?.changed === true,
        statusBefore: current.status || '',
        statusAfter: nextItem.status || '',
        reason: reconcileReason
    })
    if(nextItem.status === 'queued' || isTerminalCoordinatorStatus(nextItem.status)) {
        scheduleQueuedWorkContinuation(`${reconcileReason || 'reconcile-active-without-actor'}-slot-freed`)
    }

    let progressChanged = false
    if(href && !isTerminalCoordinatorStatus(nextItem.status)) {
        const resetRecord = normalizeProgressPatch(
            href,
            buildQueuedCoordinatorProgressResetPatch(nextItem, {
                now,
                runId: nextItem.runId || current.runId || '',
                actionKind: nextItem.actionKind || current.actionKind || ''
            }),
            currentRecord || progress[href] || {}
        )
        if(resetRecord) {
            progress[href] = resetRecord
            profileNukeProgress = {
                ...profileNukeProgress,
                [href]: resetRecord
            }
            progressChanged = true
        }
    }
    else if(href) {
        const terminalRecord = makeTerminalProgressRecordFromCoordinatorItem(
            href,
            nextItem,
            currentRecord || progress[href] || {},
            'Failed durable active row without a confirmed runtime actor'
        )
        if(terminalRecord) {
            progress[href] = terminalRecord
            profileNukeProgress = {
                ...profileNukeProgress,
                [href]: terminalRecord
            }
            progressChanged = true
        }
    }

    let progressProjectionSaved = {saved: true, rows: 0}
    if(progressChanged && href) {
        const progressRecord = cloneCoordinatorAuthorityValue(progress[href])
        progressProjectionSaved = {
            saved: 'scheduled',
            rows: 1
        }
        void promiseWithTimeout(
            saveProfileNukeProgressRowProjection({[href]: progressRecord}, {
                metricPath: 'reconcile.activeWithoutActor.progressProjection'
            }),
            COORDINATOR_ACTIVE_RECONCILE_STORAGE_UPDATE_TIMEOUT_MS,
            'active-without-actor progress projection save'
        ).then(result => {
            if(result === false || result?.saved === false) {
                incrementQueueWakeupMetric('reconcile.activeWithoutActor.progressProjectionFailed')
                scheduleCoordinatorReconcile(1000, {
                    reason: 'reconcile-active-without-actor-progress-projection-failed',
                    edgeTriggered: true
                })
            }
        }).catch(error => {
            incrementQueueWakeupMetric('reconcile.activeWithoutActor.progressProjectionFailed')
            recordCoordinatorDiagnosticEvent(
                'reconcile-active-without-actor-progress-projection-save-failed',
                error?.message || 'Active-without-actor terminal progress projection save failed'
            )
            scheduleCoordinatorReconcile(1000, {
                reason: 'reconcile-active-without-actor-progress-projection-failed',
                edgeTriggered: true
            })
        })
    }

    return {
        changed: true,
        status: nextItem.status,
        tabId: persistedTabStatus.tab ? tabId : null,
        href,
        item: nextItem,
        itemKey,
        progressChanged,
        progressProjectionSaved
    }
}

async function mutateCoordinatorActiveFromTerminalProgress(operation = {}) {
    const snapshotReason = normalizeSnapshotWriteReason(operation.reason || 'reconcile')
    if(snapshotReason !== 'reconcile') return {changed: false, reason: 'invalid-terminal-progress-reconcile-reason'}

    const itemKey = `${operation.itemKey || ''}`.trim()
    const expectedItem = operation.expectedItem || null
    const record = operation.record || null
    const mapped = operation.mapped || getCoordinatorStatusFromProgress(record)
    if(!itemKey || !expectedItem || typeof expectedItem !== 'object') {
        return {changed: false, reason: 'invalid-item'}
    }
    if(!record || !isTerminalProfileNukeRecord(record) || !isTerminalCoordinatorStatus(mapped.status)) {
        return {changed: false, reason: 'missing-terminal-progress'}
    }

    let currentAuthorityState = null
    if(operation.currentAuthorityState?.queue &&
        operation.currentAuthorityState?.runs) {
        currentAuthorityState = {
            stored: operation.currentAuthorityState.stored || {},
            queue: normalizeCoordinatorMap(cloneCoordinatorAuthorityValue(operation.currentAuthorityState.queue || {})),
            runs: normalizeCoordinatorMap(cloneCoordinatorAuthorityValue(operation.currentAuthorityState.runs || {})),
            progress: cloneCoordinatorAuthorityValue(operation.currentAuthorityState.progress || {})
        }
        incrementQueueWakeupMetric('reconcile.terminalProgressActive.usedResidentAuthority')
    }
    if(!currentAuthorityState) {
        currentAuthorityState = await loadCoordinatorQueueRunsProgressProjection({
            metricPath: 'reconcile.terminalProgressActive.load'
        })
    }

    const queue = currentAuthorityState.queue
    const runs = currentAuthorityState.runs
    const progress = currentAuthorityState.progress || {}
    const current = queue[itemKey] || null
    if(!current || !isActiveCoordinatorStatus(current.status)) return {changed: false, reason: 'row-changed'}

    const expectedAttemptId = getAttemptIdFromValue(expectedItem)
    const expectedAttemptNumber = getAttemptNumberFromValue(expectedItem)
    if(expectedAttemptId && getAttemptIdFromValue(current) !== expectedAttemptId) return {changed: false, reason: 'attempt-changed'}
    if(expectedAttemptNumber && getAttemptNumberFromValue(current) !== expectedAttemptNumber) return {changed: false, reason: 'attempt-changed'}
    if(hasMismatchedCoordinatorAttempt(current, record)) return {changed: false, reason: 'progress-attempt-mismatch'}

    const currentRecord = getCoordinatorProgressRecordForItem(itemKey, current, progress)
    if(currentRecord && hasMismatchedCoordinatorAttempt(current, currentRecord)) {
        return {changed: false, reason: 'current-progress-attempt-mismatch'}
    }

    const href = getCoordinatorItemHref(current) || normalizeQuoraProfileUrl(itemKey)
    const currentCoordinatorKey = getCoordinatorItemQueueKey(current, itemKey)
    const now = Date.now()
    const nextItem = transitionCoordinatorItemFromProgress(current, record, mapped, {
        now,
        terminalAtFallback: 'record'
    })
    if(!isTerminalCoordinatorStatus(nextItem.status)) return {changed: false, reason: 'terminal-transition-rejected'}

    const authorityResult = await coordinatorAuthority.applyWithinStorageUpdate({
        operationKind: 'terminal-progress-active',
        rowKey: itemKey,
        expectedAttemptId,
        expectedAttemptNumber,
        reason: 'ordinaryMutation',
        metricPath: 'reconcile.terminalProgressActive.save',
        deferProjectionSave: true,
        projectionReconcileDelayMs: 30000,
        currentAuthorityState,
        allowCurrentAuthorityState: true,
        mutate(currentItem, context) {
            if(!isActiveCoordinatorStatus(currentItem?.status)) {
                return context.reject('row-changed')
            }
            if((getCoordinatorItemHref(currentItem) || normalizeQuoraProfileUrl(itemKey)) !== href ||
                getCoordinatorItemQueueKey(currentItem, itemKey) !== currentCoordinatorKey) {
                return context.reject('row-target-changed-before-authority-apply')
            }
            if(hasMismatchedCoordinatorAttempt(currentItem, record)) {
                return context.reject('progress-attempt-mismatch')
            }
            const transitionedItem = transitionCoordinatorItemFromProgress(currentItem, record, mapped, {
                now: Date.now(),
                terminalAtFallback: 'record'
            })
            if(!isTerminalCoordinatorStatus(transitionedItem.status)) {
                return context.reject('terminal-transition-rejected')
            }
            return transitionedItem
        }
    })

    if(authorityResult?.accepted !== true || authorityResult?.durable !== true) {
        return {
            changed: false,
            reason: authorityResult?.reason || 'authority-apply-failed'
        }
    }

    currentAuthorityState = coordinatorAuthority.current()
    const nextQueue = currentAuthorityState.queue
    const durableItem = authorityResult.nextRow || nextQueue[itemKey] || nextItem
    const affectedRunIds = new Set()
    if(durableItem.runId) affectedRunIds.add(durableItem.runId)
    if(current.runId) affectedRunIds.add(current.runId)
    if(href) {
        for(const runId of getCoordinatorRunIdsForHref(runs, href)) {
            affectedRunIds.add(runId)
        }
    }
    const nextRuns = affectedRunIds.size
        ? recomputeCoordinatorRuns(nextQueue, runs, affectedRunIds)
        : runs
    const runsChanged = affectedRunIds.size && JSON.stringify(nextRuns) !== JSON.stringify(runs)
    if(runsChanged) {
        let derivedSaved = true
        try {
            derivedSaved = await saveCoordinatorState({
                runs: nextRuns,
                progress: undefined
            }, {
                queue: false,
                runs: true,
                progress: false,
                reason: 'reconcile',
                queueOperation: 'terminal-progress-active-derived',
                queueChangedRows: 0
            })
        }
        catch(error) {
            derivedSaved = false
            recordCoordinatorDiagnosticEvent(
                'terminal-progress-active-derived-save-failed',
                error?.message || 'Active terminal progress reconcile derived save failed'
            )
        }
        if(derivedSaved === false) {
            incrementQueueWakeupMetric('reconcile.terminalProgressActive.derivedSaveFailed')
            scheduleCoordinatorReconcile(1000, {
                reason: 'terminal-progress-active-derived-save-failed',
                edgeTriggered: true
            })
        }
    }

    return {
        changed: true,
        status: durableItem.status,
        href,
        tabId: getPersistedQueuedTabId(current, record),
        progressChanged: false
    }
}

async function settleDurableCoordinatorItemFromTerminalProgress(itemKey = '', expectedItem = null, record = null, options = {}) {
    if(!itemKey || !expectedItem || typeof expectedItem !== 'object') return {changed: false, reason: 'invalid-item'}
    if(isTerminalCoordinatorStatus(expectedItem.status) || !isCoordinatorQueueAuthoritativeItem(expectedItem)) {
        return {changed: false, reason: 'invalid-settlement-item'}
    }
    if(!record || !isTerminalProfileNukeRecord(record)) return {changed: false, reason: 'missing-terminal-progress'}
    if(hasMismatchedCoordinatorAttempt(expectedItem, record)) return {changed: false, reason: 'progress-attempt-mismatch'}

    const mapped = getCoordinatorStatusFromProgress(record)
    if(!isTerminalCoordinatorStatus(mapped.status)) return {changed: false, reason: 'nonterminal-progress'}

    let currentAuthorityState = options.currentAuthorityState?.queue && options.currentAuthorityState?.runs
        ? {
            stored: options.currentAuthorityState.stored || {},
            queue: normalizeCoordinatorMap(cloneCoordinatorAuthorityValue(options.currentAuthorityState.queue || {})),
            runs: normalizeCoordinatorMap(cloneCoordinatorAuthorityValue(options.currentAuthorityState.runs || {})),
            progress: cloneCoordinatorAuthorityValue(options.currentAuthorityState.progress || {})
        }
        : null
    if(!currentAuthorityState) {
        currentAuthorityState = await loadCoordinatorQueueRunsProgressProjection({
            metricPath: 'terminalSettlement.terminalProgress.load'
        })
    }

    const current = currentAuthorityState.queue?.[itemKey] || null
    if(!current || isTerminalCoordinatorStatus(current.status) || !isCoordinatorQueueAuthoritativeItem(current)) {
        return {changed: false, reason: 'row-changed'}
    }
    const expectedAttemptId = getAttemptIdFromValue(expectedItem)
    const expectedAttemptNumber = getAttemptNumberFromValue(expectedItem)
    if(expectedAttemptId && getAttemptIdFromValue(current) !== expectedAttemptId) return {changed: false, reason: 'attempt-changed'}
    if(expectedAttemptNumber && getAttemptNumberFromValue(current) !== expectedAttemptNumber) return {changed: false, reason: 'attempt-changed'}
    if(hasMismatchedCoordinatorAttempt(current, record)) return {changed: false, reason: 'progress-attempt-mismatch'}

    const href = getCoordinatorItemHref(current) || normalizeQuoraProfileUrl(itemKey)
    const currentCoordinatorKey = getCoordinatorItemQueueKey(current, itemKey)
    const nextItem = transitionCoordinatorItemFromProgress(current, record, mapped, {
        now: Date.now(),
        terminalAtFallback: 'record'
    })
    if(!isTerminalCoordinatorStatus(nextItem.status)) return {changed: false, reason: 'terminal-transition-rejected'}

    const authorityResult = await coordinatorAuthority.applyWithinStorageUpdate({
        operationKind: 'terminal-progress-settlement',
        rowKey: itemKey,
        expectedAttemptId,
        expectedAttemptNumber,
        reason: 'ordinaryMutation',
        metricPath: 'terminalSettlement.terminalProgress.save',
        deferProjectionSave: true,
        projectionReconcileDelayMs: 30000,
        currentAuthorityState,
        allowCurrentAuthorityState: true,
        mutate(currentItem, context) {
            if(isTerminalCoordinatorStatus(currentItem?.status) || !isCoordinatorQueueAuthoritativeItem(currentItem)) {
                return context.reject('row-changed')
            }
            if((getCoordinatorItemHref(currentItem) || normalizeQuoraProfileUrl(itemKey)) !== href ||
                getCoordinatorItemQueueKey(currentItem, itemKey) !== currentCoordinatorKey) {
                return context.reject('row-target-changed-before-authority-apply')
            }
            if(hasMismatchedCoordinatorAttempt(currentItem, record)) {
                return context.reject('progress-attempt-mismatch')
            }
            const transitionedItem = transitionCoordinatorItemFromProgress(currentItem, record, mapped, {
                now: Date.now(),
                terminalAtFallback: 'record'
            })
            if(!isTerminalCoordinatorStatus(transitionedItem.status)) {
                return context.reject('terminal-transition-rejected')
            }
            return transitionedItem
        }
    })
    if(authorityResult?.accepted !== true || authorityResult?.durable !== true) {
        return {changed: false, reason: authorityResult?.reason || 'authority-apply-failed'}
    }

    currentAuthorityState = coordinatorAuthority.current()
    const nextQueue = currentAuthorityState.queue
    const durableItem = authorityResult.nextRow || nextQueue[itemKey] || nextItem
    const affectedRunIds = new Set()
    if(durableItem.runId) affectedRunIds.add(durableItem.runId)
    if(current.runId) affectedRunIds.add(current.runId)
    for(const runId of getCoordinatorRunIdsForHref(currentAuthorityState.runs || {}, href)) {
        affectedRunIds.add(runId)
    }
    if(affectedRunIds.size) {
        const nextRuns = recomputeCoordinatorRuns(nextQueue, currentAuthorityState.runs || {}, affectedRunIds)
        if(JSON.stringify(nextRuns) !== JSON.stringify(currentAuthorityState.runs || {})) {
            await saveCoordinatorState({
                runs: nextRuns,
                progress: undefined
            }, {
                queue: false,
                runs: true,
                progress: false,
                reason: 'reconcile',
                queueOperation: 'terminal-progress-settlement-derived',
                queueChangedRows: 0
            }).catch(error => {
                recordCoordinatorDiagnosticEvent(
                    'terminal-progress-settlement-derived-save-failed',
                    error?.message || 'Terminal progress settlement derived save failed'
                )
                scheduleCoordinatorReconcile(1000, {
                    reason: 'terminal-progress-settlement-derived-save-failed',
                    edgeTriggered: true
                })
                return false
            })
        }
    }

    return {
        changed: true,
        status: durableItem.status,
        href,
        itemKey,
        item: durableItem
    }
}

async function reconcileUnconfirmedQueuedRuntimeActor(tabId = null, reason = 'reconcile-unconfirmed-runtime') {
    const normalizedTabId = normalizeTabId(tabId)
    if(!normalizedTabId) return {changed: false, reason: 'invalid-tab'}

    const metadata = getQueuedTabMetadata(normalizedTabId)
    if(!metadata) {
        detachQueuedTabRuntimeState(normalizedTabId, reason)
        return {changed: true, detached: true, closed: false, reason: 'metadata-missing'}
    }

    const confirmed = await promiseWithTimeout(
        confirmQueuedTabDurablyActive(metadata, {id: normalizedTabId}, metadata),
        QUEUED_TAB_ACTION_CLAIM_NUDGE_TIMEOUT_MS,
        'provisional queued tab durable confirmation'
    ).catch(() => false)
    if(confirmed) return {changed: true, confirmed: true, reason: 'confirmed'}

    const href = normalizeQuoraProfileUrl(metadata.profileHref || metadata.targetProfileHref || '')
    const record = href ? profileNukeProgress?.[href] || null : null
    const actionPhaseProgress = hasActiveQueuedTabActionPhaseProgress(record, metadata)
    if(!actionPhaseProgress && isFreshQueuedTabRuntimeStartup(metadata)) {
        incrementQueueWakeupMetric('reconcile.deferred.freshRuntimeStartup')
        scheduleCoordinatorReconcile(1000, {
            reason: `${reason || 'reconcile'}-fresh-runtime-startup`,
            edgeTriggered: true,
            allowBeforeQuora: true
        })
        return {
            changed: false,
            deferred: true,
            reason: 'fresh-runtime-startup'
        }
    }
    if(!actionPhaseProgress) {
        markQueuedTabClosing(normalizedTabId, reason)
        detachQueuedTabRuntimeState(normalizedTabId, reason)
        try {
            await browser.tabs.remove(normalizedTabId)
        }
        catch {}
    }
    else {
        detachQueuedTabRuntimeState(normalizedTabId, reason)
    }

    return {
        changed: true,
        detached: true,
        closed: !actionPhaseProgress,
        actionPhaseProgress,
        reason: actionPhaseProgress ? 'detached-action-phase-progress' : 'closed-unconfirmed-provisional'
    }
}

async function runCoordinatorAuthorityReconcileActions(reason = 'coordinator-authority-reconcile', options = {}) {
    const actionBudget = getCoordinatorReconcileActionBudget(options)
    let currentAuthorityState = options.queueOnlyAuthority === true
        ? (options.forceDurableQueueReload === true
            ? null
            : getHydratedCoordinatorAuthorityState('reconcile.authority.queueOnly.usedResidentAuthority')) ||
            await loadCoordinatorQueueRunsProjection({
                metricPath: options.forceDurableQueueReload === true
                    ? 'reconcile.authority.queueOnly.forceDurableReload'
                    : 'reconcile.authority.queueOnly.load'
            })
        : await loadCoordinatorCurrentAuthorityState({
            [COORDINATOR_PAUSED_KEY]: false
        })
    const queue = currentAuthorityState.queue
    const progress = options.queueOnlyAuthority === true ? {} : currentAuthorityState.progress
    const paused = !!currentAuthorityState.stored?.[COORDINATOR_PAUSED_KEY]
    const liveProfileTabsByHref = await getLiveProfileTabsByHref()
    let actions = 0
    let adopted = 0
    let requeued = 0
    let failed = 0
    let skipped = 0
    let runtimeDetached = 0
    let runtimeClosed = 0
    let runtimeRecovered = 0
    let confirmed = 0
    let terminalized = 0
    let budgetExhausted = false

    if(options.queueOnlyAuthority !== true) {
        profileNukeProgress = progress
    }
    if(paused) return {changed: false, paused: true, actionBudget, actions: 0}

    const preTerminalizedExhausted = await applyCoordinatorQueueMachineEvent({
        type: 'EXHAUSTED_ROLLBACK_SETTLE',
        items: Object.values(queue),
        options: {
            limit: actionBudget,
            recoverReason: 'executor-plan-active-transition-retry-budget-recovered',
            terminalizeReason: 'executor-plan-active-transition-retry-budget-exhausted',
            queueOnlyAuthority: options.queueOnlyAuthority === true,
            recoverActiveTransitionFailures: true,
            recoverQueueLoadPressure: true,
            liveProfileTabsByHref
        }
    }).catch(error => ({
        changed: false,
        terminalized: 0,
        recovered: 0,
        keys: [],
        reason: 'batch-terminalize-error',
        error: error?.message || `${error || ''}`
    }))
    if(preTerminalizedExhausted?.recovered > 0) {
        actions += preTerminalizedExhausted.recovered
        requeued += preTerminalizedExhausted.recovered
        currentAuthorityState = coordinatorAuthority.current()
        incrementQueueWakeupMetric('reconcile.changed.recoveredExhaustedRolledBack', preTerminalizedExhausted.recovered)
    }
    if(preTerminalizedExhausted?.terminalized > 0) {
        actions += preTerminalizedExhausted.terminalized
        terminalized += preTerminalizedExhausted.terminalized
        currentAuthorityState = coordinatorAuthority.current()
        incrementQueueWakeupMetric('reconcile.changed.terminalizedExhaustedRolledBack', preTerminalizedExhausted.terminalized)
    }

    for(const tabId of queueRuntime.listActiveQueuedTabIds()) {
        if(actions >= actionBudget) {
            budgetExhausted = true
            break
        }
        if(hasDurableQueueMatchForRuntimeTab(tabId, queue, progress)) continue

        const result = await reconcileUnconfirmedQueuedRuntimeActor(tabId, reason)
        if(!result.changed) continue
        actions += 1
        if(result.confirmed) confirmed += 1
        if(result.detached) runtimeDetached += 1
        if(result.closed) runtimeClosed += 1
    }

    for(const itemKey of Object.keys(queue)) {
        if(actions >= actionBudget) {
            budgetExhausted = true
            break
        }
        const latestQueue = currentAuthorityState?.queue || queue
        const item = latestQueue[itemKey] || null
        if(!isActiveCoordinatorStatus(item?.status)) continue

        const currentProgress = options.queueOnlyAuthority === true
            ? progress
            : currentAuthorityState?.progress || progress
        const loadedRecord = getCoordinatorProgressRecordForItem(itemKey, item, currentProgress)
        const record = loadedRecord && hasMismatchedCoordinatorAttempt(item, loadedRecord)
            ? null
            : loadedRecord
        if(isTerminalProfileNukeRecord(record)) {
            const result = await applyCoordinatorQueueMachineEvent({
                type: 'ACTIVE_TERMINAL_PROGRESS',
                itemKey,
                item,
                record,
                reason,
                currentAuthorityState,
                timeoutMs: QUEUE_CRITICAL_STORAGE_UPDATE_TIMEOUT_MS
            })
                .catch(error => ({
                    changed: false,
                    reason: 'active-terminal-progress-reconcile-error',
                    error: error?.message || `${error || ''}`
                }))
            if(!result.changed) continue

            actions += 1
            if(result.status === 'skipped') skipped += 1
            else if(isTerminalCoordinatorStatus(result.status)) failed += 1
            if(result.tabId) {
                cleanupQueuedTabMetadataOnly(result.tabId)
                try {
                    await browser.tabs.remove(result.tabId)
                }
                catch {}
            }
            currentAuthorityState = coordinatorAuthority.current()
            continue
        }
        if(hasConfirmedLiveRuntimeActorForCoordinatorItem(item, record, liveProfileTabsByHref)) {
            const result = await recoverConfirmedLiveRuntimeActorForCoordinatorItem(
                item,
                record,
                `${reason || 'reconcile'}-confirmed-live-runtime`
            )
            if(result.changed) {
                actions += 1
                runtimeRecovered += 1
            }
            continue
        }

        if(normalizeCoordinatorActionLease(item.actionLease)) {
            const result = await releaseMissingActionLeaseForActiveCoordinatorItem(itemKey, item, reason, {
                expectedRecord: record,
                currentAuthorityState,
                timeoutMs: QUEUE_CRITICAL_STORAGE_UPDATE_TIMEOUT_MS
            }).catch(error => ({
                changed: false,
                reason: 'active-action-lease-release-error',
                error: error?.message || `${error || ''}`
            }))
            if(!result.changed &&
                /^(?:action-lease-tab-still-live|action-lease-tab-lookup-(?:timeout|deferred))$/.test(`${result.reason || ''}`)) {
                incrementQueueWakeupMetric(`reconcile.deferred.${normalizeStorageMetricPathName(result.reason || 'action-lease-live')}`)
                scheduleCoordinatorReconcile(1000, {
                    reason: `${reason || 'reconcile'}-${result.reason || 'action-lease-live'}`,
                    edgeTriggered: true,
                    allowBeforeQuora: true
                })
                continue
            }
            if(result.changed) {
                actions += 1
                currentAuthorityState = coordinatorAuthority.current()
                if(result.terminalized === true) {
                    terminalized += 1
                    continue
                }
                scheduleCoordinatorQueueResume(1000, `${reason || 'reconcile'}-action-lease-released`)
                scheduleCoordinatorReconcile(1000, {
                    reason: `${reason || 'reconcile'}-action-lease-released`,
                    edgeTriggered: true
                })
                if(actions >= actionBudget) {
                    budgetExhausted = true
                    continue
                }

                const releasedItem = currentAuthorityState.queue?.[itemKey] || null
                if(!releasedItem || !isActiveCoordinatorStatus(releasedItem.status)) continue
                if(normalizeCoordinatorActionLease(releasedItem.actionLease)) continue

                const releasedLoadedRecord = getCoordinatorProgressRecordForItem(itemKey, releasedItem, currentAuthorityState.progress || progress)
                const releasedRecord = releasedLoadedRecord && hasMismatchedCoordinatorAttempt(releasedItem, releasedLoadedRecord)
                    ? null
                    : releasedLoadedRecord
                const releasedLiveTab = await getTokenMatchedLiveOrPersistedTabForCoordinatorItem(
                    releasedItem,
                    releasedRecord,
                    itemKey,
                    liveProfileTabsByHref
                )
                if(releasedLiveTab) {
                    const adoptedTab = await adoptLiveCoordinatorQueuedTab(releasedItem, itemKey, releasedLiveTab, SERVICE_WORKER_QUEUE_OWNER_ID, {currentAuthorityState})
                    if(adoptedTab) {
                        actions += 1
                        adopted += 1
                        currentAuthorityState = coordinatorAuthority.current()
                    }
                    continue
                }

                const requeueResult = await applyCoordinatorQueueMachineEvent({
                    type: 'ACTIVE_MISSING_TAB',
                    itemKey,
                    item: releasedItem,
                    record: releasedRecord,
                    reason,
                    currentAuthorityState,
                    skipActionPhaseProtection: true,
                    skipFreshContentReadiness: true,
                    skipFreshOpenDeferralAfterLeaseRelease: true,
                    timeoutMs: QUEUE_CRITICAL_STORAGE_UPDATE_TIMEOUT_MS
                }).catch(error => ({
                    changed: false,
                    reason: 'active-row-requeue-after-lease-release-error',
                    error: error?.message || `${error || ''}`
                }))
                if(requeueResult.changed) {
                    actions += 1
                    if(requeueResult.status === 'queued') {
                        requeued += 1
                        currentAuthorityState = coordinatorAuthority.current()
                        const requeuedItem =
                            currentAuthorityState.queue?.[requeueResult.itemKey || itemKey] ||
                            currentAuthorityState.queue?.[itemKey] ||
                            requeueResult.item ||
                            null
                        if(isExhaustedRolledBackQueuedTabRetry(requeuedItem)) {
                            const terminalizeResult = await applyCoordinatorQueueMachineEvent({
                                type: shouldRecoverExhaustedRolledBackQueuedTabRetry(requeuedItem, {
                                    recoverActiveTransitionFailures: true,
                                    recoverQueueLoadPressure: true,
                                    serviceWorkerOwned: true
                                })
                                    ? 'EXHAUSTED_ROLLBACK_RECOVER'
                                    : 'EXHAUSTED_ROLLBACK_TERMINATE',
                                itemKey: requeueResult.itemKey || itemKey,
                                item: requeuedItem,
                                options: {
                                    currentAuthorityState,
                                    reason: shouldRecoverExhaustedRolledBackQueuedTabRetry(requeuedItem, {
                                        recoverActiveTransitionFailures: true,
                                        recoverQueueLoadPressure: true,
                                        serviceWorkerOwned: true
                                    })
                                        ? 'executor-plan-active-transition-retry-budget-recovered'
                                        : 'executor-plan-active-transition-retry-budget-exhausted'
                                }
                            }).catch(error => ({
                                changed: false,
                                reason: 'terminalize-error',
                                error: error?.message || `${error || ''}`
                            }))
                            if(terminalizeResult?.changed) {
                                actions += 1
                                if(terminalizeResult.recovered === true) {
                                    requeued += 1
                                }
                                else {
                                    terminalized += 1
                                }
                                currentAuthorityState = coordinatorAuthority.current()
                            }
                            else {
                                scheduleCoordinatorQueueResume(1000, `${reason || 'reconcile'}-active-requeued-after-lease-release`)
                            }
                        }
                        else {
                            scheduleCoordinatorQueueResume(1000, `${reason || 'reconcile'}-active-requeued-after-lease-release`)
                        }
                    }
                    else if(requeueResult.adopted === true) {
                        adopted += 1
                        currentAuthorityState = coordinatorAuthority.current()
                    }
                    else if(requeueResult.terminalized === true) {
                        terminalized += 1
                        currentAuthorityState = coordinatorAuthority.current()
                    }
                    else if(isTerminalCoordinatorStatus(requeueResult.status)) failed += 1
                    if(requeueResult.tabId) {
                        cleanupQueuedTabMetadataOnly(requeueResult.tabId)
                        try {
                            await browser.tabs.remove(requeueResult.tabId)
                        }
                        catch {}
                    }
                }
                continue
            }
        }

        const nonProfileLandingUrl = record?.lastUrl || record?.errorPageUrl || ''
        if(shouldTerminalizeCoordinatorNonProfileLanding(item, record, itemKey, nonProfileLandingUrl)) {
            const result = await applyCoordinatorQueueMachineEvent({
                type: 'ACTIVE_NON_PROFILE_LANDING',
                itemKey,
                landingUrl: nonProfileLandingUrl,
                expectedAttemptId: getAttemptIdFromValue(item),
                expectedAttemptNumber: getAttemptNumberFromValue(item),
                reconcileReason: reason
            }, {
                reason: 'reconcile'
            }).catch(error => ({
                changed: false,
                reason: 'active-row-non-profile-terminalize-error',
                error: error?.message || `${error || ''}`
            }))
            if(result.changed) {
                actions += 1
                if(result.status === 'skipped') skipped += 1
                else if(isTerminalCoordinatorStatus(result.status)) failed += 1
                if(result.tabId) {
                    cleanupQueuedTabMetadataOnly(result.tabId)
                    const tab = await getQueuedExecutorTabWithTimeout(result.tabId, 'non-profile-landing-close')
                    if(tab && isSafeToCloseNonProfileLandingTab(item, record, tab)) {
                        await browser.tabs.remove(result.tabId).catch(() => {})
                    }
                }
                continue
            }
        }

        const tokenMatchedTab = await getTokenMatchedLiveOrPersistedTabForCoordinatorItem(item, record, itemKey, liveProfileTabsByHref)
        if(tokenMatchedTab) {
            const adoptedTab = await adoptLiveCoordinatorQueuedTab(item, itemKey, tokenMatchedTab, SERVICE_WORKER_QUEUE_OWNER_ID, {currentAuthorityState})
            if(adoptedTab) {
                actions += 1
                adopted += 1
                currentAuthorityState = coordinatorAuthority.current()
                continue
            }
        }
        const reclaimTab = getLiveProfileTabForActiveCoordinatorReclaim(item, record, itemKey, liveProfileTabsByHref)
        if(reclaimTab) {
            const adoptedTab = await adoptLiveCoordinatorQueuedTab(item, itemKey, reclaimTab, SERVICE_WORKER_QUEUE_OWNER_ID, {currentAuthorityState})
            if(adoptedTab) {
                actions += 1
                adopted += 1
                currentAuthorityState = coordinatorAuthority.current()
                continue
            }
        }

        const freshStartupActor = getFreshQueuedTabStartupRuntimeActorForCoordinatorItem(item, record, itemKey)
        if(freshStartupActor) {
            incrementQueueWakeupMetric('reconcile.deferred.freshRuntimeStartup')
            scheduleCoordinatorReconcile(1000, {
                reason: `${reason || 'reconcile'}-fresh-runtime-startup`,
                edgeTriggered: true,
                allowBeforeQuora: true
            })
            continue
        }
        const activeLease = normalizeCoordinatorActionLease(item.actionLease)
        if(activeLease && !isCoordinatorActionLeaseExpired(activeLease)) {
            incrementQueueWakeupMetric('reconcile.deferred.activeActionLease')
            scheduleCoordinatorReconcile(1000, {
                reason: `${reason || 'reconcile'}-active-action-lease`,
                edgeTriggered: true,
                allowBeforeQuora: true
            })
            continue
        }

        const requeueReason = /fast-executor-preflight$/.test(`${reason || ''}`) &&
            (Number.parseInt(item.retryAttempt, 10) || 0) >= (Number.parseInt(item.maxRetries, 10) || 0)
            ? 'executor-plan-active-transition-retry-budget-recovered'
            : reason
        const result = await applyCoordinatorQueueMachineEvent({
            type: 'ACTIVE_MISSING_TAB',
            itemKey,
            item,
            record,
            reason: requeueReason,
            currentAuthorityState,
            skipFreshContentReadiness: true,
            skipFreshOpenDeferralAfterLeaseRelease: true,
            timeoutMs: QUEUE_CRITICAL_STORAGE_UPDATE_TIMEOUT_MS
        })
            .catch(error => ({
                changed: false,
                reason: 'active-row-requeue-error',
                error: error?.message || `${error || ''}`
            }))
        if(!result.changed) continue

        actions += 1
        if(result.adopted === true) {
            adopted += 1
            currentAuthorityState = coordinatorAuthority.current()
        }
        else if(result.terminalized === true) {
            terminalized += 1
            currentAuthorityState = coordinatorAuthority.current()
        }
        else if(result.status === 'queued') {
            requeued += 1
            currentAuthorityState = coordinatorAuthority.current()
            const requeuedItem =
                currentAuthorityState.queue?.[result.itemKey || itemKey] ||
                currentAuthorityState.queue?.[itemKey] ||
                result.item ||
                null
            if(isExhaustedRolledBackQueuedTabRetry(requeuedItem)) {
                const terminalizeResult = await applyCoordinatorQueueMachineEvent({
                    type: options.queueOnlyAuthority === true
                        ? 'EXHAUSTED_ROLLBACK_RECOVER'
                        : 'EXHAUSTED_ROLLBACK_TERMINATE',
                    itemKey: result.itemKey || itemKey,
                    item: requeuedItem,
                    options: {
                        currentAuthorityState,
                        reason: options.queueOnlyAuthority === true
                            ? 'executor-plan-active-transition-retry-budget-recovered'
                            : 'executor-plan-active-transition-retry-budget-exhausted'
                    }
                }).catch(error => ({
                    changed: false,
                    reason: 'terminalize-error',
                    error: error?.message || `${error || ''}`
                }))
                if(terminalizeResult?.changed) {
                    actions += 1
                    if(terminalizeResult.recovered === true) {
                        requeued += 1
                    }
                    else {
                        terminalized += 1
                    }
                    currentAuthorityState = coordinatorAuthority.current()
                }
                else {
                    scheduleCoordinatorQueueResume(1000, `${reason || 'reconcile'}-active-requeued`)
                }
            }
            else {
                scheduleCoordinatorQueueResume(1000, `${reason || 'reconcile'}-active-requeued`)
            }
        }
        else if(isTerminalCoordinatorStatus(result.status)) failed += 1
        if(result.tabId) {
            cleanupQueuedTabMetadataOnly(result.tabId)
            try {
                await browser.tabs.remove(result.tabId)
            }
            catch {}
        }
    }

    if(runtimeDetached) incrementQueueWakeupMetric('reconcile.changed.runtimeDetached', runtimeDetached)
    if(runtimeClosed) incrementQueueWakeupMetric('reconcile.changed.runtimeClosed', runtimeClosed)
    if(runtimeRecovered) incrementQueueWakeupMetric('reconcile.changed.runtimeRecovered', runtimeRecovered)
    if(confirmed) incrementQueueWakeupMetric('reconcile.changed.runtimeConfirmed', confirmed)
    if(adopted) incrementQueueWakeupMetric('reconcile.changed.activeAdopted', adopted)
    if(terminalized) incrementQueueWakeupMetric('reconcile.changed.activeTerminalized', terminalized)
    if(requeued) incrementQueueWakeupMetric('reconcile.changed.activeRequeued', requeued)
    if(failed) incrementQueueWakeupMetric('reconcile.changed.activeFailed', failed)
    if(skipped) incrementQueueWakeupMetric('reconcile.changed.activeSkipped', skipped)
    if(budgetExhausted) incrementQueueWakeupMetric('reconcile.rescheduled.budgetExhausted')

    return {
        changed: actions > 0,
        actions,
        actionBudget,
        budgetExhausted,
        runtimeDetached,
        runtimeClosed,
        runtimeRecovered,
        confirmed,
        adopted,
        terminalized,
        requeued,
        failed,
        skipped,
        paused: false
    }
}

async function observeCoordinatorReconcileSnapshot(reason = 'reconcile-observe', options = {}) {
    const currentAuthorityState = await loadCoordinatorCurrentAuthorityState({
        [COORDINATOR_PAUSED_KEY]: false
    })
    const queue = currentAuthorityState.queue || {}
    const progress = currentAuthorityState.progress || {}
    const paused = !!currentAuthorityState.stored?.[COORDINATOR_PAUSED_KEY]
    const liveProfileTabsByHref = options.includeLiveTabs === false
        ? new Map()
        : await getLiveProfileTabsByHref()
    const durable = getCoordinatorQueueWorkCounts(queue)
    const mismatch = getCoordinatorAuthorityMismatchCounts(queue, progress, liveProfileTabsByHref, options)

    return {
        reason,
        paused,
        hasStoredWork: hasStoredCoordinatorWork(queue),
        ...durable,
        ...getQueueWakeupMetricRuntimeSnapshot(),
        ...mismatch
    }
}

function recordActiveStorageWorkSnapshot(queue = {}, options = {}) {
    const context = getActiveStorageContext()
    if(!context) return

    const counts = getCoordinatorQueueWorkCounts(queue)
    context.durableActiveRows = counts.durableActiveRows
    context.durableQueuedRows = counts.durableQueuedRows
    context.durableTerminalRows = counts.durableTerminalRows
    if(options.paused !== undefined) context.paused = options.paused === true
}

function getStorageContextJournalDetails(context = {}) {
    const now = Date.now()
    const startedAt = Number.parseInt(context.startedAt, 10) || 0
    const finishedAt = Number.parseInt(context.finishedAt, 10) || 0
    const timedOutAt = Number.parseInt(context.timedOutAt, 10) || 0
    const effectiveEndAt = finishedAt || timedOutAt || now
    const queueWaitMs = startedAt
        ? Math.max(0, startedAt - (Number.parseInt(context.enqueuedAt, 10) || startedAt))
        : Math.max(0, effectiveEndAt - (Number.parseInt(context.enqueuedAt, 10) || effectiveEndAt))
    const runMs = startedAt ? Math.max(0, effectiveEndAt - startedAt) : 0
    const totalMs = Math.max(0, effectiveEndAt - (Number.parseInt(context.enqueuedAt, 10) || effectiveEndAt))

    return {
        updateToken: Number.parseInt(context.updateToken, 10) || 0,
        reason: context.reason || '',
        enqueuedAt: Number.parseInt(context.enqueuedAt, 10) || 0,
        startedAt,
        finishedAt,
        timedOutAt,
        queueWaitMs,
        runMs,
        totalMs,
        timedOut: context.didTimeout === true,
        timeoutMs: Number.parseInt(context.timeoutMs, 10) || 0,
        deadlineMissed: context.deadlineMissed === true,
        fallbackReturned: context.fallbackReturned === true,
        abandoned: context.abandoned === true,
        tailWedged: context.tailWedged === true,
        serializedTailRecovered: context.serializedTailRecovered === true,
        lateWriteSuppressed: context.lateWriteSuppressed === true,
        abortedOperation: context.abortedOperation || '',
        depth: Number.parseInt(context.depth, 10) || 0,
        maxNestedDepth: Number.parseInt(context.maxNestedDepth, 10) || 0,
        nestedUpdateCount: Number.parseInt(context.nestedUpdateCount, 10) || 0,
        timeoutPhase: context.timeoutPhase || '',
        currentPhase: context.currentPhase || '',
        storageGetCalls: Number.parseInt(context.storageGetCalls, 10) || 0,
        storageSetCalls: Number.parseInt(context.storageSetCalls, 10) || 0,
        saveCoordinatorStateCalls: Number.parseInt(context.saveCoordinatorStateCalls, 10) || 0,
        storageGetMs: Math.round(Number(context.storageGetMs) || 0),
        storageSetMs: Math.round(Number(context.storageSetMs) || 0),
        storageGetCumulativeMs: Math.round(Number(context.storageGetMs) || 0),
        storageSetCumulativeMs: Math.round(Number(context.storageSetMs) || 0),
        ownStorageGetMs: Math.round(getPhaseWallMs(context, 'storageGet')),
        ownStorageSetMs: Math.round(getPhaseWallMs(context, 'storageSet')),
        loadCoordinatorStateMs: Math.round(Number(context.loadCoordinatorStateMs) || 0),
        saveCoordinatorStateMs: Math.round(Number(context.saveCoordinatorStateMs) || 0),
        normalizeQueueMs: Math.round(Number(context.normalizeQueueMs) || 0),
        normalizeRunsMs: Math.round(Number(context.normalizeRunsMs) || 0),
        normalizeEventsMs: Math.round(Number(context.normalizeEventsMs) || 0),
        normalizeProgressMs: Math.round(Number(context.normalizeProgressMs) || 0),
        recomputeRunsMs: Math.round(Number(context.recomputeRunsMs) || 0),
        flushDiagnosticEventsMs: Math.round(Number(context.flushDiagnosticEventsMs) || 0),
        flushMilestonesMs: Math.round(Number(context.flushMilestonesMs) || 0),
        queueWalSegmentStorageGetMs: Math.round(Number(context.queueWalSegmentStorageGetMs) || 0),
        queueWalHydrateMs: Math.round(Number(context.queueWalHydrateMs) || 0),
        queueWalAppendPrepareMs: Math.round(Number(context.queueWalAppendPrepareMs) || 0),
        queueWalPhysicalPayloadMs: Math.round(Number(context.queueWalPhysicalPayloadMs) || 0),
        queueWalStorageSetMs: Math.round(Number(context.queueWalStorageSetMs) || 0),
        queueWalReplayVerifyMs: Math.round(Number(context.queueWalReplayVerifyMs) || 0),
        queueProjectionBuildMs: Math.round(Number(context.queueProjectionBuildMs) || 0),
        queueProjectionStorageSetMs: Math.round(Number(context.queueProjectionStorageSetMs) || 0),
        payloadBytes: Number.parseInt(context.payloadBytes, 10) || 0,
        payloadKeys: context.payloadKeys || '',
        durableActiveRows: Number.parseInt(context.durableActiveRows, 10) || 0,
        durableQueuedRows: Number.parseInt(context.durableQueuedRows, 10) || 0,
        durableTerminalRows: Number.parseInt(context.durableTerminalRows, 10) || 0,
        paused: context.paused === true
    }
}

function getStorageTimeoutBucket(context = {}) {
    const phase = `${context.currentPhase || ''}`.trim()
    if(!context.startedAt && (!phase || phase === 'beforeStart')) return 'timeout.beforeStart'
    if(phase === 'storageGet') return 'timeout.duringStorageGet'
    if(phase === 'storageSet') return 'timeout.duringStorageSet'
    if(phase === 'recomputeRuns') return 'timeout.duringRecomputeRuns'
    if(phase === 'flushDiagnosticEvents') return 'timeout.duringDiagnosticFlush'
    if(phase === 'flushMilestones') return 'timeout.duringMilestoneFlush'
    if(/^normalize/.test(phase)) return 'timeout.duringNormalize'
    return 'timeout.unknown'
}

function recordStorageIdleChurnCounters(context = {}) {
    const runtimeCounts = queueRuntime.getRuntimeCounts()
    const runtimeHasWork = runtimeCounts.activeQueuedTabs > 0 ||
        runtimeCounts.queuedTabActions > 0 ||
        runtimeCounts.pendingTabActions > 0
    const durableActiveRows = Number.parseInt(context.durableActiveRows, 10) || 0
    const durableQueuedRows = Number.parseInt(context.durableQueuedRows, 10) || 0
    const durableHasWork = durableActiveRows > 0 || durableQueuedRows > 0
    const progressProjectionOnlyWrite = (Number.parseInt(context.profileProgressProjectionOnlyWrites, 10) || 0) > 0 &&
        context.nonProgressProjectionWrite !== true &&
        !context.queueWriteOperation

    if(!runtimeHasWork) incrementQueueWakeupMetric('storageUpdate.noRuntimeWork')
    if(!durableHasWork) incrementQueueWakeupMetric('storageUpdate.noDurableWork')
    if(durableHasWork &&
        !runtimeHasWork &&
        context.paused !== true &&
        (durableActiveRows > 0 || !progressProjectionOnlyWrite) &&
        context.suppressDurableIdleResume !== true) {
        scheduleDurableQueueResumeFromIdleStorage(context)
    }
}

function scheduleDurableQueueResumeFromIdleStorage(context = {}) {
    const durableActiveRows = Number.parseInt(context.durableActiveRows, 10) || 0
    const durableQueuedRows = Number.parseInt(context.durableQueuedRows, 10) || 0
    if(context.paused === true) return false
    if(durableActiveRows <= 0 && durableQueuedRows <= 0) return false

    const reason = durableActiveRows > 0
        ? 'storage-idle-durable-active-work'
        : 'storage-idle-durable-queued-work'
    incrementQueueWakeupMetric('storageUpdate.durableWorkNoRuntime')
    scheduleCoordinatorQueueResume(1000, reason, {
        allowBeforeQuora: true
    })
    if(durableActiveRows > 0) {
        void runCoordinatorReconcileTick(reason, {
            allowBeforeQuora: true,
            skipStoredWorkCheck: true,
            awaitFill: true
        }).catch(() => null)
    }
    else if(durableQueuedRows > 0) {
        if(queuedTabFillPromise || coordinatorFastExecutorActiveUntil > Date.now()) {
            incrementQueueWakeupMetric('storageUpdate.durableQueuedWorkDeferredDuringFill')
        }
        else {
            void runCoordinatorQueueExecutorFastPath(reason, {
                awaitFill: true,
                returnAfterDurableActive: true,
                allowBeforeQuora: true,
                skipAuthorityReconcile: true,
                forceDurableQueueReload: true
            }).catch(() => null)
        }
    }
    return true
}

function scheduleQueuedOnlyDurableWorkContinuation(reason = 'queued-only-durable-work', options = {}) {
    const normalizedReason = `${reason || 'queued-only-durable-work'}`.trim() || 'queued-only-durable-work'
    incrementQueueWakeupMetric('reconcile.queuedOnlyFastResumeScheduled')
    scheduleCoordinatorQueueResume(1000, normalizedReason, {
        allowBeforeQuora: options.allowBeforeQuora === true
    })
    const runtimeCounts = queueRuntime.getRuntimeCounts()
    const detachedQueuedActions = runtimeCounts.queuedTabActions > 0 &&
        runtimeCounts.activeQueuedTabs <= 0 &&
        runtimeCounts.pendingTabActions <= 0
    if(coordinatorFastExecutorActiveUntil > Date.now() && !detachedQueuedActions) {
        incrementQueueWakeupMetric('reconcile.queuedOnlyFastResumeDeferredDuringFastExecutor')
        return true
    }
    if(detachedQueuedActions) incrementQueueWakeupMetric('reconcile.detachedQueuedActionsFastResumed')
    void runCoordinatorQueueExecutorFastPath(normalizedReason, {
        awaitFill: options.awaitFill !== false,
        returnAfterDurableActive: true,
        allowBeforeQuora: options.allowBeforeQuora === true,
        skipAuthorityReconcile: true,
        forceDurableQueueReload: false
    }).catch(() => null)
    return true
}

function kickQueuedWorkAfterSlotFreed(reason = 'queued-tab-slot-freed', options = {}) {
    const normalizedReason = `${reason || 'queued-tab-slot-freed'}`.trim() || 'queued-tab-slot-freed'
    scheduleQueuedWorkContinuation(normalizedReason)
    scheduleCoordinatorQueueResume(100, normalizedReason, {
        allowBeforeQuora: true
    })
    scheduleCoordinatorReconcile(100, {
        reason: normalizedReason,
        edgeTriggered: true,
        allowBeforeQuora: true
    })
    if(storageUpdateState.getDepth() > 0 || queuedTabFillPromise) {
        incrementQueueWakeupMetric('pump.slotFreed.fastKickDeferred')
        return false
    }
    incrementQueueWakeupMetric('pump.slotFreed.fastKick')
    void runCoordinatorQueueExecutorFastPath(normalizedReason, {
        awaitFill: options.awaitFill !== false,
        returnAfterDurableActive: true,
        allowBeforeQuora: true,
        skipAuthorityReconcile: true,
        forceDurableQueueReload: false
    }).catch(() => null)
    return true
}

function getPromiseLatchAgeMs(startedAt = 0) {
    const normalizedStartedAt = Number.parseInt(startedAt, 10) || 0
    return normalizedStartedAt ? Math.max(0, Date.now() - normalizedStartedAt) : 0
}

function isRuntimeAndStorageIdleForPromiseLatch() {
    return storageUpdateState.getDepth() <= 0 &&
        getSchedulerBlockingQueuedExecutorCount() <= 0 &&
        queueRuntime.getActiveQueuedTabCount() <= 0 &&
        queueRuntime.getPendingTabActionCount() <= 0
}

function hasVisibleQueuedTabFillPromise() {
    if(!queuedTabFillPromise) return false
    const pendingOnlyActiveTabs = queueRuntime.listPendingTabActionTabIds()
        .every(tabId => queueRuntime.hasActiveQueuedTab(tabId))
    return !(queueRuntime.getActiveQueuedTabCount() > 0 &&
        queueRuntime.getActivationIntentCount() <= 0 &&
        pendingOnlyActiveTabs)
}

function isExecutorRuntimeIdleForPromiseLatch() {
    return getSchedulerBlockingQueuedExecutorCount() <= 0 &&
        queueRuntime.getActiveQueuedTabCount() <= 0 &&
        queueRuntime.getPendingTabActionCount() <= 0
}

function isExecutorRuntimeDetachedForPromiseLatch() {
    return queueRuntime.getActiveQueuedTabCount() <= 0 &&
        queueRuntime.getPendingTabActionCount() <= 0 &&
        !hasVisibleQueuedTabFillPromise()
}

function shouldDeferScheduledResumeDuringFastExecutor(reason = '') {
    const normalizedReason = `${reason || ''}`.trim()
    if(/terminal-progress|active-transition|durable-(?:active|queued)-work|storage-idle-durable|queued-tab-release|active-missing-tab|runtime-authority-missing-active-row/.test(normalizedReason)) {
        incrementQueueWakeupMetric('pump.fastExecutor.deferredBypassProgressReason')
        return false
    }
    return coordinatorFastExecutorActiveUntil > Date.now() &&
        (coordinatorResumePromise ||
            queuedTabFillPromise ||
            getSchedulerBlockingQueuedExecutorCount() > 0 ||
            queueRuntime.getPendingTabActionCount() > 0)
}

function clearStaleQueuedTabFillPromise(reason = 'queued-tab-fill') {
    if(!queuedTabFillPromise) return false

    const ageMs = getPromiseLatchAgeMs(queuedTabFillPromiseStartedAt)
    const idleLatch = isRuntimeAndStorageIdleForPromiseLatch()
    const staleMs = idleLatch
        ? Math.min(QUEUED_TAB_IDLE_FILL_PROMISE_STALE_MS, QUEUED_TAB_FILL_PROMISE_STALE_MS)
        : QUEUED_TAB_FILL_PROMISE_STALE_MS
    if(ageMs < staleMs) return false

    resetQueuedTabFillState()
    incrementQueueWakeupMetric('pump.changed.clearedStaleFillPromise')
    if(idleLatch) incrementQueueWakeupMetric('pump.changed.clearedIdleStaleFillPromise')
    pushQueueWakeupJournalEntry({
        kind: 'state-change',
        name: 'queued-tab-fill-promise-stale-cleared',
        reason,
        result: 'state-changed',
        resultReason: 'stale-fill-promise-cleared',
        details: {
            ageMs,
            staleMs,
            idleLatch
        }
    })
    scheduleCoordinatorQueueResume(1000, `${reason || 'queued-tab-fill'}-stale-fill-promise`, {
        allowBeforeQuora: true
    })
    scheduleCoordinatorReconcile(1000, {
        reason: `${reason || 'queued-tab-fill'}-stale-fill-promise`,
        edgeTriggered: true,
        allowBeforeQuora: true
    })
    return true
}

function clearStaleCoordinatorReconcilePromise(reason = 'coordinator-reconcile') {
    if(!coordinatorReconcilePromise) return false

    const ageMs = getPromiseLatchAgeMs(coordinatorReconcilePromiseStartedAt)
    const idleLatch = isRuntimeAndStorageIdleForPromiseLatch()
    const executorIdle = isExecutorRuntimeIdleForPromiseLatch()
    const detachedExecutor = isExecutorRuntimeDetachedForPromiseLatch()
    const staleMs = idleLatch || executorIdle || detachedExecutor
        ? COORDINATOR_IDLE_RECONCILE_PROMISE_STALE_MS
        : COORDINATOR_RECONCILE_PROMISE_STALE_MS
    if(ageMs < staleMs) return false

    coordinatorReconcilePromise = null
    coordinatorReconcilePromiseStartedAt = 0
    incrementQueueWakeupMetric('reconcile.stalePromiseCleared')
    if(idleLatch) incrementQueueWakeupMetric('reconcile.idleStalePromiseCleared')
    else if(executorIdle) incrementQueueWakeupMetric('reconcile.executorIdleStalePromiseCleared')
    else if(detachedExecutor) incrementQueueWakeupMetric('reconcile.detachedExecutorStalePromiseCleared')
    pushQueueWakeupJournalEntry({
        kind: 'state-change',
        name: 'coordinator-reconcile-promise-stale-cleared',
        reason,
        result: 'state-changed',
        resultReason: 'stale-reconcile-promise-cleared',
        details: {
            ageMs,
            staleMs,
            idleLatch,
            executorIdle,
            detachedExecutor
        }
    })
    scheduleCoordinatorReconcile(1000, {
        reason: `${reason || 'coordinator-reconcile'}-stale-reconcile-promise`,
        edgeTriggered: true,
        allowBeforeQuora: true
    })
    return true
}

function clearStorageTimeoutPromiseLatches(reason = 'storage-timeout', timeoutMs = SPACE_FEED_STORAGE_UPDATE_TIMEOUT_MS) {
    const normalizedReason = `${reason || 'storage-timeout'}`.trim() || 'storage-timeout'
    const executorIdle = isExecutorRuntimeIdleForPromiseLatch()
    const recoveryStaleMs = Math.max(
        executorIdle
            ? QUEUED_TAB_IDLE_FILL_PROMISE_STALE_MS
            : QUEUED_TAB_FILL_PROMISE_STALE_MS,
        Number.parseInt(timeoutMs, 10) || SPACE_FEED_STORAGE_UPDATE_TIMEOUT_MS
    )
    const effectiveRecoveryStaleMs = executorIdle
        ? Math.min(recoveryStaleMs, QUEUED_TAB_IDLE_FILL_PROMISE_STALE_MS)
        : recoveryStaleMs
    let cleared = false

    if(queuedTabFillPromise && getPromiseLatchAgeMs(queuedTabFillPromiseStartedAt) >= effectiveRecoveryStaleMs) {
        resetQueuedTabFillState()
        cleared = true
        incrementQueueWakeupMetric('storageUpdate.clearedTimedOutFillPromise')
    }

    if(coordinatorReconcilePromise && getPromiseLatchAgeMs(coordinatorReconcilePromiseStartedAt) >= effectiveRecoveryStaleMs) {
        coordinatorReconcilePromise = null
        coordinatorReconcilePromiseStartedAt = 0
        cleared = true
        incrementQueueWakeupMetric('storageUpdate.clearedTimedOutReconcilePromise')
    }

    if(cleared) {
        pushQueueWakeupJournalEntry({
            kind: 'state-change',
            name: 'storage-timeout-promise-latches-cleared',
            reason: normalizedReason,
            result: 'state-changed',
            resultReason: 'storage-timeout-recovery',
            details: {
                recoveryStaleMs: effectiveRecoveryStaleMs,
                executorIdle
            }
        })
    }

    return cleared
}

function recoverStorageGetTimeoutSerializedTail(context = {}, reason = 'storage-timeout', serializedTailPromise = null) {
    if(!context || context.serializedTailRecovered === true) return false
    if(`${context.currentPhase || ''}`.trim() !== 'storageGet') return false

    const updateToken = Number.parseInt(context.updateToken, 10) || 0
    if(!updateToken) return false
    if(!storageUpdateState.canRecoverSerializedTail(context, serializedTailPromise)) return false

    context.serializedTailRecovered = true
    context.lateWriteSuppressed = true
    context.abortedOperation = 'storageGet'
    storageUpdateState.recoverSerializedTail(context)
    incrementQueueWakeupMetric('storageUpdate.serializedTailRecovered')
    incrementQueueWakeupMetric('storageUpdate.storageGetTailRecovered')
    pushQueueWakeupJournalEntry({
        kind: 'state-change',
        name: 'storage-get-timeout-serialized-tail-recovered',
        reason,
        result: 'state-changed',
        resultReason: 'storage-get-timeout-tail-recovered',
        details: getStorageContextJournalDetails(context)
    })
    flushPostStorageQueuedWorkContinuation()
    scheduleQueueWakeupMetricsFlush()
    return true
}

function requestStorageTimeoutRecoveryContinuation(context = {}, reason = 'storage-timeout') {
    if(context.timeoutRecoveryRequested === true) return false
    context.timeoutRecoveryRequested = true

    const normalizedReason = `${reason || context.reason || 'storage-timeout'}`.trim() || 'storage-timeout'
    const followupReason = `${normalizedReason}-recovery`
    incrementQueueWakeupMetric('storageUpdate.timeoutRecoveryRequested')
    clearStorageTimeoutPromiseLatches(followupReason, context.timeoutMs)
    requestPostStorageQueuedWorkContinuation(followupReason)
    scheduleCoordinatorQueueResume(1000, followupReason, {
        allowBeforeQuora: true
    })
    return true
}

function shouldContinueQueuedOnlyWorkWithFastExecutor(snapshot = {}) {
    if(!snapshot || snapshot.paused === true) return false
    if((Number.parseInt(snapshot.durableActiveRows, 10) || 0) > 0) return false
    if((Number.parseInt(snapshot.durableQueuedRows, 10) || 0) <= 0) return false
    if((Number.parseInt(snapshot.activeQueuedTabs, 10) || 0) > 0) return false
    if((Number.parseInt(snapshot.durablyActiveQueuedTabs, 10) || 0) > 0) return false
    if((Number.parseInt(snapshot.provisionalActiveQueuedTabs, 10) || 0) > 0) return false
    if((Number.parseInt(snapshot.pendingTabActions, 10) || 0) > 0) return false
    return true
}

function scheduleQueueWakeupMetricsFlush() {
    queueWakeupMetricsDirty = true
    if(!queueWakeupMetricsLoaded) return
    if(storageUpdateState.getDepth() > 0) return
    if(queueWakeupMetricsFlushPromise) return

    queueWakeupMetricsFlushPromise = Promise.resolve()
        .then(() => flushQueueWakeupMetrics())
        .finally(() => {
            queueWakeupMetricsFlushPromise = null
        })
}

async function flushQueueWakeupMetrics() {
    if(!queueWakeupMetricsLoaded) return
    if(!queueWakeupMetricsDirty) return
    queueWakeupMetricsDirty = false
    try {
        await promiseWithTimeout(
            coordinatorStorageAdapter.set({
                [QUEUE_WAKEUP_METRICS_KEY]: buildPersistedQueueWakeupMetrics(queueWakeupMetrics),
                [QUEUE_WAKEUP_METRICS_VIEW_KEY]: buildQueueWakeupMetricsView(queueWakeupMetrics)
            }),
            QUEUE_WAKEUP_METRICS_STORAGE_TIMEOUT_MS,
            'queue wakeup metrics flush'
        )
    }
    catch {
        queueWakeupMetricsDirty = true
    }
}

async function loadQueueWakeupMetrics() {
    try {
        const stored = await promiseWithTimeout(
            coordinatorStorageAdapter.get({[QUEUE_WAKEUP_METRICS_KEY]: queueWakeupMetrics}),
            QUEUE_WAKEUP_METRICS_STORAGE_TIMEOUT_MS,
            'queue wakeup metrics load'
        )
        queueWakeupMetrics = normalizeQueueWakeupMetrics(stored[QUEUE_WAKEUP_METRICS_KEY])
        queueWakeupMetricsLoaded = true
        queueWakeupMetricGeneration += 1
        const epoch = getQueueWakeupMetricEpoch()
        queueLoadThrottle = normalizeQueueLoadThrottle(epoch.queueLoadThrottle)
        const loadedVersion = `${epoch.extensionVersion || ''}`.trim()
        const currentVersion = getExtensionVersion()
        if(loadedVersion && currentVersion && loadedVersion !== currentVersion) {
            pendingQueueWakeupMetricsReset = null
            resetQueueWakeupMetricsEpoch('extension-updated')
            await flushQueueWakeupMetrics()
            return
        }
        const now = Date.now()
        if(!epoch.firstServiceWorkerStartedAt) epoch.firstServiceWorkerStartedAt = now
        epoch.lastServiceWorkerStartedAt = now
        incrementQueueWakeupMetric('serviceWorker.started')
        pushQueueWakeupJournalEntry({
            kind: 'state-change',
            name: 'service-worker-started',
            result: 'state-changed'
        })
    }
    catch {
        queueWakeupMetrics = makeEmptyQueueWakeupMetrics()
        queueLoadThrottle = makeEmptyQueueLoadThrottle()
        queueWakeupMetricsLoaded = false
        queueWakeupMetricsDirty = false
        queueWakeupMetricGeneration += 1
    }
}

async function refreshQueueWakeupMetricsViewForDashboard(reason = 'dashboard-refresh') {
    await ensureQueueWakeupMetricsLoaded().catch(() => null)
    const view = buildQueueWakeupMetricsView(queueWakeupMetrics)
    await metricStorageSet({[QUEUE_WAKEUP_METRICS_VIEW_KEY]: view}, {
        metricPath: `metricsView.${normalizeStorageMetricPathName(reason)}`
    }).catch(() => null)
    return {
        refreshed: true,
        reason,
        view
    }
}

function getFirstPositiveNumber(...values) {
    for(const value of values) {
        const number = Number.parseInt(value, 10) || 0
        if(number > 0) return number
    }
    return 0
}

function recordQueueWakeupPhaseSamplesFromProgress(record = {}) {
    if(!record || typeof record !== 'object') return

    const queuedAt = getFirstPositiveNumber(record.queuedAt, record.createdAt)
    const tabOpenedAt = getFirstPositiveNumber(record.tabOpenedAt, record.tabCreatedAt)
    const claimAcceptedAt = getFirstPositiveNumber(record.claimAcceptedAt, record.contentOpenedAt)
    const actionReadyAt = getFirstPositiveNumber(record.actionReadyAt)
    const actionStartedAt = getFirstPositiveNumber(
        record.blockAttemptedAt,
        record.muteAttemptedAt,
        record.unblockAttemptedAt,
        record.unmuteAttemptedAt
    )
    const terminalAt = getFirstPositiveNumber(record.terminalAt, record.blockedAt, record.unblockedAt, record.updatedAt)
    const slotReleasedAt = getFirstPositiveNumber(record.slotReleasedAt)

    if(queuedAt && tabOpenedAt && tabOpenedAt >= queuedAt) {
        recordQueueWakeupPhase('durableQueueToTabOpen', tabOpenedAt - queuedAt)
    }
    if(tabOpenedAt && claimAcceptedAt && claimAcceptedAt >= tabOpenedAt) {
        recordQueueWakeupPhase('tabOpenToClaimAccepted', claimAcceptedAt - tabOpenedAt)
    }
    if(claimAcceptedAt && actionStartedAt && actionStartedAt >= claimAcceptedAt) {
        recordQueueWakeupPhase('claimAcceptedToActionStart', actionStartedAt - claimAcceptedAt)
    }
    if(actionReadyAt && actionStartedAt && actionStartedAt >= actionReadyAt) {
        recordQueueWakeupPhase('actionReadyToActionStart', actionStartedAt - actionReadyAt)
    }
    if(actionStartedAt && terminalAt && terminalAt >= actionStartedAt) {
        recordQueueWakeupPhase('actionStartToTerminal', terminalAt - actionStartedAt)
    }
    if(terminalAt && slotReleasedAt && slotReleasedAt >= terminalAt) {
        recordQueueWakeupPhase('terminalToSlotRelease', slotReleasedAt - terminalAt)
    }
}

function pruneProfileNukeProgress(records, maxEntries = MAX_PROFILE_NUKE_PROGRESS_ENTRIES) {
    const entries = Object.entries(records || {})
        .filter(([key, value]) => !!key && value && typeof value === 'object')
        .sort((left, right) => {
            const leftUpdatedAt = Number.isFinite(left[1].updatedAt) ? left[1].updatedAt : 0
            const rightUpdatedAt = Number.isFinite(right[1].updatedAt) ? right[1].updatedAt : 0
            return rightUpdatedAt - leftUpdatedAt || left[0].localeCompare(right[0])
        })

    if(maxEntries > 0 && entries.length > maxEntries) {
        entries.length = maxEntries
    }

    return Object.fromEntries(entries)
}

function mergeProfileProgressEvents(existingEvents = [], incomingEvents = []) {
    const seen = new Set()
    const merged = []

    for(const value of [...existingEvents, ...incomingEvents]) {
        const normalized = `${value || ''}`.trim()
        if(!normalized || seen.has(normalized)) continue
        seen.add(normalized)
        merged.push(normalized)
    }

    merged.sort()
    return merged.slice(-12)
}

function mergeUniqueStringList(...values) {
    const seen = new Set()
    const merged = []

    for(const value of values.flat()) {
        const normalized = `${value || ''}`.trim()
        if(!normalized || seen.has(normalized)) continue
        seen.add(normalized)
        merged.push(normalized)
    }

    return merged
}

function getNormalizedProfileHrefList(values = []) {
    const seen = new Set()
    const normalized = []

    for(const value of values || []) {
        const href = normalizeQuoraProfileUrl(value)
        if(!href || seen.has(href)) continue
        seen.add(href)
        normalized.push(href)
    }

    return normalized
}

function normalizeCoordinatorRequestedUrl(value = '') {
    const normalized = normalizeTabTargetUrl(`${value || ''}`.trim())
    if(!normalized) return ''

    try {
        const url = new URL(normalized)
        url.hash = ''
        return url.toString()
    }
    catch {
        return normalized
    }
}

function isProfileResolutionMode(value = '') {
    return `${value || ''}`.trim() === QUEUED_PROFILE_RESOLUTION_MODE
}

function isProfileResolutionItem(item = null) {
    return item?.resolveProfileFromPage === true ||
        isProfileResolutionMode(item?.resolutionMode || '') ||
        `${item?.coordinatorKey || item?.dedupeKey || item?.requestedUrl || ''}`.trim().startsWith('resolve-profile:')
}

function stripProfileResolutionQueueKey(key = '') {
    const value = `${key || ''}`.trim()
    return value.startsWith('resolve-profile:') ? value.slice('resolve-profile:'.length) : value
}

function makeProfileResolutionQueueKey(value = '') {
    const requestedUrl = normalizeCoordinatorRequestedUrl(stripProfileResolutionQueueKey(value))
    return requestedUrl ? `resolve-profile:${requestedUrl}` : ''
}

function getProfileResolutionRequestedUrl(item = null, fallbackKey = '') {
    return normalizeCoordinatorRequestedUrl(stripProfileResolutionQueueKey(
        item?.requestedUrl ||
        item?.dedupeKey ||
        item?.coordinatorKey ||
        fallbackKey ||
        ''
    ))
}

function getEncodedQuoraPathRootToken(value = '') {
    const token = `${value || ''}`.split(/[-_/]/).filter(Boolean)[0] || ''
    return token.toLowerCase()
}

function isEncodedProfilePathOrTruncatedProfilePath(value = '') {
    const rootToken = getEncodedQuoraPathRootToken(value)
    return rootToken.length >= 3 && 'profile'.startsWith(rootToken)
}

function isLowConfidenceEncodedQuestionPath(value = '') {
    const path = `${value || ''}`.replace(/^[-_/]+|[-_/]+$/g, '')
    if(path.length < 12) return true
    if(isEncodedProfilePathOrTruncatedProfilePath(path)) return true

    const rootToken = getEncodedQuoraPathRootToken(path)
    return QUORA_NON_PROFILE_ROOT_PATHS.has(rootToken)
}

function getQuestionResolutionUrlFromEvidencePostUrl(postUrl = '') {
    try {
        const url = new URL(`${postUrl || ''}`)
        const decodedPath = decodeURIComponent(url.pathname || '').replace(/^\/+/, '')
        const encodedQuoraUrlPattern = /(?:^|[-_/])https?-www-quora-com-([^/?#]+)/ig
        let match = null

        while((match = encodedQuoraUrlPattern.exec(decodedPath))) {
            const encodedPath = `${match[1] || ''}`.replace(/^[-_/]+|[-_/]+$/g, '')
            if(isLowConfidenceEncodedQuestionPath(encodedPath)) continue

            return normalizeCoordinatorRequestedUrl(`https://www.quora.com/${encodedPath}`)
        }
    }
    catch {
        return ''
    }

    return ''
}

function getInvalidProfileResolutionFailure(item = {}, fallbackKey = '') {
    if(!isProfileResolutionItem(item)) return ''

    const requestedUrl = getProfileResolutionRequestedUrl(item, fallbackKey)
    if(!requestedUrl) return 'Queued profile resolution has no source page'

    try {
        const url = new URL(requestedUrl)
        const hostname = `${url.hostname || ''}`.toLowerCase()
        const isPrimaryQuoraHost = hostname === 'quora.com' || hostname === 'www.quora.com'
        const isQuoraSubdomain = hostname.endsWith('.quora.com')
        if(!isPrimaryQuoraHost && !isQuoraSubdomain) {
            return `Queued profile resolution source is not a Quora page: ${requestedUrl}`
        }

        const pathParts = url.pathname.split('/').filter(Boolean)
        const rootToken = `${pathParts[0] || ''}`.toLowerCase()
        if(isQuoraSubdomain && !isPrimaryQuoraHost) return ''
        if(!rootToken) return `Queued profile resolution source is not a question page: ${requestedUrl}`
        if(rootToken.length >= 3 && 'profile'.startsWith(rootToken)) {
            return `Queued profile resolution source looks like a truncated profile URL: ${requestedUrl}`
        }
        if(QUORA_NON_PROFILE_ROOT_PATHS.has(rootToken)) {
            return `Queued profile resolution source is not a question page: ${requestedUrl}`
        }
    }
    catch {
        return `Queued profile resolution source is invalid: ${requestedUrl}`
    }

    return ''
}

function getCoordinatorItemQueueKey(item = null, fallbackKey = '') {
    const href = getCoordinatorItemHref(item || {})
    if(href) return href

    const explicitKey = `${item?.coordinatorKey || ''}`.trim()
    if(explicitKey) return explicitKey

    if(isProfileResolutionItem(item)) {
        return makeProfileResolutionQueueKey(item?.requestedUrl || item?.dedupeKey || fallbackKey || '')
    }

    return normalizeQuoraProfileUrl(fallbackKey || '') || `${fallbackKey || ''}`.trim()
}

function getCoordinatorItemOpenUrl(item = null, fallbackKey = '') {
    const href = getCoordinatorItemHref(item || {})
    if(href) return href
    if(isProfileResolutionItem(item) || `${fallbackKey || ''}`.trim().startsWith('resolve-profile:')) {
        return getProfileResolutionRequestedUrl(item, fallbackKey)
    }

    return normalizeTabTargetUrl(item?.requestedUrl || item?.dedupeKey || fallbackKey || '')
}

function makeCoordinatorScope(runInput = {}, source = {}, runId = '') {
    return {
        type: runInput.sourceType || source.type || 'space-feed',
        runId: runId || runInput.id || '',
        sourcePageUrl: source.pageUrl || runInput.sourcePageUrl || '',
        spaceKey: source.spaceKey || '',
        spaceCategory: source.spaceCategory || ''
    }
}

function makeCoordinatorResolutionSubject(requestedUrl = '', coordinatorKey = '') {
    const normalizedUrl = normalizeCoordinatorRequestedUrl(requestedUrl || stripProfileResolutionQueueKey(coordinatorKey || ''))
    if(!normalizedUrl) return null

    return {
        kind: 'quora-source-page',
        href: normalizedUrl,
        requestedUrl: normalizedUrl,
        aliases: coordinatorKey ? [coordinatorKey] : []
    }
}

function getCoordinatorSubjectKey(subject = null) {
    if(!subject || typeof subject !== 'object') return ''
    return `${subject.kind || 'subject'}:${subject.href || subject.requestedUrl || subject.key || ''}`
}

function makeCoordinatorJobKey(scope = {}, actionKind = '', subject = null) {
    const scopeKey = scope.runId ||
        [scope.type || 'global', scope.sourcePageUrl || scope.spaceKey || ''].filter(Boolean).join(':') ||
        'global'
    const subjectKey = getCoordinatorSubjectKey(subject)
    if(!subjectKey) return ''

    return `${scopeKey}|${getCoordinatorActionKindForRequestedAction(actionKind)}|${subjectKey}`
}

function makeCoordinatorAttemptEnvelope(existing = null, attemptId = '', attemptNumber = 0, maxAttempts = 1) {
    const previous = existing?.attempt && typeof existing.attempt === 'object' ? existing.attempt : {}
    return {
        ...previous,
        id: normalizeAttemptId(attemptId || previous.id || ''),
        number: Number.parseInt(attemptNumber || previous.number, 10) || 0,
        max: Number.parseInt(maxAttempts || previous.max, 10) || 1,
        claimedTabId: previous.claimedTabId ?? existing?.tabId ?? null,
        claimedAt: Number.parseInt(previous.claimedAt, 10) || 0,
        leaseExpiresAt: Number.parseInt(previous.leaseExpiresAt, 10) || 0,
        heartbeatAt: Number.parseInt(previous.heartbeatAt, 10) || 0
    }
}

function makeCoordinatorJobEnvelope(details = {}) {
    const targetProfileHref = normalizeQuoraProfileUrl(details.targetProfileHref || '')
    const coordinatorKey = `${details.coordinatorKey || targetProfileHref || ''}`.trim()
    const requestedUrl = isProfileResolutionItem({
            requestedUrl: details.requestedUrl || '',
            coordinatorKey
        })
        ? getProfileResolutionRequestedUrl({
            requestedUrl: details.requestedUrl || '',
            coordinatorKey
        }, coordinatorKey)
        : normalizeCoordinatorRequestedUrl(details.requestedUrl || targetProfileHref || coordinatorKey)
    const actionKind = getCoordinatorActionKindForRequestedAction(details.actionKind || '')
    const scope = makeCoordinatorScope(details.runInput || {}, details.source || {}, details.runId || '')
    const canonicalSubject = targetProfileHref
        ? makeCanonicalSubject(targetProfileHref)
        : makeCoordinatorResolutionSubject(requestedUrl, coordinatorKey)
    const jobKey = makeCoordinatorJobKey(scope, actionKind, canonicalSubject)

    return {
        jobKey,
        scope,
        canonicalSubject
    }
}

function applyCoordinatorJobEnvelope(item = {}, details = {}) {
    const envelope = makeCoordinatorJobEnvelope({
        targetProfileHref: item.targetProfileHref || details.targetProfileHref || '',
        requestedUrl: item.requestedUrl || details.requestedUrl || '',
        coordinatorKey: item.coordinatorKey || details.coordinatorKey || '',
        actionKind: item.actionKind || details.actionKind || '',
        runInput: details.runInput || {},
        source: item.source || details.source || {},
        runId: item.runId || details.runId || ''
    })

    return {
        ...item,
        jobKey: envelope.jobKey || item.jobKey || '',
        scope: envelope.scope || item.scope,
        canonicalSubject: envelope.canonicalSubject || item.canonicalSubject,
        attempt: makeCoordinatorAttemptEnvelope(
            item,
            getAttemptIdFromValue(item),
            getAttemptNumberFromValue(item),
            item.maxAttempts || item.attempt?.max || 1
        )
    }
}

function getFailedItemQuestionResolutionUrl(item = {}) {
    const errorText = `${item?.error || ''}`
    const questionPathMatch = errorText.match(/\bquestion:\s*(\/[^)\s]+)/i)
    if(questionPathMatch?.[1]) {
        return normalizeCoordinatorRequestedUrl(`https://www.quora.com${questionPathMatch[1]}`)
    }

    const evidence = Array.isArray(item?.evidence) ? item.evidence : []
    for(const entry of evidence) {
        try {
            const requestedUrl = getQuestionResolutionUrlFromEvidencePostUrl(entry?.postUrl || '')
            if(requestedUrl) return requestedUrl
        }
        catch {}
    }

    if(/\bdid not land on a profile page\b/i.test(errorText)) {
        for(const entry of evidence) {
            const postUrl = normalizeCoordinatorRequestedUrl(entry?.postUrl || '')
            if(postUrl) return postUrl
        }
    }

    return ''
}

function getFailedItemProfileResolutionRetryUrl(item = {}, fallbackKey = '') {
    const fallbackResolutionUrl = getFailedItemQuestionResolutionUrl(item)
    if(fallbackResolutionUrl) return fallbackResolutionUrl

    if(!isProfileResolutionItem(item)) return ''
    if(getCoordinatorItemHref(item)) return ''

    return getProfileResolutionRequestedUrl(item, fallbackKey)
}

function buildQueuedCoordinatorProgressResetPatch(item = {}, options = {}) {
    const actionKind = getCoordinatorActionKindForRequestedAction(item?.actionKind || options.actionKind || '')
    const now = Number.parseInt(options.now, 10) || Date.now()

    return {
        replaceProgressRecord: true,
        actionKind,
        runId: item?.runId || options.runId || '',
        attemptId: getAttemptIdFromValue(item),
        attemptNumber: getAttemptNumberFromValue(item),
        status: 'queued',
        queuedAt: now,
        queueIndex: 0,
        retryAttempt: 0,
        maxRetries: Number.parseInt(item?.maxRetries, 10) || STALE_QUEUED_TAB_MAX_RETRIES,
        tabId: null,
        tabCreatedAt: 0,
        tabOpenedAt: 0,
        contentOpenedAt: 0,
        actionReadyAt: 0,
        openedViablePage: false,
        terminalAt: 0,
        slotReleasedAt: 0,
        closeRequestedAt: 0,
        tabClosedAt: 0,
        closedByExtension: false,
        closeReason: '',
        ownerTabId: null,
        ownerWindowId: null,
        waitingForForegroundAt: 0,
        foregroundWaitReason: '',
        foregroundWaitLastEventAt: 0,
        foregroundLeaseAcquiredAt: 0,
        foregroundPromotedAt: 0,
        foregroundPromotionReason: '',
        muteAttempted: false,
        muteSucceeded: false,
        muteAttemptedAt: 0,
        mutedAt: 0,
        muteError: '',
        blockAttempted: false,
        blockSucceeded: false,
        blockAttemptedAt: 0,
        blockedAt: 0,
        blockError: '',
        directBlockFailureDetail: null,
        unblockOk: false,
        unblockSucceeded: false,
        unblockReason: '',
        unmuteOk: false,
        unmuteReason: '',
        foundBlockedBeforeQueue: false,
        profileBlocked: false,
        profileMenuOpen: false,
        selectedActionLabel: '',
        selectedActionRect: null,
        menuActionLabels: [],
        visibleProfileMenuLabels: [],
        finalError: '',
        errorPageUrl: '',
        lastUrl: '',
        unavailableReason: '',
        resolvedProfileHref: '',
        remappedFromRequested: false,
        securityVerification: false,
        event: actionKind === UNBLOCK_UNMUTE_ACTION_KIND
            ? 'Added Unblock Unmute to Current Work'
            : 'Added Mute Block to Current Work'
    }
}

function getStoredSpaceFeedRecordUrls(record, key = 'remainingUrls') {
    if(!record || typeof record !== 'object') return []

    const urls = key && Array.isArray(record[key])
        ? record[key]
        : key === 'remainingUrls'
            ? Array.isArray(record.remainingUrls)
                ? record.remainingUrls
                : Array.isArray(record.allUrls)
                    ? record.allUrls
                    : Array.isArray(record.urls)
                        ? record.urls
                        : []
            : []

    return getNormalizedProfileHrefList(urls)
}

function getPendingSpaceFeedJobKeyPatch(record = {}, remainingUrls = []) {
    const remaining = getNormalizedProfileHrefList(remainingUrls)
    const existingByHref = record?.jobKeysByProfileHref && typeof record.jobKeysByProfileHref === 'object'
        ? record.jobKeysByProfileHref
        : {}
    const jobKeysByProfileHref = {}

    for(const href of remaining) {
        jobKeysByProfileHref[href] = normalizeQuoraProfileUrl(existingByHref[href] || href) || href
    }

    return {
        jobKeys: getNormalizedProfileHrefList(Object.values(jobKeysByProfileHref)),
        jobKeysByProfileHref
    }
}

function makeId(prefix) {
    return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`
}

function makeAttemptId() {
    return makeId('attempt')
}

function normalizeAttemptId(value = '') {
    return `${value || ''}`.trim()
}

function getAttemptIdFromValue(value = null) {
    if(!value || typeof value !== 'object') return ''
    return normalizeAttemptId(value.attemptId || value.attempt?.id || '')
}

function getAttemptNumberFromValue(value = null) {
    if(!value || typeof value !== 'object') return 0
    return Number.parseInt(value.attemptNumber ?? value.attempt?.number, 10) || 0
}

function makeCoordinatorInFlightMutationKey(prefix = '', itemKey = '', item = null, extra = '') {
    return [
        `${prefix || 'coordinator-mutation'}`.trim(),
        normalizeQuoraProfileUrl(itemKey) || `${itemKey || ''}`.trim(),
        getAttemptIdFromValue(item),
        getAttemptNumberFromValue(item),
        `${extra || ''}`.trim()
    ].join('|')
}

function getNextAttemptNumberFromValue(value = null) {
    return Math.max(1, getAttemptNumberFromValue(value) + 1)
}

function isAttemptTrackedCoordinatorItem(item = null) {
    return !!item &&
        isCoordinatorQueueAuthoritativeItem(item) &&
        (getAttemptIdFromValue(item) || getAttemptNumberFromValue(item))
}

function isNewerTerminalProgressForCoordinatorItem(item = null, record = null) {
    if(!item || !record) return false
    if(isTerminalCoordinatorStatus(item?.status)) return false
    if(!isTerminalProfileNukeRecord(record)) return false

    const expectedAttemptNumber = getAttemptNumberFromValue(item)
    const incomingAttemptNumber = getAttemptNumberFromValue(record)
    if(!expectedAttemptNumber || !incomingAttemptNumber) return false
    if(incomingAttemptNumber <= expectedAttemptNumber) return false

    const itemRunId = `${item?.runId || ''}`.trim()
    const recordRunId = `${record?.runId || ''}`.trim()
    if(itemRunId && recordRunId && itemRunId !== recordRunId) return false

    const itemQueuedAt = Number.parseInt(item?.queuedAt || item?.createdAt || 0, 10) || 0
    const recordTerminalAt = Number.parseInt(record?.terminalAt || record?.tabClosedAt || record?.updatedAt || 0, 10) || 0
    if(itemQueuedAt && recordTerminalAt && recordTerminalAt < itemQueuedAt) return false

    return true
}

function normalizeCoordinatorMap(value) {
    return value && typeof value === 'object' && !Array.isArray(value) ? value : {}
}

function normalizeCoordinatorEvents(value) {
    if(Array.isArray(value)) return value.filter(event => event && typeof event === 'object')
    return Object.values(normalizeCoordinatorMap(value)).filter(event => event && typeof event === 'object')
}

function hasMismatchedCoordinatorAttempt(item = null, record = null) {
    if(!isTerminalCoordinatorStatus(item?.status) && isTerminalProfileNukeRecord(record)) {
        const itemQueuedAt = Number.parseInt(item?.queuedAt || item?.createdAt || 0, 10) || 0
        const recordTerminalAt = Number.parseInt(record?.terminalAt || record?.tabClosedAt || record?.updatedAt || 0, 10) || 0
        if(itemQueuedAt && recordTerminalAt && recordTerminalAt < itemQueuedAt) return true
    }

    if(isNewerTerminalProgressForCoordinatorItem(item, record)) return false

    const expectedAttemptId = getAttemptIdFromValue(item)
    const incomingAttemptId = getAttemptIdFromValue(record)
    if(expectedAttemptId && incomingAttemptId && expectedAttemptId !== incomingAttemptId) return true

    const expectedAttemptNumber = getAttemptNumberFromValue(item)
    const incomingAttemptNumber = getAttemptNumberFromValue(record)
    if(expectedAttemptNumber && incomingAttemptNumber && expectedAttemptNumber !== incomingAttemptNumber) return true

    if(!isTerminalCoordinatorStatus(item?.status) && isAttemptTrackedCoordinatorItem(item)) {
        if(expectedAttemptId && !incomingAttemptId) return true
        if(expectedAttemptNumber && !incomingAttemptNumber) return true
    }

    return !isTerminalCoordinatorStatus(item?.status) &&
        !!expectedAttemptId &&
        !incomingAttemptId &&
        isTerminalProfileNukeRecord(record)
}

function getResolvedDestinationConflict(existingResolvedItem = null, sourceItem = null) {
    if(!existingResolvedItem) return ''
    if(existingResolvedItem.status === 'succeeded') return ''
    if(isTerminalCoordinatorStatus(existingResolvedItem.status)) return 'terminal-resolved-coordinator-item'
    if(hasMismatchedCoordinatorAttempt(existingResolvedItem, sourceItem)) return 'resolved-coordinator-conflict'
    return ''
}

function makeStaleAttemptDiagnosticEvent(details = {}) {
    return {
        id: makeId('event'),
        runId: details.runId || '',
        itemId: details.itemId || '',
        type: 'stale-attempt',
        message: details.message || 'Ignored stale worker attempt',
        at: Date.now(),
        details: {
            profileHref: details.profileHref || '',
            incomingAttemptId: details.incomingAttemptId || '',
            expectedAttemptId: details.expectedAttemptId || '',
            senderTabId: details.senderTabId || null
        }
    }
}

function recordCoordinatorDiagnosticEvent(type = 'coordinator-diagnostic', message = '', details = {}) {
    const event = {
        id: makeId('event'),
        runId: details?.runId || '',
        itemId: details?.itemId || '',
        type: `${type || 'coordinator-diagnostic'}`.trim() || 'coordinator-diagnostic',
        message: `${message || 'Coordinator diagnostic event'}`.slice(0, 500),
        at: Date.now(),
        details: details && typeof details === 'object'
            ? cloneCoordinatorAuthorityValue(details)
            : {}
    }
    incrementQueueWakeupMetric('diagnosticEvent.received')
    pendingCoordinatorDiagnosticEvents.push(event)
    if(pendingCoordinatorDiagnosticEvents.length > MAX_COORDINATOR_EVENTS) {
        pendingCoordinatorDiagnosticEvents = pendingCoordinatorDiagnosticEvents.slice(-MAX_COORDINATOR_EVENTS)
        incrementQueueWakeupMetric('diagnosticEvent.pendingPruned')
    }
    recordQueueWakeupMetricMax('diagnosticEvent.pendingMax', pendingCoordinatorDiagnosticEvents.length)
    if(storageUpdateState.getDepth() <= 0 && coordinatorDiagnosticBatchDepth <= 0) {
        incrementQueueWakeupMetric('diagnosticEvent.persistDeferred')
    }
    return true
}

function drainPendingCoordinatorDiagnosticEvents() {
    const events = pendingCoordinatorDiagnosticEvents
    pendingCoordinatorDiagnosticEvents = []
    return events
}

async function flushPendingCoordinatorDiagnosticEvents() {
    return runQueueWakeupMetricPhase('flushDiagnosticEvents', async () => {
        const pending = drainPendingCoordinatorDiagnosticEvents()
        if(!pending.length) return false

        incrementQueueWakeupMetric('diagnosticEvent.flushPerformed')
        incrementQueueWakeupMetric('diagnosticEvent.eventsPerFlush', pending.length)
        const stored = await metricStorageGet({[COORDINATOR_EVENTS_KEY]: []})
        const events = normalizeCoordinatorEvents(stored[COORDINATOR_EVENTS_KEY])
        await metricStorageSet({
            [COORDINATOR_EVENTS_KEY]: events.concat(pending).slice(-MAX_COORDINATOR_EVENTS)
        }, {
            snapshotWriteReason: 'reconcile'
        })
        incrementQueueWakeupMetric('diagnosticEvent.storageWrites')
        return true
    })
}

function shouldFlushPendingCoordinatorDiagnosticEventsNow(context = {}) {
    const durableActiveRows = Number.parseInt(context?.durableActiveRows, 10) || 0
    const durableQueuedRows = Number.parseInt(context?.durableQueuedRows, 10) || 0
    const runtimeCounts = queueRuntime.getRuntimeCounts()
    return runtimeCounts.activeQueuedTabs <= 0 &&
        runtimeCounts.queuedTabActions <= 0 &&
        runtimeCounts.pendingTabActions <= 0 &&
        durableActiveRows <= 0 &&
        durableQueuedRows <= 0
}

async function flushPendingCoordinatorDiagnosticEventsIfIdle(context = {}) {
    if(!shouldFlushPendingCoordinatorDiagnosticEventsNow(context)) {
        incrementQueueWakeupMetric('diagnosticEvent.flushDeferredForQueueWork')
        return false
    }
    return flushPendingCoordinatorDiagnosticEvents()
}

async function recordStaleAttemptDiagnostic(details = {}) {
    const event = makeStaleAttemptDiagnosticEvent(details)
    incrementQueueWakeupMetric('diagnosticEvent.received')
    pendingCoordinatorDiagnosticEvents.push(event)
    if(pendingCoordinatorDiagnosticEvents.length > MAX_COORDINATOR_EVENTS) {
        pendingCoordinatorDiagnosticEvents = pendingCoordinatorDiagnosticEvents.slice(-MAX_COORDINATOR_EVENTS)
        incrementQueueWakeupMetric('diagnosticEvent.pendingPruned')
    }
    recordQueueWakeupMetricMax('diagnosticEvent.pendingMax', pendingCoordinatorDiagnosticEvents.length)
    if(storageUpdateState.getDepth() <= 0 && coordinatorDiagnosticBatchDepth <= 0) {
        incrementQueueWakeupMetric('diagnosticEvent.persistDeferred')
    }
    return true
}

function mergeCoordinatorSources(existingSources = [], incomingSources = []) {
    const seen = new Set()
    const merged = []

    for(const source of [...existingSources, ...incomingSources]) {
        if(!source || typeof source !== 'object') continue
        const key = [
            source.type || '',
            source.pageUrl || '',
            source.spaceKey || '',
            source.spaceCategory || ''
        ].join('|')
        if(seen.has(key)) continue
        seen.add(key)
        merged.push({
            type: source.type || '',
            pageUrl: source.pageUrl || '',
            spaceKey: source.spaceKey || '',
            spaceCategory: source.spaceCategory || ''
        })
    }

    return merged
}

function mergeCoordinatorEvidence(existingEvidence = [], incomingEvidence = []) {
    const seen = new Set()
    const merged = []

    for(const evidence of [...existingEvidence, ...incomingEvidence]) {
        if(!evidence || typeof evidence !== 'object') continue
        const key = [
            evidence.postKey || '',
            evidence.postUrl || '',
            evidence.collector || '',
            evidence.sourcePageUrl || ''
        ].join('|')
        if(seen.has(key)) continue
        seen.add(key)
        merged.push({
            postKey: evidence.postKey || '',
            postUrl: evidence.postUrl || '',
            collector: evidence.collector || '',
            confidence: evidence.confidence || '',
            source: evidence.source || '',
            rawSlug: evidence.rawSlug || '',
            resolutionReason: evidence.resolutionReason || '',
            sourcePageUrl: evidence.sourcePageUrl || ''
        })
    }

    return merged
}

function getCoordinatorStatusFromProgress(record = null) {
    const mapped = mapProgressToCoordinatorState(record)
    return {
        status: mapped.status || '',
        outcome: mapped.outcome || '',
        error: mapped.error || ''
    }
}

function progressPatchHasExplicitStatus(patch = {}) {
    return Object.prototype.hasOwnProperty.call(patch || {}, 'status') &&
        `${patch?.status || ''}`.trim() !== ''
}

function shouldApplyExplicitProgressStatusToCoordinatorItem(item = {}, patch = {}, options = {}) {
    if(!progressPatchHasExplicitStatus(patch)) return false

    const status = `${patch?.status || ''}`.trim()
    const senderTabId = normalizeTabId(options.senderTabId)
    if(options.requireActiveSenderTab === true) {
        const itemTabId = normalizeTabId(item?.tabId || item?.activeTabId || null)
        return !!senderTabId && isActiveCoordinatorStatus(item?.status || '') && itemTabId === senderTabId
    }

    if(status === 'interrupted' && senderTabId) {
        const itemTabId = normalizeTabId(item?.tabId || item?.activeTabId || null)
        return isActiveCoordinatorStatus(item?.status || '') && itemTabId === senderTabId
    }

    return true
}

function getActiveCoordinatorProgressSenderTabMismatchReason(item = {}, patch = {}, options = {}) {
    if(!item || !isActiveCoordinatorStatus(item?.status || '')) return ''

    const senderTabId = normalizeTabId(options.senderTabId || patch?.tabId || null)
    if(!senderTabId) return ''

    if(options.allowBlockedLiveTabSender === true &&
        patch?.blockSucceeded === true &&
        `${patch?.status || ''}`.trim() === 'already-blocked') {
        const itemHref = getCoordinatorItemHref(item)
        const patchHref = normalizeQuoraProfileUrl(patch?.resolvedProfileHref || patch?.profileHref || '')
        if(itemHref && patchHref === itemHref) return ''
    }

    const lease = normalizeCoordinatorActionLease(item?.actionLease)
    const leaseTabId = normalizeTabId(lease?.tabId || null)
    if(leaseTabId && senderTabId !== leaseTabId) {
        return 'active-action-lease-sender-tab-mismatch'
    }

    const itemTabId = normalizeTabId(item?.tabId || item?.activeTabId || null)
    if(itemTabId && senderTabId !== itemTabId) {
        return 'active-sender-tab-mismatch'
    }

    return ''
}

function getActiveCoordinatorDirectProgressRuntimeRejectionReason(item = {}, patch = {}, mapped = {}, options = {}) {
    if(isTerminalCoordinatorStatus(mapped?.status)) return ''
    if(!item) return ''
    if(!isCoordinatorQueueAuthoritativeItem(item)) return ''

    const itemStatus = `${item?.status || ''}`.trim()
    if(itemStatus === 'queued' && isActiveCoordinatorStatus(mapped?.status || '')) {
        const releaseReason = `${item?.actionLeaseReleaseReason || ''}`.trim()
        const releaseAt = Number.parseInt(item?.actionLeaseReleasedAt, 10) || 0
        const milestones = item?.milestones || {}
        const closeAt = Math.max(
            Number.parseInt(milestones.closeRequestedAt, 10) || 0,
            Number.parseInt(milestones.tabClosedAt, 10) || 0
        )
        if(releaseReason || releaseAt || closeAt) {
            return 'queued-direct-progress-after-runtime-release'
        }
        return ''
    }
    if(!isActiveCoordinatorStatus(itemStatus)) return ''

    const senderTabId = normalizeTabId(options.senderTabId || patch?.tabId || null)
    const itemTabId = normalizeTabId(item?.tabId || item?.activeTabId || null)
    const tabId = senderTabId || itemTabId
    if(!tabId) return 'active-direct-progress-missing-runtime-tab'
    if(!queueRuntime.hasActiveQueuedTab(tabId)) {
        if(senderTabId && itemTabId && senderTabId === itemTabId &&
            !queueRuntime.hasPendingTabAction(tabId) &&
            !queueRuntime.hasQueuedTabMetadata(tabId)) {
            if(wasQueuedRuntimeTabRemoved(tabId)) return 'queued-tab-runtime-detached'
            queueRuntime.addActiveQueuedTab(tabId)
            setQueuedTabMetadata(tabId, {
                profileHref: getCoordinatorItemHref(item) || item.profileHref || item.targetProfileHref || '',
                coordinatorKey: getCoordinatorItemQueueKey(item),
                requestedUrl: item.requestedUrl || item.targetProfileHref || '',
                tabAction: item.executorTabAction || item.tabAction || 'nuke',
                actionKind: item.actionKind || 'mute-block',
                runId: item.runId || '',
                attemptId: getAttemptIdFromValue(item),
                attemptNumber: getAttemptNumberFromValue(item),
                durableActiveAt: item.activeAt || Date.now(),
                durableActiveReason: 'direct-progress-runtime-restored'
            })
            incrementQueueWakeupMetric('directProgress.runtimeRestoredFromAuthority')
        }
        else {
            return 'queued-tab-runtime-detached'
        }
    }

    const metadata = getQueuedTabMetadata(tabId)
    if(!metadata) return 'queued-tab-metadata-missing'
    if(metadata?.closeRequestedAt || metadata?.closeReason) return 'queued-tab-closing'

    const metadataHref = normalizeQuoraProfileUrl(metadata.profileHref || metadata.targetProfileHref || '')
    const itemHref = normalizeQuoraProfileUrl(getCoordinatorItemHref(item) || item.profileHref || item.targetProfileHref || '')
    if(metadataHref && itemHref && metadataHref !== itemHref) {
        return 'queued-tab-metadata-profile-mismatch'
    }

    return ''
}

function getCoordinatorActionKindForProgress(record = null) {
    return record?.actionKind || 'mute-block'
}

function getCoordinatorActionKindForItem(item = null) {
    return item?.actionKind || 'mute-block'
}

function shouldApplyProgressToCoordinatorItem(item = null, record = null) {
    if(!item || !record) return false
    return getCoordinatorActionKindForItem(item) === getCoordinatorActionKindForProgress(record)
}

function isCoordinatorQueueAuthoritativeItem(item = null) {
    return item?.serviceWorkerOwned === true ||
        `${item?.executorOwner || ''}` === 'service-worker'
}

function getCoordinatorMilestonesFromProgress(record = {}) {
    return getJobMilestonesFromProgress(record)
}

function isTerminalCoordinatorStatus(status) {
    return isTerminalJobStatus(status)
}

function isActiveCoordinatorStatus(status = '') {
    return ['opening', 'active', 'acting', 'settling'].includes(`${status || ''}`.trim())
}

function isPendingCoordinatorStatus(status = '') {
    return status === 'queued' || isActiveCoordinatorStatus(status)
}

function isRetryableCoordinatorFailure(item = null) {
    return isRetryableJobFailure(item)
}

function isRetryableCoordinatorFailureFromProgress(item = null, record = null) {
    return isRetryableJobFailureFromProgress(item, record)
}

function getCoordinatorCurrentWorkAnchor(item = {}) {
    return Number.parseInt(item?.terminalAt || item?.updatedAt || item?.createdAt, 10) || 0
}

function hasUnsettledCoordinatorSource(item = null) {
    const settlementKey = getCoordinatorItemSettlementKey(item)
    return !!settlementKey && item?.sourceSettlementKey !== settlementKey
}

function shouldKeepCoordinatorCurrentWorkItem(item = null, now = Date.now()) {
    if(!item || typeof item !== 'object') return false
    if(isPendingCoordinatorStatus(item.status)) return true
    if(isRetryableCoordinatorFailure(item)) return true
    if(!isTerminalCoordinatorStatus(item.status)) return true
    if(hasUnsettledCoordinatorSource(item)) return true

    const anchor = getCoordinatorCurrentWorkAnchor(item)
    return !anchor || now - anchor <= CURRENT_WORK_RETENTION_MS
}

function pruneCoordinatorCurrentWork(queue = {}, now = Date.now()) {
    let changed = false

    for(const [key, item] of Object.entries(queue || {})) {
        if(shouldKeepCoordinatorCurrentWorkItem(item, now)) continue
        delete queue[key]
        changed = true
    }

    return changed
}

function getCoordinatorQueueViewSortRank(item = {}) {
    const status = `${item?.status || ''}`.trim()
    if(isActiveCoordinatorStatus(status)) return 0
    if(status === 'queued') return 1
    if(isRetryableCoordinatorFailure(item)) return 2
    if(status === 'failed') return 3
    if(!isTerminalCoordinatorStatus(status)) return 4
    return 5
}

function getCoordinatorQueueViewTime(item = {}) {
    return Number.parseInt(
        item?.terminalAt ||
        item?.updatedAt ||
        item?.activeAt ||
        item?.queuedAt ||
        item?.createdAt,
        10
    ) || 0
}

function getCoordinatorQueueViewEpochStartedAt() {
    return Number.parseInt(queueWakeupMetrics?.currentEpoch?.startedAt, 10) || 0
}

function isCoordinatorActualBlockSuccess(item = {}) {
    if(`${item?.status || ''}` !== 'succeeded') return false
    if(`${item?.actionKind || ''}` === UNBLOCK_UNMUTE_ACTION_KIND) return false
    if(`${item?.outcome || ''}` === 'already-blocked') return false
    if(`${item?.outcome || ''}` === 'blocked') return true

    const milestones = item?.milestones || {}
    return getFirstPositiveNumber(
        item?.blockAttemptedAt,
        milestones.blockAttemptedAt
    ) > 0
}

function getCoordinatorActualBlockTerminalTime(item = {}) {
    return getFirstPositiveNumber(item?.terminalAt, item?.blockedAt, item?.updatedAt, item?.createdAt)
}

function getCoordinatorActualBlockActiveStartTime(item = {}) {
    const milestones = item?.milestones || {}
    return getFirstPositiveNumber(
        item?.activeAt,
        item?.actionReadyAt,
        milestones.actionReadyAt,
        item?.blockAttemptedAt,
        milestones.blockAttemptedAt,
        item?.tabOpenedAt,
        milestones.tabOpenedAt,
        item?.contentOpenedAt,
        milestones.contentOpenedAt
    )
}

function summarizeCoordinatorActualBlockTiming(queue = {}, epochStartedAt = 0) {
    const minimumTerminalAt = Number.parseInt(epochStartedAt, 10) || 0
    const samples = Object.values(queue || {})
        .filter(item => {
            if(!isCoordinatorActualBlockSuccess(item)) return false
            const terminalAt = getCoordinatorActualBlockTerminalTime(item)
            return terminalAt > 0 && (!minimumTerminalAt || terminalAt >= minimumTerminalAt)
        })
        .sort((left, right) => getCoordinatorActualBlockTerminalTime(right) - getCoordinatorActualBlockTerminalTime(left))
        .slice(0, 100)

    const durations = samples
        .map(item => {
            const startedAt = getCoordinatorActualBlockActiveStartTime(item)
            const terminalAt = getCoordinatorActualBlockTerminalTime(item)
            return startedAt > 0 && terminalAt > startedAt ? terminalAt - startedAt : 0
        })
        .filter(duration => duration > 0)
    const elapsedMs = durations.reduce((total, duration) => total + duration, 0)
    const blocks = durations.length

    return {
        epochStartedAt: minimumTerminalAt,
        sampleLimit: 100,
        blocks,
        elapsedMs,
        seconds: blocks ? (elapsedMs / 1000) / blocks : 0
    }
}

function getCoordinatorActivationHandoffTerminalTime(item = {}) {
    return getFirstPositiveNumber(item?.terminalAt, item?.updatedAt, item?.createdAt)
}

function getCoordinatorActivationHandoffActiveTime(item = {}) {
    return getFirstPositiveNumber(item?.activeAt)
}

function summarizeCoordinatorActivationHandoffTiming(queue = {}, epochStartedAt = 0) {
    const minimumTerminalAt = Number.parseInt(epochStartedAt, 10) || 0
    const entries = Object.entries(queue || {})
    const activations = entries
        .map(([key, item]) => ({
            key,
            item,
            runId: `${item?.runId || ''}`.trim(),
            activeAt: getCoordinatorActivationHandoffActiveTime(item)
        }))
        .filter(sample => sample.activeAt > 0 && sample.runId)
        .sort((left, right) => left.activeAt - right.activeAt)
    const terminals = entries
        .map(([key, item]) => ({
            key,
            item,
            runId: `${item?.runId || ''}`.trim(),
            terminalAt: getCoordinatorActivationHandoffTerminalTime(item)
        }))
        .filter(sample => {
            if(!isTerminalCoordinatorStatus(sample.item?.status)) return false
            return sample.runId && sample.terminalAt > 0 && (!minimumTerminalAt || sample.terminalAt >= minimumTerminalAt)
        })
        .sort((left, right) => left.terminalAt - right.terminalAt)

    const samples = []
    for(const terminal of terminals) {
        const nextActivation = activations.find(candidate =>
            candidate.key !== terminal.key &&
            candidate.runId === terminal.runId &&
            candidate.activeAt > terminal.terminalAt
        )
        if(!nextActivation) continue
        samples.push({
            terminalKey: terminal.key,
            runId: terminal.runId,
            terminalStatus: terminal.item?.status || '',
            terminalOutcome: terminal.item?.outcome || '',
            terminalAt: terminal.terminalAt,
            nextActiveKey: nextActivation.key,
            nextActiveStatus: nextActivation.item?.status || '',
            nextActiveAt: nextActivation.activeAt,
            gapMs: nextActivation.activeAt - terminal.terminalAt
        })
        if(samples.length >= 100) break
    }

    const gaps = samples
        .map(sample => Number.parseInt(sample.gapMs, 10) || 0)
        .filter(gap => gap > 0)
        .sort((left, right) => left - right)
    const elapsedMs = gaps.reduce((total, gap) => total + gap, 0)
    const handoffs = gaps.length
    const p95Index = handoffs ? Math.min(handoffs - 1, Math.ceil(handoffs * 0.95) - 1) : 0

    return {
        epochStartedAt: minimumTerminalAt,
        sampleLimit: 100,
        handoffs,
        elapsedMs,
        seconds: handoffs ? (elapsedMs / 1000) / handoffs : 0,
        maxMs: handoffs ? gaps[handoffs - 1] : 0,
        p95Ms: handoffs ? gaps[p95Index] : 0,
        samples
    }
}

function summarizeCoordinatorQueueViewItem(key = '', item = {}) {
    const source = item && typeof item === 'object' ? item : {}
    return {
        storageKey: key,
        id: source.id || '',
        runId: source.runId || '',
        status: source.status || '',
        outcome: source.outcome || '',
        error: source.error || source.finalError || '',
        actionKind: source.actionKind || '',
        executorTabAction: source.executorTabAction || '',
        executorOwner: source.executorOwner || '',
        serviceWorkerOwned: source.serviceWorkerOwned === true,
        targetProfileHref: source.targetProfileHref || '',
        requestedUrl: source.requestedUrl || '',
        dedupeKey: source.dedupeKey || '',
        tabId: Number.parseInt(source.tabId || source.activeTabId, 10) || 0,
        activeTabId: Number.parseInt(source.activeTabId || source.tabId, 10) || 0,
        attemptId: source.attemptId || source.attempt?.id || '',
        attemptNumber: Number.parseInt(source.attemptNumber || source.attempt?.number, 10) || 0,
        maxAttempts: Number.parseInt(source.maxAttempts || source.attempt?.max, 10) || 0,
        resolveProfileFromPage: source.resolveProfileFromPage === true,
        resolutionMode: source.resolutionMode || '',
        queuedAt: Number.parseInt(source.queuedAt || source.createdAt, 10) || 0,
        createdAt: Number.parseInt(source.createdAt || source.queuedAt, 10) || 0,
        activeAt: Number.parseInt(source.activeAt, 10) || 0,
        terminalAt: Number.parseInt(source.terminalAt, 10) || 0,
        updatedAt: Number.parseInt(source.updatedAt || source.createdAt || source.queuedAt, 10) || 0,
        retryCount: Number.parseInt(source.retryCount, 10) || 0,
        provenance: normalizeCoordinatorItemProvenance(source.provenance) || null,
        source: {
            type: source.source?.type || source.sourceType || '',
            pageUrl: source.source?.pageUrl || source.sourcePage || '',
            searchQuery: source.source?.searchQuery || '',
            sourceLabel: source.source?.sourceLabel || source.sourceLabel || ''
        }
    }
}

function filterCoordinatorQueueForCompactView(queue = {}, runs = {}) {
    const knownRunIds = new Set(
        Object.keys(runs && typeof runs === 'object' ? runs : {})
            .map(runId => `${runId || ''}`.trim())
            .filter(Boolean)
    )
    if(!knownRunIds.size) return queue

    const filteredQueue = {}
    for(const [key, item] of Object.entries(queue || {})) {
        const runId = `${item?.runId || ''}`.trim()
        if(runId && !knownRunIds.has(runId) && isTerminalCoordinatorStatus(item?.status)) continue
        filteredQueue[key] = item
    }
    return filteredQueue
}

function buildCoordinatorQueueView(queue = {}, now = Date.now(), options = {}) {
    const compactQueue = filterCoordinatorQueueForCompactView(queue, options.runs || {})
    const entries = Object.entries(compactQueue || {})
    const epochStartedAt = getCoordinatorQueueViewEpochStartedAt()
    const counts = {}
    const authoritativeCounts = {}
    for(const [, item] of entries) {
        const status = `${item?.status || ''}`.trim() || 'unknown'
        counts[status] = (counts[status] || 0) + 1
        if(isCoordinatorQueueAuthoritativeItem(item)) {
            authoritativeCounts[status] = (authoritativeCounts[status] || 0) + 1
        }
    }
    const hasAuthoritativeStoredWork = ['queued', 'opening', 'active', 'acting', 'settling']
        .some(status => (Number.parseInt(authoritativeCounts[status], 10) || 0) > 0)

    const items = entries
        .sort((left, right) => {
            const leftItem = left[1] || {}
            const rightItem = right[1] || {}
            return getCoordinatorQueueViewSortRank(leftItem) - getCoordinatorQueueViewSortRank(rightItem) ||
                getCoordinatorQueueViewTime(rightItem) - getCoordinatorQueueViewTime(leftItem) ||
                `${left[0]}`.localeCompare(`${right[0]}`)
        })
        .map(([key, item]) => summarizeCoordinatorQueueViewItem(key, item))

    return {
        version: 1,
        updatedAt: now,
        total: entries.length,
        counts,
        authoritativeCounts,
        hasAuthoritativeStoredWork,
        actualBlockTiming: summarizeCoordinatorActualBlockTiming(compactQueue, epochStartedAt),
        activationHandoffTiming: summarizeCoordinatorActivationHandoffTiming(compactQueue, epochStartedAt),
        itemLimit: items.length,
        truncated: false,
        items
    }
}

function makeCoordinatorQueueAccountingCounts(queue = {}) {
    const counts = {}
    const authoritativeCounts = {}
    for(const item of Object.values(queue || {})) {
        const status = `${item?.status || ''}`.trim() || 'unknown'
        counts[status] = (counts[status] || 0) + 1
        if(isCoordinatorQueueAuthoritativeItem(item)) {
            authoritativeCounts[status] = (authoritativeCounts[status] || 0) + 1
        }
    }

    return {
        total: Object.keys(queue || {}).length,
        counts,
        authoritativeCounts
    }
}

function normalizeCoordinatorQueueViewAccounting(view = null) {
    if(!view || typeof view !== 'object') {
        return {
            present: false,
            total: 0,
            counts: {},
            authoritativeCounts: {},
            itemCount: 0,
            itemLimit: 0,
            truncated: false,
            updatedAt: 0
        }
    }

    const items = Array.isArray(view.items) ? view.items : []
    return {
        present: true,
        total: Number.parseInt(view.total, 10) || items.length,
        counts: normalizeObjectNumberMap(view.counts || {}),
        authoritativeCounts: normalizeObjectNumberMap(view.authoritativeCounts || {}),
        itemCount: items.length,
        itemLimit: Number.parseInt(view.itemLimit, 10) || 0,
        truncated: view.truncated === true,
        updatedAt: Number.parseInt(view.updatedAt, 10) || 0
    }
}

function areCoordinatorAccountingCountsEqual(left = {}, right = {}) {
    const keys = new Set([
        ...Object.keys(left || {}),
        ...Object.keys(right || {})
    ])
    for(const key of keys) {
        if((Number(left?.[key]) || 0) !== (Number(right?.[key]) || 0)) return false
    }
    return true
}

function makeCoordinatorQueueAccountingComparison(source = {}, target = {}, prefix = '') {
    const mismatches = []
    if((Number(source.total) || 0) !== (Number(target.total) || 0)) {
        mismatches.push(`${prefix}total`)
    }
    if(!areCoordinatorAccountingCountsEqual(source.counts, target.counts)) {
        mismatches.push(`${prefix}counts`)
    }
    if(!areCoordinatorAccountingCountsEqual(source.authoritativeCounts, target.authoritativeCounts)) {
        mismatches.push(`${prefix}authoritative-counts`)
    }
    return mismatches
}

function summarizeCoordinatorQueueWalAccounting(walStore = null, recovery = {}) {
    const activeGenerationId = walStore?.meta?.activeCheckpoint || recovery?.wal?.generationId || ''
    const records = activeGenerationId ? getWalRecordsForGeneration(walStore, activeGenerationId) : []
    const checkpoints = walStore && typeof walStore === 'object' && walStore.checkpoints && typeof walStore.checkpoints === 'object'
        ? Object.keys(walStore.checkpoints)
        : []
    const generations = walStore && typeof walStore === 'object' && walStore.wal && typeof walStore.wal === 'object'
        ? Object.keys(walStore.wal)
        : []
    const ignored = Array.isArray(recovery?.wal?.projected?.ignored) ? recovery.wal.projected.ignored : []
    const applied = Array.isArray(recovery?.wal?.projected?.applied) ? recovery.wal.projected.applied : []

    return {
        present: !!walStore,
        recovered: recovery?.recovered === true,
        recoveryReason: recovery?.reason || '',
        activeGenerationId,
        checkpointCount: checkpoints.length,
        generationCount: generations.length,
        activeTailRecords: records.length,
        appliedRecords: applied.length,
        ignoredRecords: ignored.length,
        nextSeq: Number.parseInt(walStore?.meta?.nextSeq, 10) || 0
    }
}

function makeCoordinatorCurrentWorkAccounting(queue = {}) {
    const counts = makeCoordinatorQueueAccountingCounts(queue).counts
    const ready = Number(counts.queued) || 0
    const active = ['opening', 'active', 'acting', 'settling']
        .reduce((total, status) => total + (Number(counts[status]) || 0), 0)
    const succeeded = Number(counts.succeeded) || 0
    const failed = Number(counts.failed) || 0

    return {
        ready,
        active,
        succeeded,
        failed,
        terminal: Object.entries(counts)
            .filter(([status]) => isTerminalCoordinatorStatus(status))
            .reduce((total, [, count]) => total + (Number(count) || 0), 0)
    }
}

async function getCoordinatorQueueAccounting(request = {}) {
    const stored = await metricStorageGet({
        [COORDINATOR_QUEUE_KEY]: {},
        ...getCoordinatorQueueWalStorageDefaults(),
        [COORDINATOR_RUNS_KEY]: {},
        [COORDINATOR_QUEUE_VIEW_KEY]: null
    }, {metricPath: 'queueAccounting.read'})
    const rawQueue = normalizeCoordinatorMap(stored[COORDINATOR_QUEUE_KEY] || {})
    const runs = normalizeCoordinatorMap(stored[COORDINATOR_RUNS_KEY] || {})
    const walStore = await loadCoordinatorQueueWalStoreFromStorage(stored, rawQueue, {
        metricPath: 'queueAccounting.read.segments'
    })
    const recovery = recoverCoordinatorQueueFromWal(rawQueue, walStore)
    const recoveredQueue = normalizeCoordinatorMap(recovery.queue || rawQueue)
    const compactRecoveredQueue = filterCoordinatorQueueForCompactView(recoveredQueue, runs)
    const raw = makeCoordinatorQueueAccountingCounts(rawQueue)
    const recovered = makeCoordinatorQueueAccountingCounts(recoveredQueue)
    const storedView = normalizeCoordinatorQueueViewAccounting(stored[COORDINATOR_QUEUE_VIEW_KEY])
    const rebuiltView = normalizeCoordinatorQueueViewAccounting(buildCoordinatorQueueView(recoveredQueue, Date.now(), {runs}))
    const rawDivergences = makeCoordinatorQueueAccountingComparison(raw, recovered, 'raw-vs-recovered-')
    const viewMismatches = makeCoordinatorQueueAccountingComparison(storedView, rebuiltView, 'stored-view-vs-recovered-')
    const mismatches = []

    if(storedView.present && viewMismatches.length) mismatches.push(...viewMismatches)
    if(walStore && recovery.recovered !== true) mismatches.push('wal-recovery-failed')

    return {
        readOnly: true,
        reason: `${request.reason || ''}`.trim() || 'manual',
        generatedAt: Date.now(),
        consistent: !viewMismatches.length && (!walStore || recovery.recovered === true),
        raw,
        recovered,
        storedView,
        rebuiltView,
        currentWork: makeCoordinatorCurrentWorkAccounting(compactRecoveredQueue),
        wal: summarizeCoordinatorQueueWalAccounting(walStore, recovery),
        rawDivergences,
        mismatches
    }
}

function summarizeCoordinatorContentQueueItem(key = '', item = {}) {
    const source = item && typeof item === 'object' ? item : {}
    const profileHref = getCoordinatorItemHref(source) || normalizeQuoraProfileUrl(key)
    return {
        ...summarizeCoordinatorQueueViewItem(key, source),
        profileHref,
        tabId: Number.isFinite(source.tabId) ? source.tabId : source.tabId || null,
        attemptId: getAttemptIdFromValue(source),
        attemptNumber: getAttemptNumberFromValue(source),
        maxAttempts: Number.parseInt(source.maxAttempts, 10) || 0
    }
}

function shouldIncludeCoordinatorItemInContentQueueIndex(item = null) {
    if(!item || typeof item !== 'object') return false
    return !isTerminalCoordinatorStatus(item.status)
}

function buildCoordinatorContentQueueIndex(queue = {}, now = Date.now()) {
    const entries = Object.entries(queue || {})
        .filter(([, item]) => shouldIncludeCoordinatorItemInContentQueueIndex(item))
        .sort((left, right) => {
            const leftItem = left[1] || {}
            const rightItem = right[1] || {}
            return getCoordinatorQueueViewSortRank(leftItem) - getCoordinatorQueueViewSortRank(rightItem) ||
                getCoordinatorQueueViewTime(rightItem) - getCoordinatorQueueViewTime(leftItem) ||
                `${left[0]}`.localeCompare(`${right[0]}`)
        })
    const items = entries
        .slice(0, MAX_COORDINATOR_CONTENT_QUEUE_INDEX_ITEMS)
        .map(([key, item]) => summarizeCoordinatorContentQueueItem(key, item))

    return {
        version: 2,
        updatedAt: now,
        total: Object.keys(queue || {}).length,
        indexed: entries.length,
        itemLimit: MAX_COORDINATOR_CONTENT_QUEUE_INDEX_ITEMS,
        truncated: entries.length > items.length,
        items
    }
}

function hashCoordinatorContentIndexKey(value = '', bucketCount = COORDINATOR_CONTENT_SOURCE_INDEX_SHARD_COUNT) {
    return hashProjectionShardKey(value, bucketCount)
}

function getCoordinatorContentSourceIndexShardKeyByIndex(index = 0) {
    return getProjectionShardKeyByIndex(
        COORDINATOR_CONTENT_SOURCE_INDEX_PREFIX,
        COORDINATOR_CONTENT_SOURCE_INDEX_SHARD_COUNT,
        index
    )
}

function getCoordinatorContentSourceIndexShardKey(sourceKey = '') {
    return getProjectionShardKey(
        COORDINATOR_CONTENT_SOURCE_INDEX_PREFIX,
        COORDINATOR_CONTENT_SOURCE_INDEX_SHARD_COUNT,
        sourceKey
    )
}

function getCoordinatorContentSourceKeysFromValues(pageUrl = '', searchQuery = '', sourceType = '') {
    const keys = []
    const normalizedPageUrl = normalizeContentPageStateUrl(pageUrl || '')
    if(normalizedPageUrl) keys.push(`url:${normalizedPageUrl}`)

    const normalizedQuery = `${searchQuery || ''}`.trim().toLowerCase()
    if(normalizedQuery && (!sourceType || `${sourceType || ''}` === 'profile-search')) {
        keys.push(`profile-search:${normalizedQuery}`)
    }

    return Array.from(new Set(keys))
}

function getCoordinatorContentSourceKeysForItem(item = null) {
    const keys = []
    for(const source of getCoordinatorItemStateSources(item)) {
        keys.push(...getCoordinatorContentSourceKeysFromValues(
            source?.pageUrl || source?.sourcePageUrl || '',
            source?.searchQuery || '',
            source?.type || ''
        ))
    }
    return Array.from(new Set(keys))
}

function getCoordinatorContentSourceKeysForRequest(request = {}) {
    return getCoordinatorContentSourceKeysFromValues(
        request.sourcePageUrl || request.url || '',
        request.searchQuery || '',
        'profile-search'
    )
}

function getCoordinatorContentSourceIndexShardDefaults(request = {}) {
    const defaults = {}
    for(const sourceKey of getCoordinatorContentSourceKeysForRequest(request)) {
        const shardKey = getCoordinatorContentSourceIndexShardKey(sourceKey)
        if(shardKey) defaults[shardKey] = {}
    }
    return defaults
}

function buildCoordinatorContentSourceIndexShardPayload(queue = {}, now = Date.now()) {
    const shards = makeProjectionShardDefaults(
        COORDINATOR_CONTENT_SOURCE_INDEX_PREFIX,
        COORDINATOR_CONTENT_SOURCE_INDEX_SHARD_COUNT,
        () => ({
            version: 1,
            updatedAt: now,
            records: {}
        })
    )

    for(const [itemKey, item] of Object.entries(queue || {})) {
        if(!shouldIncludeCoordinatorItemInContentQueueIndex(item)) continue
        const summary = summarizeCoordinatorContentQueueItem(itemKey, item)
        const sourceKeys = getCoordinatorContentSourceKeysForItem(item)
        for(const sourceKey of sourceKeys) {
            const shardKey = getCoordinatorContentSourceIndexShardKey(sourceKey)
            if(!shardKey) continue
            if(!shards[shardKey].records[sourceKey]) {
                shards[shardKey].records[sourceKey] = {
                    items: []
                }
            }
            shards[shardKey].records[sourceKey].items.push(summary)
        }
    }

    return shards
}

function buildCoordinatorQueueDerivedProjectionPayload(queue = {}, now = Date.now()) {
    return {
        [COORDINATOR_QUEUE_VIEW_KEY]: buildCoordinatorQueueView(queue, now),
        [COORDINATOR_CONTENT_QUEUE_INDEX_KEY]: buildCoordinatorContentQueueIndex(queue, now),
        ...buildCoordinatorContentSourceIndexShardPayload(queue, now)
    }
}

function makeCoordinatorQueueWalCheckpoint(queue = {}, options = {}) {
    return makePairedCheckpointStore({queue: normalizeCoordinatorMap(cloneCoordinatorAuthorityValue(queue || {}))}, {
        snapshotSeq: Number.parseInt(options.snapshotSeq, 10) || 0,
        nextSeq: Number.parseInt(options.nextSeq, 10) || 1,
        createdAt: Number.parseInt(options.createdAt, 10) || Date.now()
    })
}

function summarizeProfileNukeProgressRecord(profileHref = '', record = {}) {
    const href = normalizeQuoraProfileUrl(record?.profileHref || profileHref || '')
    if(!href) return null

    const source = record && typeof record === 'object' ? record : {}
    return {
        profileHref: href,
        status: source.status || '',
        actionKind: source.actionKind || '',
        attemptId: getAttemptIdFromValue(source),
        attemptNumber: getAttemptNumberFromValue(source),
        runId: source.runId || '',
        tabId: Number.isFinite(source.tabId) ? source.tabId : source.tabId || null,
        lastUrl: source.lastUrl || '',
        queuedAt: Number.parseInt(source.queuedAt, 10) || 0,
        tabCreatedAt: Number.parseInt(source.tabCreatedAt, 10) || 0,
        tabOpenedAt: Number.parseInt(source.tabOpenedAt, 10) || 0,
        contentOpenedAt: Number.parseInt(source.contentOpenedAt, 10) || 0,
        actionReadyAt: Number.parseInt(source.actionReadyAt, 10) || 0,
        waitingForForegroundAt: Number.parseInt(source.waitingForForegroundAt, 10) || 0,
        foregroundLeaseAcquiredAt: Number.parseInt(source.foregroundLeaseAcquiredAt, 10) || 0,
        foregroundPromotedAt: Number.parseInt(source.foregroundPromotedAt, 10) || 0,
        muteAttemptedAt: Number.parseInt(source.muteAttemptedAt, 10) || 0,
        blockAttemptedAt: Number.parseInt(source.blockAttemptedAt, 10) || 0,
        unmuteAttemptedAt: Number.parseInt(source.unmuteAttemptedAt, 10) || 0,
        unblockAttemptedAt: Number.parseInt(source.unblockAttemptedAt, 10) || 0,
        terminalAt: Number.parseInt(source.terminalAt, 10) || 0,
        updatedAt: Number.parseInt(source.updatedAt, 10) || 0,
        actionSurfaceMode: source.actionSurfaceMode || '',
        actionSurfaceWindowId: source.actionSurfaceWindowId || null,
        actionSurfaceAnchorTabId: source.actionSurfaceAnchorTabId || null,
        actionSurfaceActivatedAt: Number.parseInt(source.actionSurfaceActivatedAt, 10) || 0,
        muteSucceeded: source.muteSucceeded === true,
        blockSucceeded: source.blockSucceeded === true,
        unblockSucceeded: source.unblockSucceeded === true,
        unmuteSucceeded: source.unmuteSucceeded === true,
        foundBlockedBeforeQueue: source.foundBlockedBeforeQueue === true,
        finalError: source.finalError || '',
        muteError: source.muteError || '',
        blockError: source.blockError || '',
        directBlockFailureDetail: source.directBlockFailureDetail &&
            typeof source.directBlockFailureDetail === 'object'
            ? source.directBlockFailureDetail
            : null,
        unblockReason: source.unblockReason || '',
        unmuteReason: source.unmuteReason || '',
        unavailableReason: source.unavailableReason || '',
        resolvedProfileHref: source.resolvedProfileHref || '',
        remappedFromRequested: source.remappedFromRequested === true,
        closeReason: source.closeReason || '',
        errorPageUrl: source.errorPageUrl || '',
        securityVerificationUrl: source.securityVerificationUrl || ''
    }
}

function buildProfileNukeProgressView(progress = {}, now = Date.now()) {
    const normalized = normalizeStoredProfileNukeProgress(progress || {})
    const entries = Object.entries(normalized)
        .sort((left, right) => {
            const leftUpdatedAt = Number.parseInt(left[1]?.updatedAt, 10) || 0
            const rightUpdatedAt = Number.parseInt(right[1]?.updatedAt, 10) || 0
            return rightUpdatedAt - leftUpdatedAt || left[0].localeCompare(right[0])
        })
    const records = {}
    for(const [profileHref, record] of entries.slice(0, MAX_PROFILE_NUKE_PROGRESS_VIEW_RECORDS)) {
        const summary = summarizeProfileNukeProgressRecord(profileHref, record)
        if(summary) records[summary.profileHref] = summary
    }

    return {
        version: 2,
        updatedAt: now,
        total: entries.length,
        recordLimit: MAX_PROFILE_NUKE_PROGRESS_VIEW_RECORDS,
        truncated: entries.length > Object.keys(records).length,
        records
    }
}

function getProfileNukeProgressShardIndex(profileHref = '') {
    const href = normalizeQuoraProfileUrl(profileHref)
    return hashProjectionShardKey(href, PROFILE_NUKE_PROGRESS_SHARD_COUNT)
}

function getProfileNukeProgressShardKeyByIndex(index = 0) {
    return getProjectionShardKeyByIndex(
        PROFILE_NUKE_PROGRESS_SHARD_PREFIX,
        PROFILE_NUKE_PROGRESS_SHARD_COUNT,
        index
    )
}

function getProfileNukeProgressShardKey(profileHref = '') {
    return getProjectionShardKey(
        PROFILE_NUKE_PROGRESS_SHARD_PREFIX,
        PROFILE_NUKE_PROGRESS_SHARD_COUNT,
        normalizeQuoraProfileUrl(profileHref)
    )
}

function getProfileNukeProgressShardDefaults(profileHrefs = []) {
    const defaults = {}
    for(const href of getNormalizedProfileHrefList(profileHrefs || [])) {
        const key = getProfileNukeProgressShardKey(href)
        if(key) defaults[key] = {}
    }
    return defaults
}

function getAllProfileNukeProgressShardDefaults() {
    return makeProjectionShardDefaults(
        PROFILE_NUKE_PROGRESS_SHARD_PREFIX,
        PROFILE_NUKE_PROGRESS_SHARD_COUNT
    )
}

function getProfileNukeProgressProjectionDefaults(profileHrefs = [], options = {}) {
    const hrefs = getNormalizedProfileHrefList(profileHrefs || [])
    const includeView = options.includeView !== false
    return {
        ...(includeView ? {[PROFILE_NUKE_PROGRESS_VIEW_KEY]: null} : {}),
        ...(hrefs.length
            ? getProfileNukeProgressShardDefaults(hrefs)
            : getAllProfileNukeProgressShardDefaults())
    }
}

function buildProfileNukeProgressShardPayload(progress = {}, now = Date.now()) {
    const normalized = normalizeStoredProfileNukeProgress(progress || {})
    const shards = {}
    for(let index = 0; index < PROFILE_NUKE_PROGRESS_SHARD_COUNT; index += 1) {
        shards[getProfileNukeProgressShardKeyByIndex(index)] = {
            version: 1,
            updatedAt: now,
            records: {}
        }
    }

    for(const [profileHref, record] of Object.entries(normalized)) {
        const key = getProfileNukeProgressShardKey(profileHref)
        if(!key) continue
        const summary = summarizeProfileNukeProgressRecord(profileHref, record)
        if(summary) shards[key].records[summary.profileHref] = summary
    }

    return shards
}

function hasNonterminalCoordinatorAuthorityForProfile(queue = {}, profileHref = '') {
    const href = normalizeQuoraProfileUrl(profileHref)
    if(!href) return false

    return Object.entries(queue || {}).some(([itemKey, item]) => {
        if(!item || typeof item !== 'object') return false
        if(isTerminalCoordinatorStatus(item.status)) return false
        const itemHref = getCoordinatorItemHref(item) || normalizeQuoraProfileUrl(itemKey)
        return itemHref === href
    })
}

function filterProfileNukeProgressForContentProjection(progress = {}, queue = {}) {
    const normalized = normalizeStoredProfileNukeProgress(progress || {})
    const filtered = {}
    for(const [profileHref, record] of Object.entries(normalized)) {
        if(hasNonterminalCoordinatorAuthorityForProfile(queue, profileHref)) continue
        filtered[profileHref] = record
    }
    return filtered
}

function updateProfileNukeProgressViewRecords(view = null, progressRecords = {}, now = Date.now()) {
    const current = normalizeProfileNukeProgressView(view)
    const records = {
        ...current.records
    }
    const previousCount = Object.keys(records).length

    for(const [profileHref, record] of Object.entries(progressRecords || {})) {
        const summary = summarizeProfileNukeProgressRecord(profileHref, record)
        if(summary) records[summary.profileHref] = summary
    }

    const recordLimit = Number.parseInt(current.recordLimit, 10) || MAX_PROFILE_NUKE_PROGRESS_VIEW_RECORDS
    const entries = Object.entries(records)
        .sort((left, right) => {
            const leftUpdatedAt = Number.parseInt(left[1]?.updatedAt, 10) || 0
            const rightUpdatedAt = Number.parseInt(right[1]?.updatedAt, 10) || 0
            return rightUpdatedAt - leftUpdatedAt || left[0].localeCompare(right[0])
        })
    const capped = Object.fromEntries(entries.slice(0, recordLimit))
    const knownTotal = Number.parseInt(current.total, 10) || previousCount
    const total = Math.max(knownTotal, Object.keys(records).length)

    return {
        version: 2,
        updatedAt: now,
        total,
        recordLimit,
        truncated: total > Object.keys(capped).length || entries.length > Object.keys(capped).length,
        records: capped
    }
}

function updateProfileNukeProgressShardRecord(shard = null, profileHref = '', record = null, now = Date.now()) {
    const href = normalizeQuoraProfileUrl(record?.profileHref || profileHref || '')
    const summary = summarizeProfileNukeProgressRecord(href, record)
    const records = normalizeProfileNukeProgressShardRecords({current: shard})
    if(summary) records[summary.profileHref] = summary

    return {
        version: 1,
        updatedAt: now,
        records
    }
}

function removeProfileNukeProgressViewRecords(view = null, profileHrefs = [], knownRemovedCount = 0, now = Date.now()) {
    const current = normalizeProfileNukeProgressView(view)
    const records = {
        ...current.records
    }
    for(const href of getNormalizedProfileHrefList(profileHrefs || [])) {
        delete records[href]
    }

    const recordLimit = Number.parseInt(current.recordLimit, 10) || MAX_PROFILE_NUKE_PROGRESS_VIEW_RECORDS
    const entries = Object.entries(records)
        .sort((left, right) => {
            const leftUpdatedAt = Number.parseInt(left[1]?.updatedAt, 10) || 0
            const rightUpdatedAt = Number.parseInt(right[1]?.updatedAt, 10) || 0
            return rightUpdatedAt - leftUpdatedAt || left[0].localeCompare(`${right[0]}`)
        })
    const capped = Object.fromEntries(entries.slice(0, recordLimit))
    const currentTotal = Number.parseInt(current.total, 10) || Object.keys(current.records).length
    const total = Math.max(0, currentTotal - Math.max(0, Number.parseInt(knownRemovedCount, 10) || 0))

    return {
        version: 2,
        updatedAt: now,
        total,
        recordLimit,
        truncated: total > Object.keys(capped).length || entries.length > Object.keys(capped).length,
        records: capped
    }
}

function removeProfileNukeProgressShardRecords(shard = null, profileHrefs = [], now = Date.now()) {
    const records = normalizeProfileNukeProgressShardRecords({current: shard})
    for(const href of getNormalizedProfileHrefList(profileHrefs || [])) {
        delete records[href]
    }

    return {
        version: 1,
        updatedAt: now,
        records
    }
}

async function saveProfileNukeProgressRowProjection(progressRecords = {}, options = {}) {
    const normalizedRecords = normalizeStoredProfileNukeProgress(progressRecords || {})
    const hrefs = Object.keys(normalizedRecords)
    if(!hrefs.length) return false

    const shardDefaults = getProfileNukeProgressShardDefaults(hrefs)
    const metricPath = normalizeStorageMetricPathName(options.metricPath || 'rowEvent.progressProjection')
    const includeView = options.view !== false
    const stored = await metricStorageGet({
        ...(includeView ? {[PROFILE_NUKE_PROGRESS_VIEW_KEY]: null} : {}),
        ...shardDefaults
    }, {metricPath: `${metricPath}.load`})

    const now = Date.now()
    const payload = includeView ? {
        [PROFILE_NUKE_PROGRESS_VIEW_KEY]: updateProfileNukeProgressViewRecords(
            stored[PROFILE_NUKE_PROGRESS_VIEW_KEY],
            normalizedRecords,
            now
        )
    } : {}

    for(const [profileHref, record] of Object.entries(normalizedRecords)) {
        const shardKey = getProfileNukeProgressShardKey(profileHref)
        if(!shardKey) continue
        payload[shardKey] = updateProfileNukeProgressShardRecord(payload[shardKey] || stored[shardKey], profileHref, record, now)
    }

    let saved = false
    try {
        saved = await metricStorageSet(payload, {metricPath: `${metricPath}.save`})
    }
    catch(error) {
        incrementQueueWakeupMetric('progress.rowProjectionStorageFailed')
        recordCoordinatorDiagnosticEvent(
            'progress-row-projection-storage-failed',
            error?.message || 'Progress row projection storage failed'
        )
        saved = false
    }
    if(saved === false) {
        incrementQueueWakeupMetric('progress.rowProjectionStorageSuppressed')
        return false
    }
    for(const [profileHref, record] of Object.entries(normalizedRecords)) {
        profileNukeProgress = {
            ...profileNukeProgress,
            [profileHref]: cloneCoordinatorAuthorityValue(record)
        }
    }
    profileNukeProgressProjectionVersion += 1
    incrementQueueWakeupMetric('progress.rowProjectionStorageWrites')
    incrementQueueWakeupMetric('progress.rowProjectionRowsPerStorageWrite', hrefs.length)
    return {
        saved: true,
        records: cloneCoordinatorAuthorityValue(normalizedRecords),
        rows: hrefs.length
    }
}

function scheduleTerminalProgressProjectionFlush() {
    if(terminalProgressProjectionSaveScheduled || terminalProgressProjectionSavePromise) return

    terminalProgressProjectionSaveScheduled = true
    Promise.resolve().then(() => {
        terminalProgressProjectionSaveScheduled = false
        terminalProgressProjectionSavePromise = flushTerminalProgressProjectionSaves()
            .finally(() => {
                terminalProgressProjectionSavePromise = null
                if(terminalProgressProjectionSaveBatches.size) {
                    scheduleTerminalProgressProjectionFlush()
                }
            })
    })
}

async function flushTerminalProgressProjectionSaves() {
    const batches = Array.from(terminalProgressProjectionSaveBatches.entries())
    terminalProgressProjectionSaveBatches.clear()

    for(const [metricPath, records] of batches) {
        try {
            const result = await promiseWithTimeout(
                saveProfileNukeProgressRowProjection(records, {
                    metricPath,
                    view: true
                }),
                COORDINATOR_ACTIVE_RECONCILE_STORAGE_UPDATE_TIMEOUT_MS,
                'terminal progress projection save'
            )
            if(result === false || result?.saved === false) {
                incrementQueueWakeupMetric('terminalProgress.derivedSaveFailed')
                scheduleCoordinatorReconcile(1000, {
                    reason: 'terminal-progress-projection-save-failed',
                    edgeTriggered: true
                })
            }
        }
        catch(error) {
            incrementQueueWakeupMetric('terminalProgress.projectionSaveFailed')
            recordCoordinatorDiagnosticEvent(
                'terminal-progress-projection-save-failed',
                error?.message || 'Terminal progress projection save failed'
            )
            scheduleCoordinatorReconcile(1000, {
                reason: 'terminal-progress-projection-save-failed',
                edgeTriggered: true
            })
        }
    }
}

function saveTerminalProgressProjectionAfterAuthority(progressRecords = {}, metricPath = 'terminalProgress.inline.progressProjection') {
    const normalizedRecords = normalizeStoredProfileNukeProgress(progressRecords || {})
    if(!Object.keys(normalizedRecords).length) return

    const existing = terminalProgressProjectionSaveBatches.get(metricPath) || {}
    terminalProgressProjectionSaveBatches.set(metricPath, {
        ...existing,
        ...normalizedRecords
    })
    scheduleTerminalProgressProjectionFlush()
}

async function deleteProfileNukeProgressRowProjection(profileHrefs = [], options = {}) {
    const hrefs = getNormalizedProfileHrefList(profileHrefs || [])
    if(!hrefs.length) return {saved: true, rows: 0}

    const shardDefaults = getProfileNukeProgressShardDefaults(hrefs)
    const metricPath = normalizeStorageMetricPathName(options.metricPath || 'rowEvent.progressProjectionDelete')
    const stored = await metricStorageGet({
        [PROFILE_NUKE_PROGRESS_VIEW_KEY]: null,
        ...shardDefaults
    }, {metricPath: `${metricPath}.load`})

    const view = normalizeProfileNukeProgressView(stored[PROFILE_NUKE_PROGRESS_VIEW_KEY])
    const removedHrefs = new Set()
    for(const href of hrefs) {
        if(view.records[href]) removedHrefs.add(href)
    }
    for(const shardKey of Object.keys(shardDefaults)) {
        const records = normalizeProfileNukeProgressShardRecords({[shardKey]: stored[shardKey]})
        for(const href of hrefs) {
            if(records[href]) removedHrefs.add(href)
        }
    }

    if(!removedHrefs.size) return {saved: true, rows: 0}

    const now = Date.now()
    const payload = {
        [PROFILE_NUKE_PROGRESS_VIEW_KEY]: removeProfileNukeProgressViewRecords(
            stored[PROFILE_NUKE_PROGRESS_VIEW_KEY],
            hrefs,
            removedHrefs.size,
            now
        )
    }
    for(const shardKey of Object.keys(shardDefaults)) {
        payload[shardKey] = removeProfileNukeProgressShardRecords(stored[shardKey], hrefs, now)
    }

    let saved = false
    try {
        saved = await metricStorageSet(payload, {metricPath: `${metricPath}.save`})
    }
    catch(error) {
        incrementQueueWakeupMetric('progress.rowProjectionDeleteStorageFailed')
        recordCoordinatorDiagnosticEvent(
            'progress-row-projection-delete-storage-failed',
            error?.message || 'Progress row projection delete storage failed'
        )
        saved = false
    }
    if(saved === false) {
        incrementQueueWakeupMetric('progress.rowProjectionDeleteStorageSuppressed')
        return false
    }
    incrementQueueWakeupMetric('progress.rowProjectionDeleteStorageWrites')
    incrementQueueWakeupMetric('progress.rowProjectionDeleteRowsPerStorageWrite', removedHrefs.size)
    return {
        saved: true,
        rows: removedHrefs.size,
        profileHrefs: Array.from(removedHrefs)
    }
}

function normalizeProfileNukeProgressShardRecords(shards = {}) {
    const records = {}
    for(const shard of Object.values(shards || {})) {
        const shardRecords = shard && typeof shard === 'object' && shard.records && typeof shard.records === 'object'
            ? shard.records
            : {}
        Object.assign(records, normalizeStoredProfileNukeProgress(shardRecords))
    }
    return records
}

function getProfileNukeProgressRecordsFromProjection(stored = {}, profileHrefs = [], options = {}) {
    const hrefs = getNormalizedProfileHrefList(profileHrefs || [])
    const requested = hrefs.length ? new Set(hrefs) : null
    const viewRecords = options.includeView === false
        ? {}
        : normalizeProfileNukeProgressView(stored?.[PROFILE_NUKE_PROGRESS_VIEW_KEY]).records
    const shardDefaults = requested
        ? getProfileNukeProgressShardDefaults(hrefs)
        : getAllProfileNukeProgressShardDefaults()
    const shardRecords = normalizeProfileNukeProgressShardRecords(
        Object.fromEntries(Object.keys(shardDefaults).map(key => [key, stored?.[key]]))
    )
    const progress = {}
    for(const [profileHref, record] of Object.entries({
        ...viewRecords,
        ...shardRecords
    })) {
        if(!requested || requested.has(profileHref)) progress[profileHref] = record
    }
    return progress
}

function addContentPageStateProjectionPayload(payload = {}) {
    if(!payload || typeof payload !== 'object') return payload
    const next = {
        ...payload
    }
    const now = Date.now()
    if(
        Object.prototype.hasOwnProperty.call(next, COORDINATOR_QUEUE_KEY) &&
        next[COORDINATOR_QUEUE_KEY] &&
        typeof next[COORDINATOR_QUEUE_KEY] === 'object'
    ) {
        const queue = normalizeCoordinatorMap(next[COORDINATOR_QUEUE_KEY])
        if(!Object.prototype.hasOwnProperty.call(next, COORDINATOR_QUEUE_WAL_KEY)) {
            next[COORDINATOR_QUEUE_WAL_KEY] = makeCoordinatorQueueWalCheckpoint(queue, {createdAt: now})
        }
        if(!Object.prototype.hasOwnProperty.call(next, COORDINATOR_QUEUE_VIEW_KEY)) {
            next[COORDINATOR_QUEUE_VIEW_KEY] = buildCoordinatorQueueView(queue, now)
        }
        if(!Object.prototype.hasOwnProperty.call(next, COORDINATOR_CONTENT_QUEUE_INDEX_KEY)) {
            next[COORDINATOR_CONTENT_QUEUE_INDEX_KEY] = buildCoordinatorContentQueueIndex(queue, now)
        }
        if(!Object.keys(next).some(key => `${key || ''}`.startsWith(COORDINATOR_CONTENT_SOURCE_INDEX_PREFIX))) {
            Object.assign(next, buildCoordinatorContentSourceIndexShardPayload(queue, now))
        }
    }
    return next
}

async function refreshCoordinatorQueueViewForDashboard(reason = 'dashboard-refresh') {
    recordFlightRecorderEvent({
        kind: 'dashboard-refresh',
        source: 'refreshCoordinatorQueueViewForDashboard',
        reason
    })
    const currentAuthorityState = await loadCoordinatorQueueProjection({
        metricPath: `queueView.${reason}`
    })
    const stored = await metricStorageGet({
        [COORDINATOR_RUNS_KEY]: {}
    }, {metricPath: `queueView.${reason}.runs`})
    const queue = currentAuthorityState.queue
    const runs = normalizeCoordinatorMap(stored[COORDINATOR_RUNS_KEY] || {})
    const view = buildCoordinatorQueueView(queue, Date.now(), {runs})
    await metricStorageSet({
        [COORDINATOR_QUEUE_VIEW_KEY]: view
    }, {metricPath: `queueView.${reason}`})
    recordFlightRecorderEvent({
        kind: 'compact-view-materialized',
        source: 'refreshCoordinatorQueueViewForDashboard',
        reason,
        changed: true
    })
    return {
        refreshed: true,
        reason,
        total: view.total,
        truncated: view.truncated,
        view
    }
}

function makeEmptyCoordinatorMilestones() {
    return makeEmptyJobMilestones()
}

function shouldResetCoordinatorFailureFromProgress(item = null, record = null, mapped = null) {
    if(!isRetryableCoordinatorFailureFromProgress(item, record)) return false
    if(!mapped || isTerminalCoordinatorStatus(mapped.status)) return false
    if(!isTransientProfileNukeStatus(record?.status)) return false

    const recordRunId = `${record?.runId || ''}`.trim()
    const itemRunId = `${item?.runId || ''}`.trim()
    if(recordRunId && recordRunId !== itemRunId) return true

    const recordUpdatedAt = Number.parseInt(record?.updatedAt, 10) || 0
    const itemTerminalAt = Number.parseInt(item?.terminalAt, 10) || 0
    return recordUpdatedAt > 0 && itemTerminalAt > 0 && recordUpdatedAt >= itemTerminalAt
}

function getCoordinatorRunStatus(runItems = [], existingRun = {}) {
    if(!runItems.length) return existingRun?.paused ? 'paused' : 'complete'

    const terminalCount = runItems.filter(item => isTerminalCoordinatorStatus(item?.status)).length
    if(terminalCount === runItems.length) return 'complete'
    if(existingRun?.paused) return 'paused'
    return 'active'
}

function materializeCoordinatorRunsPausedStateFromControl(queue = {}, runs = {}, paused = false, now = Date.now()) {
    const nextRuns = {...(runs || {})}
    const targetRunIds = new Set(Object.keys(nextRuns))
    const affectedRunIds = []

    for(const item of Object.values(queue || {})) {
        const runId = `${item?.runId || ''}`.trim()
        if(runId) targetRunIds.add(runId)
    }

    for(const runId of targetRunIds) {
        const run = nextRuns[runId]
        if(!run || typeof run !== 'object') continue

        const runItems = getCoordinatorRunItems(queue, runId, run)
        if(!runItems.some(item => isPendingCoordinatorStatus(item?.status))) continue

        const status = paused ? 'paused' : 'active'
        if(run.paused === paused && `${run.status || ''}` === status) continue

        nextRuns[runId] = {
            ...run,
            paused,
            status,
            updatedAt: Math.max(Number.parseInt(run.updatedAt, 10) || 0, now)
        }
        affectedRunIds.push(runId)
    }

    return {
        changed: affectedRunIds.length > 0,
        runs: affectedRunIds.length ? nextRuns : runs,
        affectedRunIds
    }
}

function getCoordinatorRunTargetHrefs(run = {}) {
    return getNormalizedProfileHrefList(run?.targetProfileHrefs || [])
}

function isCoordinatorRunWorkKeyForProfileHref(workKey = '', normalizedHref = '') {
    const key = `${workKey || ''}`.trim()
    if(!key || !normalizedHref) return false
    if(key === normalizedHref) return true

    return normalizeQuoraProfileUrl(key) === normalizedHref
}

function getCoordinatorRunItems(queue = {}, runId = '', existingRun = {}) {
    const targetHrefs = new Set(getCoordinatorRunTargetHrefs(existingRun))

    return Object.entries(queue || {})
        .filter(([itemKey, item]) => {
            if(item?.runId === runId) return true
            if(!targetHrefs.size) return false

            const href = getCoordinatorItemHref(item) || normalizeQuoraProfileUrl(itemKey)
            return !!href && targetHrefs.has(href)
        })
        .map(([, item]) => item)
}

function getCoordinatorRunIdsForHref(runs = {}, href = '') {
    const normalizedHref = normalizeQuoraProfileUrl(href)
    if(!normalizedHref) return []

    return Object.values(runs || {})
        .filter(run => {
            if(getCoordinatorRunTargetHrefs(run).includes(normalizedHref)) return true

            return (Array.isArray(run?.targetWorkKeys) ? run.targetWorkKeys : [])
                .some(key => isCoordinatorRunWorkKeyForProfileHref(key, normalizedHref))
        })
        .map(run => run?.id || run?.runId || '')
        .filter(Boolean)
}

function recomputeCoordinatorRuns(queue = {}, runs = {}, runIds = null) {
    return runQueueWakeupMetricPhase('recomputeRuns', () => {
        const nextRuns = {
            ...runs
        }
        const targetRunIds = new Set(runIds || Object.keys(nextRuns))

        for(const item of Object.values(queue || {})) {
            if(item?.runId && (!runIds || targetRunIds.has(item.runId))) {
                targetRunIds.add(item.runId)
            }
        }

        for(const runId of targetRunIds) {
            const existing = nextRuns[runId] || {
                id: runId,
                sourcePages: []
            }
            const runItems = getCoordinatorRunItems(queue, runId, existing)
            const targetHrefs = new Set(getCoordinatorRunTargetHrefs(existing))
            const targetWorkKeys = new Set(Array.isArray(existing.targetWorkKeys) ? existing.targetWorkKeys : [])
            const sourcePages = new Set(Array.isArray(existing.sourcePages) ? existing.sourcePages : [])
            for(const item of runItems) {
                const href = getCoordinatorItemHref(item)
                const workKey = getCoordinatorItemQueueKey(item) || href
                const sourcePageUrl = `${item?.source?.pageUrl || item?.source?.sourcePageUrl || ''}`.trim()
                if(href) targetHrefs.add(href)
                if(workKey) targetWorkKeys.add(workKey)
                if(sourcePageUrl) sourcePages.add(sourcePageUrl)
            }
            const targetProfileHrefs = Array.from(targetHrefs)
            const targetWorkKeyList = Array.from(targetWorkKeys)
            const terminalCount = runItems.filter(item => isTerminalCoordinatorStatus(item?.status)).length
            const activeCount = runItems.filter(item => isActiveCoordinatorStatus(item?.status)).length
            const latestItemUpdatedAt = runItems.reduce((latest, item) => {
                const updatedAt = Number.parseInt(item?.updatedAt || item?.terminalAt || item?.createdAt, 10) || 0
                return Math.max(latest, updatedAt)
            }, 0)

            nextRuns[runId] = {
                ...existing,
                id: runId,
                sourceType: existing.sourceType || runItems[0]?.source?.type || 'space-feed',
                createdAt: existing.createdAt || runItems[0]?.createdAt || Date.now(),
                sourcePages: Array.from(sourcePages),
                targetProfileHrefs,
                targetWorkKeys: targetWorkKeyList,
                itemCount: targetProfileHrefs.length || runItems.length || targetWorkKeyList.length || 0,
                activeCount,
                terminalCount,
                status: getCoordinatorRunStatus(runItems, existing),
                updatedAt: Math.max(Number.parseInt(existing.updatedAt, 10) || 0, latestItemUpdatedAt)
            }
        }

        return nextRuns
    })
}

function getCoordinatorTransitionTerminalAt(item = {}, record = {}, now = Date.now(), options = {}) {
    if(options.terminalAtFallback === 'record') {
        return Number.parseInt(record.terminalAt || record.tabClosedAt || record.updatedAt, 10) || item.terminalAt || now
    }

    return Number.isFinite(record.terminalAt) && record.terminalAt > 0 ? record.terminalAt : now
}

function getCoordinatorProgressReducerEventType(item = {}, mapped = {}, options = {}) {
    const status = `${mapped.status || ''}`.trim()
    if(isTerminalCoordinatorStatus(status)) return JOB_EVENT_TERMINAL
    if(status === 'queued') return options.resetRetry === true ? JOB_EVENT_RETRY : JOB_EVENT_ENQUEUED
    if(status === 'opening') return JOB_EVENT_TAB_OPENED
    return JOB_EVENT_MILESTONE
}

function getCoordinatorProgressRecordActiveAt(record = {}) {
    return Number.parseInt(
        record?.tabOpenedAt ||
        record?.tabCreatedAt ||
        record?.contentOpenedAt ||
        record?.navigationStartedAt,
        10
    ) || 0
}

function getCoordinatorProgressActiveAt(item = {}, record = {}, now = Date.now(), options = {}) {
    const recordActiveAt = getCoordinatorProgressRecordActiveAt(record)
    if(options.refreshActiveAt === true) return recordActiveAt || now
    return Number.parseInt(item?.activeAt, 10) || recordActiveAt || now
}

function buildProjectedCoordinatorItemFromProgress(item = {}, record = {}, mapped = {}, options = {}) {
    const now = Number.parseInt(options.now, 10) || Date.now()
    const resetRetry = options.resetRetry === true
    const mappedTerminal = isTerminalCoordinatorStatus(mapped.status)
    const progressActiveAt = getCoordinatorProgressActiveAt(item, record, now, {
        refreshActiveAt: options.refreshActiveAt === true
    })
    const terminalAt = mappedTerminal
        ? getCoordinatorTransitionTerminalAt(item, record, now, options)
        : 0
    const terminalActiveAt = mappedTerminal
        ? Math.min(
            progressActiveAt || terminalAt || now,
            terminalAt || progressActiveAt || now
        )
        : progressActiveAt

    return {
        ...item,
        runId: resetRetry ? record.runId || item.runId : item.runId,
        status: mapped.status,
        outcome: mappedTerminal ? mapped.outcome || item.outcome || '' : '',
        error: mappedTerminal ? mapped.error || '' : '',
        updatedAt: Math.max(Number.parseInt(item.updatedAt, 10) || 0, Number.parseInt(record.updatedAt, 10) || 0, now),
        queuedAt: resetRetry && mapped.status === 'queued'
            ? Number.parseInt(record.queuedAt, 10) || now
            : item.queuedAt || 0,
        activeAt: mapped.status === 'active'
            ? (options.refreshActiveAt === true
                ? progressActiveAt
                : progressActiveAt)
            : resetRetry ? 0 : mappedTerminal ? terminalActiveAt : item.activeAt || 0,
        terminalAt,
        actionLease: mappedTerminal || resetRetry ? null : item.actionLease || null,
        actionLeaseReleasedAt: mappedTerminal
            ? now
            : resetRetry ? 0 : item.actionLeaseReleasedAt || 0,
        actionLeaseReleaseReason: mappedTerminal
            ? 'terminal-progress'
            : resetRetry ? '' : item.actionLeaseReleaseReason || '',
        tabId: resetRetry ? null : (mapped.status === 'active' ? getPersistedQueuedTabId(item, record) : item.tabId || null),
        actionSurfaceMode: resetRetry ? '' : record.actionSurfaceMode || item.actionSurfaceMode || '',
        actionSurfaceWindowId: resetRetry ? null : record.actionSurfaceWindowId || item.actionSurfaceWindowId || null,
        actionSurfaceAnchorTabId: resetRetry ? null : record.actionSurfaceAnchorTabId || item.actionSurfaceAnchorTabId || null,
        actionSurfaceActivatedAt: resetRetry ? 0 : record.actionSurfaceActivatedAt || item.actionSurfaceActivatedAt || 0,
        attempt: resetRetry ? 0 : Number.parseInt(record.retryAttempt, 10) || item.attempt || 0,
        attemptId: resetRetry ? '' : getAttemptIdFromValue(record) || getAttemptIdFromValue(item),
        attemptNumber: resetRetry ? 0 : getAttemptNumberFromValue(record) || getAttemptNumberFromValue(item),
        retryAttempt: resetRetry
            ? Number.parseInt(record.retryAttempt, 10) || Number.parseInt(item.retryAttempt, 10) || 0
            : Number.parseInt(record.retryAttempt, 10) || Number.parseInt(item.retryAttempt, 10) || 0,
        maxRetries: resetRetry
            ? Number.parseInt(record.maxRetries, 10) || Number.parseInt(item.maxRetries, 10) || 0
            : Number.parseInt(record.maxRetries, 10) || Number.parseInt(item.maxRetries, 10) || 0,
        maxAttempts: (Number.parseInt(record.maxRetries, 10) || 0) + 1 || item.maxAttempts || 1,
        milestones: resetRetry ? {
            ...makeEmptyCoordinatorMilestones(),
            ...getCoordinatorMilestonesFromProgress(record)
        } : {
            ...(item.milestones || {}),
            ...getCoordinatorMilestonesFromProgress(record)
        }
    }
}

function mergeReducedCoordinatorProgressItem(item = {}, reducedItem = {}, projectedItem = {}, mapped = {}, record = {}, options = {}) {
    const status = `${mapped.status || ''}`.trim()
    const resetRetry = options.resetRetry === true
    const mappedTerminal = isTerminalCoordinatorStatus(status)

    return {
        ...projectedItem,
        status: reducedItem.status,
        outcome: mappedTerminal ? reducedItem.outcome || projectedItem.outcome || '' : '',
        error: mappedTerminal ? reducedItem.error || projectedItem.error || '' : '',
        updatedAt: Math.max(
            Number.parseInt(reducedItem.updatedAt, 10) || 0,
            Number.parseInt(projectedItem.updatedAt, 10) || 0
        ),
        queuedAt: status === 'queued' ? reducedItem.queuedAt || projectedItem.queuedAt || 0 : projectedItem.queuedAt || 0,
        activeAt: status === 'active' || status === 'acting' || status === 'settling'
            ? projectedItem.activeAt || reducedItem.activeAt || 0
            : resetRetry ? 0 : projectedItem.activeAt || reducedItem.activeAt || 0,
        terminalAt: mappedTerminal ? reducedItem.terminalAt || projectedItem.terminalAt || 0 : 0,
        tabId: mappedTerminal || resetRetry ? null : projectedItem.tabId ?? reducedItem.tabId ?? null,
        actionSurfaceMode: resetRetry ? '' : projectedItem.actionSurfaceMode || reducedItem.actionSurfaceMode || '',
        actionSurfaceWindowId: resetRetry ? null : projectedItem.actionSurfaceWindowId || reducedItem.actionSurfaceWindowId || null,
        actionSurfaceAnchorTabId: resetRetry ? null : projectedItem.actionSurfaceAnchorTabId || reducedItem.actionSurfaceAnchorTabId || null,
        actionSurfaceActivatedAt: resetRetry ? 0 : projectedItem.actionSurfaceActivatedAt || reducedItem.actionSurfaceActivatedAt || 0,
        actionLease: mappedTerminal || resetRetry ? null : reducedItem.actionLease || projectedItem.actionLease || null,
        actionLeaseReleasedAt: mappedTerminal
            ? reducedItem.actionLeaseReleasedAt || projectedItem.actionLeaseReleasedAt || 0
            : resetRetry ? 0 : reducedItem.actionLeaseReleasedAt || projectedItem.actionLeaseReleasedAt || 0,
        actionLeaseReleaseReason: mappedTerminal || resetRetry
            ? reducedItem.actionLeaseReleaseReason || projectedItem.actionLeaseReleaseReason || ''
            : projectedItem.actionLeaseReleaseReason || '',
        attemptId: resetRetry ? reducedItem.attemptId || projectedItem.attemptId || '' : reducedItem.attemptId || projectedItem.attemptId || '',
        attemptNumber: resetRetry ? reducedItem.attemptNumber || projectedItem.attemptNumber || 0 : reducedItem.attemptNumber || projectedItem.attemptNumber || 0,
        milestones: {
            ...makeEmptyCoordinatorMilestones(),
            ...(item.milestones || {}),
            ...(reducedItem.milestones || {}),
            ...getCoordinatorMilestonesFromProgress(record)
        }
    }
}

function transitionCoordinatorItemFromProgress(item = {}, record = {}, mapped = {}, options = {}) {
    const now = Number.parseInt(options.now, 10) || Date.now()
    const resetRetry = options.resetRetry === true
    const status = `${mapped.status || ''}`.trim()
    const mappedTerminal = isTerminalCoordinatorStatus(status)
    const projectedItem = buildProjectedCoordinatorItemFromProgress(item, record, mapped, {
        ...options,
        now
    })
    const reducerEventBase = {
        type: getCoordinatorProgressReducerEventType(item, mapped, options),
        status: mapped.status,
        outcome: mapped.outcome || '',
        error: mapped.error || '',
        at: now,
        terminalAt: mappedTerminal
            ? getCoordinatorTransitionTerminalAt(item, record, now, options)
            : 0,
        tabId: getPersistedQueuedTabId(item, record) || null,
        attemptId: getAttemptIdFromValue(record) || getAttemptIdFromValue(item),
        attemptNumber: getAttemptNumberFromValue(record) || getAttemptNumberFromValue(item),
        retryCount: resetRetry
            ? Number.parseInt(record.retryAttempt, 10) || item.retryCount || 0
            : item.retryCount || 0,
        lastRetryAt: resetRetry ? now : item.lastRetryAt || 0,
        reason: mappedTerminal ? 'terminal-progress' : '',
        milestones: getCoordinatorMilestonesFromProgress(record)
    }
    let reducerItem = item

    if(resetRetry && isTerminalCoordinatorStatus(item.status) && mapped.status !== 'queued') {
        const retryResult = reduceJobEvent(item, {
            ...reducerEventBase,
            type: JOB_EVENT_RETRY,
            status: 'queued',
            outcome: '',
            error: '',
            terminalAt: 0,
            reason: '',
            retryCount: item.retryCount || 0
        })
        if(!retryResult.accepted) return projectedItem
        reducerItem = retryResult.item
    }

    const reduced = reduceJobEvent(reducerItem, reducerEventBase)
    if(!reduced.accepted) {
        const previousTabId = normalizeTabId(item?.tabId || item?.activeTabId || null)
        const nextTabId = normalizeTabId(projectedItem?.tabId || projectedItem?.activeTabId || null)
        if(!resetRetry &&
            !mappedTerminal &&
            status === 'active' &&
            previousTabId &&
            nextTabId &&
            previousTabId !== nextTabId &&
            !hasMismatchedCoordinatorAttempt(item, record)) {
            return projectedItem
        }
        if(shouldPreferSuccessfulProgressOverTerminalCoordinatorItem(item, record, mapped)) {
            return promoteTerminalCoordinatorItemFromSuccessfulProgress(item, record, mapped, {
                ...options,
                now
            })
        }
        if(mappedTerminal) {
            return projectedItem
        }
        return resetRetry ? projectedItem : item
    }

    return mergeReducedCoordinatorProgressItem(item, reduced.item, projectedItem, mapped, record, {
        ...options,
        now
    })
}

function shouldPersistCoordinatorRowEventQueueItemChange(item = {}, nextItem = {}, mapped = {}) {
    if(!nextItem || nextItem === item) return false
    if(isTerminalCoordinatorStatus(mapped?.status) || isTerminalCoordinatorStatus(nextItem?.status)) return true

    const previousStatus = `${item?.status || ''}`.trim()
    const nextStatus = `${nextItem?.status || ''}`.trim()
    if(previousStatus !== nextStatus) return true

    if(normalizeTabId(item?.tabId || item?.activeTabId || null) !== normalizeTabId(nextItem?.tabId || nextItem?.activeTabId || null)) {
        return true
    }
    if(getAttemptIdFromValue(item) !== getAttemptIdFromValue(nextItem)) return true
    if(getAttemptNumberFromValue(item) !== getAttemptNumberFromValue(nextItem)) return true

    const durableFields = [
        'activeAt',
        'terminalAt',
        'actionLease',
        'actionLeaseReleasedAt',
        'actionLeaseReleaseReason',
        'outcome',
        'error'
    ]
    return durableFields.some(field => JSON.stringify(item?.[field] ?? null) !== JSON.stringify(nextItem?.[field] ?? null))
}

function makeTerminalProgressRecordFromCoordinatorItem(href = '', item = {}, previous = {}, reason = '', options = {}) {
    const previousRecord = previous && typeof previous === 'object' ? previous : {}
    const normalizedHref = normalizeQuoraProfileUrl(href || item?.targetProfileHref || previousRecord.profileHref || '')
    if(!normalizedHref || !isTerminalCoordinatorStatus(item?.status)) return null

    const actionKind = item.actionKind || previousRecord.actionKind || 'mute-block'
    const outcome = `${item.outcome || ''}`.trim()
    const patch = {
        actionKind,
        attemptId: getAttemptIdFromValue(item) || getAttemptIdFromValue(previousRecord),
        attemptNumber: getAttemptNumberFromValue(item) || getAttemptNumberFromValue(previousRecord),
        runId: item.runId || previousRecord.runId || '',
        tabId: getPersistedQueuedTabId(item, previousRecord) || null,
        terminalAt: Number.parseInt(item.terminalAt || previousRecord.terminalAt, 10) || Date.now(),
        finalError: item.error || previousRecord.finalError || '',
        event: reason || 'Restored terminal profile progress from coordinator row',
        replaceProgressRecord: options.replaceProgressRecord === true
    }

    if(item.status === 'succeeded' && actionKind === UNBLOCK_UNMUTE_ACTION_KIND) {
        Object.assign(patch, {
            status: outcome === 'already-unblocked' ? 'already-unblocked' : 'unblocked',
            unblockSucceeded: true,
            unblockedAt: Number.parseInt(item.terminalAt || previousRecord.unblockedAt, 10) || Date.now(),
            finalError: ''
        })
    }
    else if(item.status === 'succeeded') {
        Object.assign(patch, {
            status: outcome === 'blocked' ? 'blocked' : 'already-blocked',
            blockSucceeded: true,
            foundBlockedBeforeQueue: outcome !== 'blocked',
            blockedAt: Number.parseInt(item.terminalAt || previousRecord.blockedAt, 10) || Date.now(),
            finalError: ''
        })
    }
    else if(item.status === 'skipped') {
        Object.assign(patch, {
            status: 'profile-unavailable',
            unavailableReason: item.error || previousRecord.unavailableReason || 'Profile unavailable',
            lastUrl: previousRecord.lastUrl || '',
            resolvedProfileHref: previousRecord.resolvedProfileHref || '',
            remappedFromRequested: previousRecord.remappedFromRequested === true
        })
    }
    else {
        Object.assign(patch, {
            status: outcome === 'error-page' ? 'error-page' : 'interrupted',
            finalError: item.error || previousRecord.finalError || 'Coordinator job reached terminal failure'
        })
    }

    return normalizeProgressPatch(normalizedHref, patch, previousRecord)
}

function hasTerminalProgressDriftFromCoordinatorItem(item = null, record = null) {
    if(!item || !record || !isTerminalCoordinatorStatus(item?.status)) return false

    const actionKind = item.actionKind || record.actionKind || 'mute-block'
    const outcome = `${item.outcome || ''}`.trim()
    const recordStatus = `${record.status || ''}`.trim()
    const expectedError = item.status === 'succeeded' ? '' : `${item.error || ''}`.trim()
    const recordError = `${record.finalError || ''}`.trim()

    if(actionKind !== (record.actionKind || actionKind)) return true
    if(getAttemptIdFromValue(item) && getAttemptIdFromValue(record) && getAttemptIdFromValue(item) !== getAttemptIdFromValue(record)) return false

    if(item.status === 'succeeded' && actionKind === UNBLOCK_UNMUTE_ACTION_KIND) {
        const expectedStatus = outcome === 'already-unblocked' ? 'already-unblocked' : 'unblocked'
        return recordStatus !== expectedStatus ||
            record.unblockSucceeded !== true ||
            !!recordError
    }

    if(item.status === 'succeeded') {
        const expectedStatus = outcome === 'blocked' ? 'blocked' : 'already-blocked'
        return recordStatus !== expectedStatus ||
            record.blockSucceeded !== true ||
            !!recordError
    }

    if(item.status === 'skipped') {
        return recordStatus !== 'profile-unavailable'
    }

    const expectedStatus = outcome === 'error-page' ? 'error-page' : 'interrupted'
    return recordStatus !== expectedStatus ||
        (expectedError && recordError !== expectedError)
}

function shouldRestoreTerminalProgressFromCoordinatorItem(item = null, record = null) {
    if(!item || !isTerminalCoordinatorStatus(item?.status)) return false
    if(!record) return true

    const mapped = getCoordinatorStatusFromProgress(record)
    if(shouldPreferSuccessfulProgressOverTerminalCoordinatorItem(item, record, mapped)) return false
    if(!isTerminalCoordinatorStatus(mapped.status)) return true

    return mapped.status !== item.status || hasTerminalProgressDriftFromCoordinatorItem(item, record)
}

function shouldPreferSuccessfulProgressOverTerminalCoordinatorItem(item = null, record = null, mapped = null) {
    const itemStatus = `${item?.status || ''}`.trim()
    if(!item || !record || !isTerminalCoordinatorStatus(itemStatus) || itemStatus === 'succeeded') return false
    const itemOutcome = `${item.outcome || ''}`.trim()
    if(itemStatus === 'skipped' && (
        itemOutcome === 'profile-redirect-mismatch' ||
        itemOutcome === 'non-profile-target'
    )) {
        return false
    }

    const effectiveMapped = mapped || getCoordinatorStatusFromProgress(record)
    if(effectiveMapped.status !== 'succeeded') return false
    if(!isSuccessfulProfileNukeRecord(record)) return false
    if(!shouldApplyProgressToCoordinatorItem(item, record)) return false
    if(hasMismatchedCoordinatorAttempt(item, record)) return false

    return true
}

function isRedundantTerminalProgressForCoordinatorItem(item = null, record = null, mapped = null) {
    const itemStatus = `${item?.status || ''}`.trim()
    if(!item || !record || !isTerminalCoordinatorStatus(itemStatus)) return false

    const effectiveMapped = mapped || getCoordinatorStatusFromProgress(record)
    if(!isTerminalCoordinatorStatus(effectiveMapped.status)) return false
    if(effectiveMapped.status !== itemStatus) return false
    if(shouldPreferSuccessfulProgressOverTerminalCoordinatorItem(item, record, effectiveMapped)) return false
    if(hasMismatchedCoordinatorAttempt(item, record)) return false

    const mappedOutcome = `${effectiveMapped.outcome || ''}`.trim()
    const mappedError = `${effectiveMapped.error || ''}`.trim()
    const itemOutcome = `${item.outcome || ''}`.trim()
    const itemError = `${item.error || ''}`.trim()
    if(mappedOutcome !== itemOutcome) return false
    if(mappedError !== itemError) return false

    return true
}

function promoteTerminalCoordinatorItemFromSuccessfulProgress(item = {}, record = {}, mapped = {}, options = {}) {
    const now = Number.parseInt(options.now, 10) || Date.now()
    const terminalAt = getCoordinatorTransitionTerminalAt(item, record, now, options)
    const nextItem = buildProjectedCoordinatorItemFromProgress(item, record, mapped, {
        ...options,
        now
    })

    return {
        ...nextItem,
        status: 'succeeded',
        outcome: mapped.outcome || nextItem.outcome || 'blocked',
        error: '',
        updatedAt: Math.max(Number.parseInt(nextItem.updatedAt, 10) || 0, now),
        terminalAt,
        tabId: null,
        actionLease: null,
        actionLeaseReleasedAt: now,
        actionLeaseReleaseReason: 'terminal-success-reconcile',
        milestones: {
            ...makeEmptyCoordinatorMilestones(),
            ...(item.milestones || {}),
            ...getCoordinatorMilestonesFromProgress(record),
            tabClosedAt: Number.parseInt(record.tabClosedAt || record.terminalAt, 10) ||
                Number.parseInt(item?.milestones?.tabClosedAt, 10) ||
                terminalAt
        }
    }
}

function cloneCoordinatorAuthorityValue(value) {
    if(value === null || typeof value !== 'object') return value
    if(Array.isArray(value)) {
        const cloned = new Array(value.length)
        for(let index = 0; index < value.length; index += 1) {
            cloned[index] = cloneCoordinatorAuthorityValue(value[index])
        }
        return cloned
    }
    const cloned = {}
    for(const key in value) {
        if(Object.prototype.hasOwnProperty.call(value, key)) {
            cloned[key] = cloneCoordinatorAuthorityValue(value[key])
        }
    }
    return cloned
}

function makeCoordinatorAuthorityProjection(state = {}) {
    return {
        stored: cloneCoordinatorAuthorityValue(state.stored || {}),
        queue: normalizeCoordinatorMap(cloneCoordinatorAuthorityValue(state.queue || {})),
        runs: normalizeCoordinatorMap(cloneCoordinatorAuthorityValue(state.runs || {})),
        events: normalizeCoordinatorEvents(cloneCoordinatorAuthorityValue(state.events || [])),
        progress: normalizeStoredProfileNukeProgress(cloneCoordinatorAuthorityValue(state.progress || {}))
    }
}

function closeRuntimeTabsReclaimedByAuthority(queue = {}, reason = 'authority-runtime-reclaimed') {
    let closed = 0
    for(const tabId of queueRuntime.listActiveQueuedTabIds()) {
        const metadata = getQueuedTabMetadata(tabId)
        if(!metadata) continue
        const href = normalizeQuoraProfileUrl(metadata.profileHref || metadata.targetProfileHref || '')
        const coordinatorKey = metadata.coordinatorKey || href || normalizeCoordinatorRequestedUrl(metadata.requestedUrl || '')
        const item = coordinatorKey && queue?.[coordinatorKey]
            ? queue[coordinatorKey]
            : href
            ? queue?.[href] || null
            : null
        if(!item || !isActiveCoordinatorStatus(item.status)) continue
        const itemTabId = normalizeTabId(item.tabId || item.activeTabId || null)
        if(!itemTabId || itemTabId !== normalizeTabId(tabId)) continue
        const metadataAttemptId = getAttemptIdFromValue(metadata)
        const metadataAttemptNumber = getAttemptNumberFromValue(metadata)
        const itemAttemptId = getAttemptIdFromValue(item)
        const itemAttemptNumber = getAttemptNumberFromValue(item)
        if(!((metadataAttemptId && itemAttemptId && metadataAttemptId !== itemAttemptId) ||
            (metadataAttemptNumber && itemAttemptNumber && metadataAttemptNumber !== itemAttemptNumber))) {
            continue
        }
        markQueuedTabClosing(tabId, reason)
        const detached = detachQueuedTabRuntimeState(tabId, reason)
        try {
            void browser.tabs.remove(tabId).catch(() => null)
        }
        catch {}
        void releaseQueuedTab(tabId, {
            runtimeDetached: true,
            metadata: detached.metadata,
            wasActive: detached.wasActive,
            foregroundLeaseReleased: detached.foregroundLeaseReleased
        })
        closed += 1
    }
    if(closed > 0) {
        incrementQueueWakeupMetric('coordinatorAuthority.reclaimedRuntimeClosed', closed)
    }
    return closed
}

function normalizeCoordinatorAuthorityRowKey(value = '') {
    const raw = `${value || ''}`.trim()
    if(!raw) return ''
    return normalizeQuoraProfileUrl(raw) || raw
}

function makeCoordinatorAuthorityPersistenceResult(overrides = {}) {
    return {
        backend: 'snapshot',
        saved: false,
        storageTimedOut: false,
        fallbackReturned: false,
        ...overrides
    }
}

function makeCoordinatorAuthorityApplyResult(operation = {}, overrides = {}) {
    const operationKind = normalizeQueueWriteOperationName(operation.operationKind || operation.kind || 'unclassified')
    const rowKey = normalizeCoordinatorAuthorityRowKey(operation.rowKey || operation.coordinatorKey || operation.profileHref || '')
    const accepted = overrides.accepted === true
    const changed = overrides.changed === true
    const durable = overrides.durable === true
    const reason = `${overrides.reason || operation.reason || ''}`.trim() || 'unclassified'
    const previousRow = cloneCoordinatorAuthorityValue(overrides.previousRow || null)
    const nextRow = cloneCoordinatorAuthorityValue(overrides.nextRow || null)
    const staleAttempt = overrides.staleAttempt === true
    const terminal = overrides.terminal === true
    const operationRecord = {
        operationKind,
        rowKey,
        reason,
        accepted,
        changed,
        durable,
        previousRow,
        nextRow,
        staleAttempt,
        terminal
    }

    return {
        operationKind,
        rowKey,
        reason,
        accepted,
        changed,
        durable,
        previousRow,
        nextRow,
        staleAttempt,
        terminal,
        operation: operationRecord,
        allowTerminalOverwrite: overrides.allowTerminalOverwrite === true || operation.allowTerminalOverwrite === true,
        allowActiveTransitionAfterRollback: overrides.allowActiveTransitionAfterRollback === true || operation.allowActiveTransitionAfterRollback === true,
        persistence: makeCoordinatorAuthorityPersistenceResult(overrides.persistence || {})
    }
}

function makeCoordinatorProgressOperationRecord(operation = {}, overrides = {}) {
    const operationKind = getCoordinatorRowEventMetricKind(
        operation.operationKind || operation.eventKind || COORDINATOR_ROW_EVENT_QUEUED_PROGRESS_MILESTONE
    )
    const rowKey = normalizeCoordinatorAuthorityRowKey(operation.rowKey || operation.profileHref || operation.href || '')
    const accepted = overrides.accepted === true
    const changed = overrides.changed === true
    const durable = overrides.durable === true
    const reason = `${overrides.reason || operation.reason || ''}`.trim() || 'unclassified'
    const previousRecord = cloneCoordinatorAuthorityValue(overrides.previousRecord || null)
    const nextRecord = cloneCoordinatorAuthorityValue(overrides.nextRecord || null)
    const staleAttempt = overrides.staleAttempt === true
    const terminal = overrides.terminal === true || isTerminalProfileNukeRecord(nextRecord)

    return {
        operationKind,
        area: 'progress',
        rowKey,
        reason,
        accepted,
        changed,
        durable,
        previousRecord,
        nextRecord,
        staleAttempt,
        terminal
    }
}

function makeCoordinatorAuthorityShadowWalRecord(result = {}) {
    if(!result?.accepted || !result?.changed || !result?.rowKey || !result?.nextRow) return null

    const nextRow = cloneCoordinatorAuthorityValue(result.nextRow)
    const attemptId = getAttemptIdFromValue(nextRow)
    const attemptNumber = getAttemptNumberFromValue(nextRow)
    const runId = `${nextRow?.runId || ''}`.trim()
    const status = `${nextRow?.status || ''}`.trim()
    const at = Number.parseInt(nextRow?.updatedAt || nextRow?.terminalAt, 10) || Date.now()

    return {
        kind: 'map.set',
        area: 'queue',
        key: result.rowKey,
        dedupeKey: [
            'queue',
            result.operationKind || 'authority-row-mutation',
            result.rowKey,
            attemptId,
            attemptNumber || '',
            status
        ].filter(value => value !== '').join(':'),
        operationKind: result.operationKind || 'authority-row-mutation',
        reason: result.reason || '',
        value: nextRow,
        runId,
        attemptId,
        attemptNumber,
        status,
        terminal: result.terminal === true || isTerminalCoordinatorStatus(nextRow?.status),
        allowTerminalOverwrite: result.allowTerminalOverwrite === true,
        allowActiveTransitionAfterRollback: result.allowActiveTransitionAfterRollback === true,
        at,
        seq: 1
    }
}

async function loadCoordinatorQueueWalStoreFromStorage(stored = {}, snapshotQueue = {}, options = {}) {
    const meta = stored?.[COORDINATOR_QUEUE_WAL_META_KEY] || null
    if(isSegmentedWalStorageMeta(meta)) {
        const residentStore = stored?.[COORDINATOR_QUEUE_WAL_KEY] || null
        if(canUseResidentCoordinatorQueueWalStoreForMeta(residentStore, meta)) {
            incrementQueueWakeupMetric('coordinatorAuthority.queueWal.residentStoreUsed')
            return residentStore
        }
        const defaults = buildSegmentedWalStorageDefaults(meta, {baseKey: COORDINATOR_QUEUE_WAL_KEY})
        const missingKeys = Object.keys(defaults).filter(key => !Object.prototype.hasOwnProperty.call(stored, key))
        let segmentStored = {}
        if(missingKeys.length) {
            segmentStored = await metricStorageGet(Object.fromEntries(missingKeys.map(key => [key, defaults[key]])), {
                metricPath: options.metricPath || 'coordinatorQueueWal.segmented.load',
                phase: 'queueWalSegmentStorageGet'
            })
            Object.assign(stored, segmentStored)
        }
        const hydrated = runQueueWakeupMetricPhase('queueWalHydrate', () => hydrateSegmentedWalStore(stored, {
            baseKey: COORDINATOR_QUEUE_WAL_KEY,
            fallbackStore: stored[COORDINATOR_QUEUE_WAL_KEY] || null
        }))
        if(hydrated?.ok === true && hydrated.store) {
            incrementQueueWakeupMetric('coordinatorAuthority.queueWal.segmentedHydrated')
            const activeSegmentCount = getSegmentedWalCommittedSegmentCount(
                meta,
                hydrated.store?.meta?.activeCheckpoint || ''
            )
            recordQueueWakeupMetricMax('coordinatorAuthority.queueWal.maxActivePhysicalSegments', activeSegmentCount)
            if(options.suppressCheckpointSwitchSchedule !== true &&
                activeSegmentCount >= COORDINATOR_QUEUE_WAL_SEGMENT_SOFT_SWITCH_AT) {
                incrementQueueWakeupMetric('coordinatorAuthority.queueWal.segmentSoftSwitchScheduledFromRead')
                scheduleCoordinatorQueueWalCheckpointSwitch('segmentSoftRead')
            }
            stored[COORDINATOR_QUEUE_WAL_KEY] = hydrated.store
            return hydrated.store
        }
        if(hydrated?.reason === 'missing-checkpoint' &&
            !Object.keys(normalizeCoordinatorMap(snapshotQueue || {})).length) {
            incrementQueueWakeupMetric('coordinatorAuthority.queueWal.segmentedMissingCheckpointReset')
            const fresh = makeCoordinatorQueueWalCheckpoint({})
            stored[COORDINATOR_QUEUE_WAL_KEY] = fresh
            return fresh
        }
        incrementQueueWakeupMetric('coordinatorAuthority.queueWal.segmentedHydrateFailed')
        recordCoordinatorDiagnosticEvent(
            'coordinator-authority-queue-wal-segmented-hydrate-failed',
            hydrated?.reason || 'Coordinator authority queue WAL segmented hydrate failed'
        )
        throw new Error(`segmented queue WAL hydrate failed: ${hydrated?.reason || 'hydrate-failed'}`)
    }

    if(!Object.prototype.hasOwnProperty.call(stored || {}, COORDINATOR_QUEUE_WAL_KEY)) {
        const monolithFallbackStored = await metricStorageGet({[COORDINATOR_QUEUE_WAL_KEY]: null}, {
            metricPath: options.metricPath
                ? `${options.metricPath}.monolithFallback`
                : 'coordinatorQueueWal.monolithFallback.load'
        })
        stored[COORDINATOR_QUEUE_WAL_KEY] = monolithFallbackStored?.[COORDINATOR_QUEUE_WAL_KEY] || null
    }

    const fallback = normalizeCoordinatorQueueWalStore(stored[COORDINATOR_QUEUE_WAL_KEY], snapshotQueue)
    stored[COORDINATOR_QUEUE_WAL_KEY] = fallback
    return fallback
}

function scheduleCoordinatorQueueWalCheckpointSwitch(reason = 'segment-soft-threshold') {
    const normalizedReason = `${reason || 'segment-soft-threshold'}`.trim() || 'segment-soft-threshold'
    const softMaintenance = !/hard/i.test(normalizedReason)
    if(softMaintenance) {
        const residentCounts = getCoordinatorQueueWorkCounts(coordinatorAuthority.current()?.queue || {})
        const runtimeCounts = queueRuntime.getRuntimeCounts()
        const runtimeHasWork = runtimeCounts.activeQueuedTabs > 0 ||
            runtimeCounts.queuedTabActions > 0 ||
            runtimeCounts.pendingTabActions > 0
        const durableHasWork = residentCounts.durableActiveRows > 0 || residentCounts.durableQueuedRows > 0
        if(runtimeHasWork || durableHasWork) {
            incrementQueueWakeupMetric('coordinatorAuthority.queueWal.segmentCheckpointSwitchDeferredForQueueWork')
            if(!coordinatorQueueWalCheckpointSwitchTimeout) {
                coordinatorQueueWalCheckpointSwitchTimeout = setTimeout(() => {
                    coordinatorQueueWalCheckpointSwitchTimeout = null
                    scheduleCoordinatorQueueWalCheckpointSwitch(`${normalizedReason}-deferred`)
                }, 5000)
            }
            return coordinatorQueueWalCheckpointSwitchPromise || Promise.resolve({
                checkpointSwitched: false,
                saved: false,
                durable: false,
                reason: 'checkpoint-switch-deferred-for-queue-work'
            })
        }
    }
    if(coordinatorQueueWalCheckpointSwitchPromise) {
        incrementQueueWakeupMetric('coordinatorAuthority.queueWal.segmentCheckpointSwitchCoalesced')
        return coordinatorQueueWalCheckpointSwitchPromise
    }
    incrementQueueWakeupMetric('coordinatorAuthority.queueWal.segmentCheckpointSwitchScheduled')
    coordinatorQueueWalCheckpointSwitchPromise = switchCoordinatorAuthorityQueueWalCheckpoint({
        metricPath: `queueWal.${reason}.load`,
        saveMetricPath: `queueWal.${reason}.save`,
        timeoutMs: COORDINATOR_QUEUE_WAL_CHECKPOINT_SWITCH_TIMEOUT_MS,
        suppressCheckpointSwitchSchedule: true
    }).finally(() => {
        coordinatorQueueWalCheckpointSwitchPromise = null
    })
    void coordinatorQueueWalCheckpointSwitchPromise
    return coordinatorQueueWalCheckpointSwitchPromise
}

async function cleanupRetiredCoordinatorQueueWalPhysicalKeys(previousMeta = null, nextMeta = null, options = {}) {
    const retiredKeys = getRetiredCoordinatorQueueWalPhysicalKeys(previousMeta, nextMeta)
    if(!retiredKeys.length) {
        return {
            removed: false,
            keyCount: 0,
            keys: []
        }
    }

    try {
        const removed = await metricStorageRemove(retiredKeys, {
            metricPath: options.metricPath || 'queueWal.physicalCleanup.remove'
        })
        if(removed === false) {
            incrementQueueWakeupMetric('coordinatorAuthority.queueWal.physicalCleanupSuppressed')
            return {
                removed: false,
                keyCount: retiredKeys.length,
                keys: retiredKeys,
                reason: 'storage-remove-suppressed'
            }
        }
        incrementQueueWakeupMetric('coordinatorAuthority.queueWal.physicalCleanupRemoved')
        incrementQueueWakeupMetric('coordinatorAuthority.queueWal.physicalCleanupRemovedKeys', retiredKeys.length)
        recordQueueWakeupMetricMax('coordinatorAuthority.queueWal.maxPhysicalCleanupKeys', retiredKeys.length)
        return {
            removed: true,
            keyCount: retiredKeys.length,
            keys: retiredKeys
        }
    }
    catch(error) {
        incrementQueueWakeupMetric('coordinatorAuthority.queueWal.physicalCleanupFailed')
        recordCoordinatorDiagnosticEvent(
            'coordinator-authority-queue-wal-physical-cleanup-failed',
            error?.message || 'Coordinator authority queue WAL physical cleanup failed'
        )
        return {
            removed: false,
            keyCount: retiredKeys.length,
            keys: retiredKeys,
            reason: 'storage-remove-failed',
            error: `${error?.message || error || 'storage error'}`.slice(0, 240)
        }
    }
}

async function cleanupPreSegmentedCoordinatorQueueWalMonolithBeforeCheckpoint(previousMeta = null, options = {}) {
    if(!isSegmentedWalStorageMeta(previousMeta)) {
        return {
            removed: false,
            keyCount: 0,
            keys: []
        }
    }

    try {
        const removed = await metricStorageRemove(COORDINATOR_QUEUE_WAL_KEY, {
            metricPath: options.metricPath || 'queueWal.checkpointSwitch.preSegmentedWalMonolith.remove'
        })
        if(removed === false) {
            incrementQueueWakeupMetric('coordinatorAuthority.queueWal.preSegmentedWalMonolithCleanupSuppressed')
            return {
                removed: false,
                keyCount: 1,
                keys: [COORDINATOR_QUEUE_WAL_KEY],
                reason: 'storage-remove-suppressed'
            }
        }
        incrementQueueWakeupMetric('coordinatorAuthority.queueWal.preSegmentedWalMonolithRemovedBeforeCheckpoint')
        return {
            removed: true,
            keyCount: 1,
            keys: [COORDINATOR_QUEUE_WAL_KEY]
        }
    }
    catch(error) {
        incrementQueueWakeupMetric('coordinatorAuthority.queueWal.preSegmentedWalMonolithCleanupFailed')
        recordCoordinatorDiagnosticEvent(
            'coordinator-authority-queue-wal-pre-segmented-monolith-cleanup-failed',
            error?.message || 'Coordinator authority queue WAL pre-segmented monolith cleanup failed'
        )
        return {
            removed: false,
            keyCount: 1,
            keys: [COORDINATOR_QUEUE_WAL_KEY],
            reason: 'storage-remove-failed',
            error: `${error?.message || error || 'storage error'}`.slice(0, 240)
        }
    }
}

function recoverCoordinatorQueueFromWal(snapshotQueue = {}, walStore = null, options = {}) {
    const normalizedSnapshot = normalizeCoordinatorMap(cloneCoordinatorAuthorityValue(snapshotQueue || {}))
    if(!walStore || typeof walStore !== 'object') {
        return {
            queue: normalizedSnapshot,
            recovered: false,
            reason: 'missing-wal'
        }
    }

    try {
        const recovered = recoverProjectedState(walStore)
        const generationId = recovered?.generationId || walStore?.meta?.activeCheckpoint
        const records = getWalRecordsForGeneration(walStore, generationId)
        const replayBytes = getJsonByteSize(records)
        const appliedCount = recovered?.projected?.applied?.length || 0
        const ignored = recovered?.projected?.ignored || []
        const ignoredCheckpointCount = ignored.filter(entry => entry?.reason === 'already-in-snapshot').length
        const checkpointCreatedAt = Number.parseInt(recovered?.checkpoint?.createdAt, 10) || 0
        if(records.length) {
            incrementQueueWakeupMetric('coordinatorAuthority.queueWal.replayRecords', records.length)
            incrementQueueWakeupMetric('coordinatorAuthority.queueWal.replayBytes', replayBytes)
            recordQueueWakeupMetricMax('coordinatorAuthority.queueWal.maxReplayRecords', records.length)
            recordQueueWakeupMetricMax('coordinatorAuthority.queueWal.maxReplayBytes', replayBytes)
        }
        if(appliedCount) incrementQueueWakeupMetric('coordinatorAuthority.queueWal.replayApplied', appliedCount)
        if(ignored.length) incrementQueueWakeupMetric('coordinatorAuthority.queueWal.replayIgnored', ignored.length)
        if(ignoredCheckpointCount) {
            incrementQueueWakeupMetric('coordinatorAuthority.queueWal.replayIgnoredCheckpoint', ignoredCheckpointCount)
        }
        if(checkpointCreatedAt) {
            recordQueueWakeupMetricMax('coordinatorAuthority.queueWal.maxCheckpointAgeMs', Math.max(0, Date.now() - checkpointCreatedAt))
        }
        recordQueueWakeupMetricMax('coordinatorAuthority.queueWal.maxTailLength', records.length)
        const queue = normalizeCoordinatorMap(recovered?.projected?.state?.queue || recovered?.state?.queue || {})
        if(recovered?.recovered === true) {
            incrementQueueWakeupMetric('coordinatorAuthority.queueWal.recovered')
            return {
                queue,
                recovered: true,
                reason: '',
                wal: recovered
            }
        }
        incrementQueueWakeupMetric('coordinatorAuthority.queueWal.recoveryFailed')
        recordCoordinatorDiagnosticEvent(
            'coordinator-authority-queue-wal-recovery-failed',
            recovered?.reason || 'Coordinator authority queue WAL recovery failed'
        )
        return {
            queue: normalizedSnapshot,
            recovered: false,
            reason: recovered?.reason || 'recovery-failed',
            wal: recovered
        }
    }
    catch(error) {
        incrementQueueWakeupMetric('coordinatorAuthority.queueWal.recoveryFailed')
        recordCoordinatorDiagnosticEvent(
            'coordinator-authority-queue-wal-recovery-failed',
            error?.message || 'Coordinator authority queue WAL recovery threw'
        )
        return {
            queue: normalizedSnapshot,
            recovered: false,
            reason: 'recovery-error',
            error: `${error?.message || error || 'recovery error'}`.slice(0, 240)
        }
    }
}

async function persistCoordinatorAuthorityQueueWalMutation(result = {}, nextProjection = {}, options = {}) {
    const record = makeCoordinatorAuthorityShadowWalRecord({
        ...result,
        durable: true
    })
    if(!record) {
        return {
            saved: false,
            backend: 'queue-wal',
            reason: 'not-row-mutation'
        }
    }

    const storedWal = normalizeCoordinatorQueueWalStore(
        nextProjection?.stored?.[COORDINATOR_QUEUE_WAL_KEY],
        result.previousProjectionQueue || {}
    )
    const previousWalMeta = nextProjection?.stored?.[COORDINATOR_QUEUE_WAL_META_KEY] || null
    const appendRecord = cloneCoordinatorAuthorityValue(record)
    delete appendRecord.id
    delete appendRecord.seq
    const append = runQueueWakeupMetricPhase('queueWalAppendPrepare', () => appendWalRecordsToGeneration(storedWal, [appendRecord], {
        segmentId: `queue-authority-${record.operationKind || 'row-mutation'}-${Date.now()}`
    }))
    if(append?.rejected) {
        incrementQueueWakeupMetric('coordinatorAuthority.queueWal.appendRejected')
        recordCoordinatorDiagnosticEvent(
            'coordinator-authority-queue-wal-append-rejected',
            append.reason || 'Coordinator authority queue WAL append was rejected'
        )
        return {
            saved: false,
            backend: 'queue-wal',
            reason: append.reason || 'append-rejected'
        }
    }

    const physicalWal = runQueueWakeupMetricPhase('queueWalPhysicalPayload', () => getCoordinatorQueueWalPhysicalPayload(append.store, {
        previousMeta: previousWalMeta,
        previousStored: nextProjection?.stored || {}
    }))
    if((physicalWal.hardLimitCommittedSegments || physicalWal.previousCommitted || 0) >= physicalWal.hardLimit) {
        recordCoordinatorQueueWalPhysicalPayloadMetrics({
            previousCommitted: physicalWal.hardLimitCommittedSegments || physicalWal.previousCommitted || 0,
            committedSegments: physicalWal.committedSegments
        })
        incrementQueueWakeupMetric('coordinatorAuthority.queueWal.segmentHardBlocked')
        scheduleCoordinatorQueueWalCheckpointSwitch('segmentHardLimit')
        scheduleCoordinatorReconcile(1000, {
            reason: 'queue-wal-segment-hard-limit',
            edgeTriggered: true
        })
        return {
            saved: false,
            backend: 'queue-wal',
            reason: 'queue-wal-segment-hard-limit',
            append
        }
    }

    recordCoordinatorQueueWalPhysicalPayloadMetrics(physicalWal)
    const walPayload = options.includeProjectionInWalSave === true
        ? {
            ...physicalWal.payload,
            ...(options.projectionPayload === 'queueViewOnly'
                ? {[COORDINATOR_QUEUE_VIEW_KEY]: buildCoordinatorQueueView(nextProjection.queue || {})}
                : buildCoordinatorQueueDerivedProjectionPayload(nextProjection.queue || {}))
        }
        : physicalWal.payload
    const walSaved = await metricStorageSet(walPayload, {
        metricPath: options.metricPath || `authority.${result.operationKind || 'row-mutation'}.queueWal.save`,
        phase: 'queueWalStorageSet',
        queueOperation: result.operationKind || 'authority-row-mutation',
        queueChangedRows: 1,
        coordinatorAuthorityWrite: true
    })
    if(walSaved === false) {
        incrementQueueWakeupMetric('coordinatorAuthority.queueWal.appendSuppressed')
        return {
            saved: false,
            backend: 'queue-wal',
            reason: 'wal-storage-suppressed',
            append
        }
    }

    incrementQueueWakeupMetric('coordinatorAuthority.queueWal.appended')
    incrementQueueWakeupMetric('coordinatorAuthority.queueWal.appendBytes', getJsonByteSize(append.records || []))
    incrementQueueWakeupMetric('coordinatorAuthority.queueWal.segmentWrites', Object.keys(physicalWal.payload || {}).length)
    recordQueueWakeupMetricMax('coordinatorAuthority.queueWal.maxAppendBytes', getJsonByteSize(append.records || []))
    recordQueueWakeupMetricMax('coordinatorAuthority.queueWal.maxCommittedSegments', physicalWal.committedSegments)
    if(physicalWal.committedSegments >= physicalWal.softSwitchAt) {
        incrementQueueWakeupMetric('coordinatorAuthority.queueWal.segmentSoftSwitchScheduled')
        scheduleCoordinatorQueueWalCheckpointSwitch('segmentSoftSwitch')
    }

    const projectionMetricPath = options.projectionMetricPath || `authority.${result.operationKind || 'row-mutation'}.projection.save`
    const projectionQueueOperation = `${result.operationKind || 'authority-row-mutation'}-projection`
    const recoveredAfterAppend = runQueueWakeupMetricPhase('queueWalReplayVerify', () => recoverProjectedState(append.store))
    const appendedRecordIds = new Set((append.records || []).map(record => record.id).filter(Boolean))
    const ignoredAppendedRecords = (recoveredAfterAppend?.projected?.ignored || [])
        .filter(entry => appendedRecordIds.has(entry?.record?.id))
    if(recoveredAfterAppend?.recovered !== true || ignoredAppendedRecords.length) {
        incrementQueueWakeupMetric(ignoredAppendedRecords.length
            ? 'coordinatorAuthority.queueWal.appendIgnoredAfterReplay'
            : 'coordinatorAuthority.queueWal.appendRecoveryFailed')
        recordCoordinatorDiagnosticEvent(
            ignoredAppendedRecords.length
                ? 'coordinator-authority-queue-wal-append-ignored-after-replay'
                : 'coordinator-authority-queue-wal-append-recovery-failed',
            ignoredAppendedRecords[0]?.reason ||
                recoveredAfterAppend?.reason ||
                'Coordinator authority queue WAL append did not replay as durable authority'
        )
        scheduleCoordinatorReconcile(1000, {
            reason: ignoredAppendedRecords.length
                ? 'queue-wal-append-ignored-after-replay'
                : 'queue-wal-append-recovery-failed',
            edgeTriggered: true
        })
        return {
            saved: false,
            backend: 'queue-wal',
            reason: ignoredAppendedRecords[0]?.reason || recoveredAfterAppend?.reason || 'append-replay-failed',
            append,
            walSaved: true,
            replayIgnored: ignoredAppendedRecords
        }
    }
    const authoritativeProjectionQueue = recoveredAfterAppend?.recovered === true
        ? recoveredAfterAppend?.projected?.state?.queue || recoveredAfterAppend?.state?.queue || null
        : null
    if(!authoritativeProjectionQueue) {
        incrementQueueWakeupMetric('coordinatorAuthority.queueWal.projectionRecoveryFailed')
        recordCoordinatorDiagnosticEvent(
            'coordinator-authority-queue-wal-projection-recovery-failed',
            recoveredAfterAppend?.reason || 'Coordinator authority queue WAL projection recovery failed'
        )
    }
    const projectionQueueBase = authoritativeProjectionQueue || nextProjection.queue || {}
    let projectionSaved = true
    if(options.deferProjectionSave === true) {
        projectionSaved = 'deferred'
        incrementQueueWakeupMetric('coordinatorAuthority.queueWal.projectionDeferred')
        const projectionQueue = cloneCoordinatorAuthorityValue(projectionQueueBase)
        const reconcileDelayMs = Math.max(1000, Number.parseInt(options.projectionReconcileDelayMs, 10) || 30000)
        setTimeout(() => {
            void (async () => {
                let deferredSaved = true
                try {
                    const projectionPayload = runQueueWakeupMetricPhase('queueProjectionBuild', () => options.projectionPayload === 'queueViewOnly'
                        ? {[COORDINATOR_QUEUE_VIEW_KEY]: buildCoordinatorQueueView(projectionQueue)}
                        : buildCoordinatorQueueDerivedProjectionPayload(projectionQueue))
                    const saved = await metricStorageSet(projectionPayload, {
                        metricPath: projectionMetricPath,
                        phase: 'queueProjectionStorageSet',
                        queueOperation: projectionQueueOperation,
                        queueChangedRows: 1,
                        coordinatorAuthorityWrite: true
                    })
                    deferredSaved = saved !== false
                }
                catch(error) {
                    deferredSaved = false
                    recordCoordinatorDiagnosticEvent(
                        'coordinator-authority-queue-wal-projection-failed',
                        error?.message || 'Coordinator authority queue WAL projection update failed'
                    )
                }
                if(!deferredSaved) {
                    incrementQueueWakeupMetric('coordinatorAuthority.queueWal.projectionFailed')
                    scheduleCoordinatorReconcile(reconcileDelayMs, {
                        reason: 'queue-wal-projection-failed',
                        edgeTriggered: true
                    })
                }
                else {
                    incrementQueueWakeupMetric('coordinatorAuthority.queueWal.projectionSaved')
                }
            })()
        }, Math.max(0, Number.parseInt(options.projectionDeferDelayMs, 10) || 0))
    }
    else {
        try {
            const projectionPayload = runQueueWakeupMetricPhase('queueProjectionBuild', () => options.projectionPayload === 'queueViewOnly'
                ? {[COORDINATOR_QUEUE_VIEW_KEY]: buildCoordinatorQueueView(projectionQueueBase)}
                : buildCoordinatorQueueDerivedProjectionPayload(projectionQueueBase))
            const saved = await metricStorageSet(projectionPayload, {
                metricPath: projectionMetricPath,
                phase: 'queueProjectionStorageSet',
                queueOperation: projectionQueueOperation,
                queueChangedRows: 1,
                coordinatorAuthorityWrite: true
            })
            projectionSaved = saved !== false
        }
        catch(error) {
            projectionSaved = false
            recordCoordinatorDiagnosticEvent(
                'coordinator-authority-queue-wal-projection-failed',
                error?.message || 'Coordinator authority queue WAL projection update failed'
            )
        }
        if(!projectionSaved) {
            incrementQueueWakeupMetric('coordinatorAuthority.queueWal.projectionFailed')
            scheduleCoordinatorReconcile(1000, {
                reason: 'queue-wal-projection-failed',
                edgeTriggered: true
            })
        }
        else {
            incrementQueueWakeupMetric('coordinatorAuthority.queueWal.projectionSaved')
        }
    }

    recordFlightRecorderEvent({
        kind: 'authority-mutation',
        source: 'persistCoordinatorAuthorityQueueWalMutation',
        operationKind: record.operationKind || result.operationKind || '',
        rowKey: result.rowKey || record.key || '',
        targetUrl: getCoordinatorItemHref(result.nextRow || {}) || result.nextRow?.targetProfileHref || '',
        attemptId: record.attemptId || getAttemptIdFromValue(result.nextRow || {}),
        attemptNumber: record.attemptNumber || getAttemptNumberFromValue(result.nextRow || {}),
        runId: record.runId || result.nextRow?.runId || '',
        statusBefore: result.previousRow?.status || '',
        statusAfter: result.nextRow?.status || record.status || '',
        accepted: result.accepted === true,
        durable: true,
        changed: result.changed === true,
        reason: result.reason || record.reason || ''
    })

    return {
        saved: true,
        backend: 'queue-wal',
        append,
        physicalWal,
        authoritativeQueue: authoritativeProjectionQueue || null,
        projectionSaved,
        snapshotSaved: false,
        walSaved: true
    }
}

async function persistCoordinatorAuthorityQueueWalBatchMutation(results = [], nextProjection = {}, options = {}) {
    const operationKind = normalizeQueueWriteOperationName(options.operationKind || 'authority-row-batch-mutation')
    const setRecords = (Array.isArray(results) ? results : [])
        .map(result => makeCoordinatorAuthorityShadowWalRecord({
            ...result,
            operationKind: result.operationKind || operationKind,
            durable: true
        }))
        .filter(Boolean)
    const removeRecords = (Array.isArray(options.removedRows) ? options.removedRows : [])
        .map(removal => makeCoordinatorAuthorityQueueWalRemoveRecord({
            ...removal,
            operationKind: removal.operationKind || operationKind
        }, {
            operationKind,
            reason: options.reason || 'ordinaryMutation'
        }))
        .filter(Boolean)
    const records = [
        ...setRecords,
        ...removeRecords
    ]
    if(!records.length) {
        return {
            saved: false,
            backend: 'queue-wal',
            reason: 'not-row-mutation'
        }
    }

    const storedWal = normalizeCoordinatorQueueWalStore(
        nextProjection?.stored?.[COORDINATOR_QUEUE_WAL_KEY],
        options.previousProjectionQueue || {}
    )
    const previousWalMeta = nextProjection?.stored?.[COORDINATOR_QUEUE_WAL_META_KEY] || null
    const appendRecords = records.map(record => {
        const next = cloneCoordinatorAuthorityValue(record)
        delete next.id
        delete next.seq
        return next
    })
    const append = runQueueWakeupMetricPhase('queueWalAppendPrepare', () => appendWalRecordsToGeneration(storedWal, appendRecords, {
        segmentId: `queue-authority-${operationKind}-batch-${Date.now()}`
    }))
    if(append?.rejected) {
        incrementQueueWakeupMetric('coordinatorAuthority.queueWal.appendRejected')
        recordCoordinatorDiagnosticEvent(
            'coordinator-authority-queue-wal-batch-append-rejected',
            append.reason || 'Coordinator authority queue WAL batch append was rejected'
        )
        return {
            saved: false,
            backend: 'queue-wal',
            reason: append.reason || 'append-rejected'
        }
    }

    const physicalWal = runQueueWakeupMetricPhase('queueWalPhysicalPayload', () => getCoordinatorQueueWalPhysicalPayload(append.store, {
        previousMeta: previousWalMeta,
        previousStored: nextProjection?.stored || {}
    }))
    if((physicalWal.hardLimitCommittedSegments || physicalWal.previousCommitted || 0) >= physicalWal.hardLimit) {
        recordCoordinatorQueueWalPhysicalPayloadMetrics({
            previousCommitted: physicalWal.hardLimitCommittedSegments || physicalWal.previousCommitted || 0,
            committedSegments: physicalWal.committedSegments
        })
        incrementQueueWakeupMetric('coordinatorAuthority.queueWal.segmentHardBlocked')
        scheduleCoordinatorQueueWalCheckpointSwitch('segmentHardLimit')
        scheduleCoordinatorReconcile(1000, {
            reason: 'queue-wal-segment-hard-limit',
            edgeTriggered: true
        })
        return {
            saved: false,
            backend: 'queue-wal',
            reason: 'queue-wal-segment-hard-limit',
            append
        }
    }

    recordCoordinatorQueueWalPhysicalPayloadMetrics(physicalWal)
    const walSaved = await metricStorageSet(physicalWal.payload, {
        metricPath: options.metricPath || `authority.${operationKind}.queueWal.save`,
        phase: 'queueWalStorageSet',
        queueOperation: operationKind,
        queueChangedRows: records.length,
        coordinatorAuthorityWrite: true
    })
    if(walSaved === false) {
        incrementQueueWakeupMetric('coordinatorAuthority.queueWal.appendSuppressed')
        return {
            saved: false,
            backend: 'queue-wal',
            reason: 'wal-storage-suppressed',
            append
        }
    }

    incrementQueueWakeupMetric('coordinatorAuthority.queueWal.appended', records.length)
    incrementQueueWakeupMetric('coordinatorAuthority.queueWal.appendBytes', getJsonByteSize(append.records || []))
    incrementQueueWakeupMetric('coordinatorAuthority.queueWal.segmentWrites', Object.keys(physicalWal.payload || {}).length)
    recordQueueWakeupMetricMax('coordinatorAuthority.queueWal.maxAppendBytes', getJsonByteSize(append.records || []))
    recordQueueWakeupMetricMax('coordinatorAuthority.queueWal.maxCommittedSegments', physicalWal.committedSegments)
    if(physicalWal.committedSegments >= physicalWal.softSwitchAt) {
        incrementQueueWakeupMetric('coordinatorAuthority.queueWal.segmentSoftSwitchScheduled')
        scheduleCoordinatorQueueWalCheckpointSwitch('segmentSoftSwitch')
    }
    const storageContext = getActiveStorageContext()
    if(storageContext) {
        storageContext.coordinatorAuthorityQueueMutationApplied = true
        storageContext.coordinatorAuthorityQueueOperation = operationKind
    }

    const recoveredAfterAppend = runQueueWakeupMetricPhase('queueWalReplayVerify', () => recoverProjectedState(append.store))
    const appendedRecordIds = new Set((append.records || []).map(record => record.id).filter(Boolean))
    const ignoredAppendedRecords = (recoveredAfterAppend?.projected?.ignored || [])
        .filter(entry => appendedRecordIds.has(entry?.record?.id))
    if(recoveredAfterAppend?.recovered !== true || ignoredAppendedRecords.length) {
        incrementQueueWakeupMetric(ignoredAppendedRecords.length
            ? 'coordinatorAuthority.queueWal.batchAppendIgnoredAfterReplay'
            : 'coordinatorAuthority.queueWal.batchAppendRecoveryFailed')
        recordCoordinatorDiagnosticEvent(
            ignoredAppendedRecords.length
                ? 'coordinator-authority-queue-wal-batch-append-ignored-after-replay'
                : 'coordinator-authority-queue-wal-batch-append-recovery-failed',
            ignoredAppendedRecords[0]?.reason ||
                recoveredAfterAppend?.reason ||
                'Coordinator authority queue WAL batch append did not replay as durable authority'
        )
        scheduleCoordinatorReconcile(1000, {
            reason: ignoredAppendedRecords.length
                ? 'queue-wal-batch-append-ignored-after-replay'
                : 'queue-wal-batch-append-recovery-failed',
            edgeTriggered: true
        })
        return {
            saved: false,
            backend: 'queue-wal',
            reason: ignoredAppendedRecords[0]?.reason || recoveredAfterAppend?.reason || 'batch-append-replay-failed',
            append,
            walSaved: true,
            replayIgnored: ignoredAppendedRecords
        }
    }
    const authoritativeProjectionQueue = recoveredAfterAppend?.projected?.state?.queue ||
        recoveredAfterAppend?.state?.queue ||
        null
    const projectionQueueBase = authoritativeProjectionQueue || nextProjection.queue || {}

    try {
        appendCoordinatorAuthorityShadowWalRecords(records, {
            operationKind,
            reason: options.reason || 'ordinaryMutation'
        })
    }
    catch {}

    let projectionSaved = true
    try {
        const projectionPayload = runQueueWakeupMetricPhase('queueProjectionBuild', () => options.projectionPayload === 'queueViewOnly'
            ? {[COORDINATOR_QUEUE_VIEW_KEY]: buildCoordinatorQueueView(projectionQueueBase)}
            : buildCoordinatorQueueDerivedProjectionPayload(projectionQueueBase))
        const saved = await metricStorageSet(projectionPayload, {
            metricPath: options.projectionMetricPath || `authority.${operationKind}.projection.save`,
            phase: 'queueProjectionStorageSet',
            queueOperation: `${operationKind}-projection`,
            queueChangedRows: records.length,
            coordinatorAuthorityWrite: true
        })
        projectionSaved = saved !== false
    }
    catch(error) {
        projectionSaved = false
        recordCoordinatorDiagnosticEvent(
            'coordinator-authority-queue-wal-batch-projection-failed',
            error?.message || 'Coordinator authority queue WAL batch projection update failed'
        )
    }
    if(!projectionSaved) {
        incrementQueueWakeupMetric('coordinatorAuthority.queueWal.projectionFailed')
        scheduleCoordinatorReconcile(1000, {
            reason: 'queue-wal-batch-projection-failed',
            edgeTriggered: true
        })
    }
    else {
        incrementQueueWakeupMetric('coordinatorAuthority.queueWal.projectionSaved')
    }

    for(const record of records) {
        recordFlightRecorderEvent({
            kind: 'authority-mutation',
            source: 'persistCoordinatorAuthorityQueueWalBatchMutation',
            operationKind: record.operationKind || operationKind || '',
            rowKey: record.key || '',
            targetUrl: getCoordinatorItemHref(record.value || {}) || record.value?.targetProfileHref || '',
            attemptId: record.attemptId || getAttemptIdFromValue(record.value || {}),
            attemptNumber: record.attemptNumber || getAttemptNumberFromValue(record.value || {}),
            runId: record.runId || record.value?.runId || '',
            statusAfter: record.value?.status || record.status || '',
            accepted: true,
            durable: true,
            changed: true,
            reason: record.reason || options.reason || ''
        })
    }

    return {
        saved: true,
        backend: 'queue-wal',
        append,
        physicalWal,
        authoritativeQueue: authoritativeProjectionQueue || null,
        projectionSaved,
        snapshotSaved: false,
        walSaved: true,
        records
    }
}

async function switchCoordinatorAuthorityQueueWalCheckpoint(options = {}) {
    const failureResult = {
        checkpointSwitched: false,
        saved: false,
        durable: false,
        reason: 'storage-update-fallback'
    }

    return enqueueSpaceFeedStorageUpdate(async () => {
        const stored = await metricStorageGet({
            ...getCoordinatorQueueWalStorageDefaults()
        }, {
            metricPath: options.metricPath || 'queueWal.checkpointSwitch.load'
        })
        const snapshotQueue = {}
        const storedWal = await loadCoordinatorQueueWalStoreFromStorage(stored, snapshotQueue, {
            metricPath: `${options.metricPath || 'queueWal.checkpointSwitch.load'}.segments`,
            suppressCheckpointSwitchSchedule: options.suppressCheckpointSwitchSchedule === true
        })
        const recovered = recoverProjectedState(storedWal)
        if(recovered?.recovered !== true) {
            incrementQueueWakeupMetric('coordinatorAuthority.queueWal.checkpointFailed')
            recordCoordinatorDiagnosticEvent(
                'coordinator-authority-queue-wal-checkpoint-recovery-failed',
                recovered?.reason || 'Coordinator authority queue WAL checkpoint recovery failed'
            )
            return {
                checkpointSwitched: false,
                saved: false,
                durable: false,
                reason: recovered?.reason || 'recovery-failed'
            }
        }

        const recoveredQueue = normalizeCoordinatorMap(recovered?.projected?.state?.queue || {})
        const activeGenerationId = storedWal?.meta?.activeCheckpoint
        const activeRecords = getWalRecordsForGeneration(storedWal, activeGenerationId)
        const maxAppliedSeq = Number.parseInt(recovered?.projected?.maxSeq, 10) ||
            Number.parseInt(recovered?.checkpoint?.snapshotSeq, 10) ||
            0
        const checkpointedRecords = activeRecords.filter(record => (Number.parseInt(record?.seq, 10) || 0) <= maxAppliedSeq).length
        const prepared = writeInactiveCheckpoint(storedWal, {queue: recoveredQueue}, {
            snapshotSeq: maxAppliedSeq,
            createdAt: Date.now()
        })
        const activated = activateCheckpoint(prepared.store, prepared.checkpointId)
        if(activated?.activated !== true) {
            incrementQueueWakeupMetric('coordinatorAuthority.queueWal.checkpointFailed')
            recordCoordinatorDiagnosticEvent(
                'coordinator-authority-queue-wal-checkpoint-activation-failed',
                activated?.reason || 'Coordinator authority queue WAL checkpoint activation failed'
            )
            return {
                checkpointSwitched: false,
                saved: false,
                durable: false,
                reason: activated?.reason || 'activation-failed',
                snapshotSeq: maxAppliedSeq,
                checkpointedRecords
            }
        }

        const verify = recoverProjectedState(activated.store)
        if(verify?.recovered !== true) {
            incrementQueueWakeupMetric('coordinatorAuthority.queueWal.checkpointFailed')
            recordCoordinatorDiagnosticEvent(
                'coordinator-authority-queue-wal-checkpoint-verify-failed',
                verify?.reason || 'Coordinator authority queue WAL checkpoint verification failed'
            )
            return {
                checkpointSwitched: false,
                saved: false,
                durable: false,
                reason: verify?.reason || 'verification-failed',
                snapshotSeq: maxAppliedSeq,
                checkpointedRecords
            }
        }

        const previousWalMeta = stored[COORDINATOR_QUEUE_WAL_META_KEY] || null
        let walSaved = false
        let checkpointWal = null
        let preSegmentedWalMonolithCleanup = null
        try {
            checkpointWal = getCoordinatorQueueWalPhysicalPayload(activated.store, {
                previousMeta: previousWalMeta,
                previousStored: stored,
                forceWriteCheckpoints: true
            })
            recordCoordinatorQueueWalPhysicalPayloadMetrics(checkpointWal)
            preSegmentedWalMonolithCleanup = await cleanupPreSegmentedCoordinatorQueueWalMonolithBeforeCheckpoint(previousWalMeta)
            walSaved = await metricStorageSet({
                ...(checkpointWal?.payload || {}),
                ...buildCoordinatorQueueDerivedProjectionPayload(recoveredQueue)
            }, {
                metricPath: options.saveMetricPath || 'queueWal.checkpointSwitch.save',
                queueOperation: 'queue-wal-checkpoint-switch',
                queueChangedRows: Object.keys(recoveredQueue).length,
                coordinatorAuthorityWrite: true
            })
        }
        catch(error) {
            incrementQueueWakeupMetric('coordinatorAuthority.queueWal.checkpointFailed')
            recordCoordinatorDiagnosticEvent(
                'coordinator-authority-queue-wal-checkpoint-save-failed',
                error?.message || 'Coordinator authority queue WAL checkpoint save failed'
            )
            return {
                checkpointSwitched: false,
                saved: false,
                durable: false,
                reason: 'wal-checkpoint-save-failed',
                snapshotSeq: maxAppliedSeq,
                checkpointedRecords,
                error: `${error?.message || error || 'storage error'}`.slice(0, 240)
            }
        }
        if(walSaved === false) {
            incrementQueueWakeupMetric('coordinatorAuthority.queueWal.checkpointSuppressed')
            return {
                checkpointSwitched: false,
                saved: false,
                durable: false,
                reason: 'wal-checkpoint-storage-suppressed',
                snapshotSeq: maxAppliedSeq,
                checkpointedRecords
            }
        }

        incrementQueueWakeupMetric('coordinatorAuthority.queueWal.checkpointed')
        incrementQueueWakeupMetric('coordinatorAuthority.queueWal.checkpointedRecords', checkpointedRecords)
        recordQueueWakeupMetricMax('coordinatorAuthority.queueWal.maxCheckpointSeq', maxAppliedSeq)
        recordQueueWakeupMetricMax(
            'coordinatorAuthority.queueWal.maxPostCheckpointTailLength',
            getWalRecordsForGeneration(activated.store, activated.store?.meta?.activeCheckpoint).length
        )

        const physicalCleanup = await cleanupRetiredCoordinatorQueueWalPhysicalKeys(
            previousWalMeta,
            checkpointWal?.payload?.[COORDINATOR_QUEUE_WAL_META_KEY] || null,
            {metricPath: options.cleanupMetricPath || 'queueWal.checkpointSwitch.physicalCleanup.remove'}
        )

        return {
            checkpointSwitched: true,
            saved: true,
            durable: true,
            reason: 'checkpointed',
            snapshotSeq: maxAppliedSeq,
            checkpointedRecords,
            tailLength: getWalRecordsForGeneration(activated.store, activated.store?.meta?.activeCheckpoint).length,
            walStore: activated.store,
            physicalCleanup,
            preSegmentedWalMonolithCleanup,
            queue: recoveredQueue
        }
    }, {
        reason: 'coordinator-authority.queueWal.checkpointSwitch',
        timeoutMs: options.timeoutMs,
        failureValue: failureResult
    })
}

function getCoordinatorAuthorityShadowWalRetainedRecordCount() {
    return getWalRecordsForGeneration(
        coordinatorAuthorityShadowWalStore,
        coordinatorAuthorityShadowWalStore?.meta?.activeCheckpoint
    ).length
}

function switchCoordinatorAuthorityShadowWalCheckpoint(reason = 'retention-limit') {
    const snapshotSeq = Math.max(
        Number.parseInt(coordinatorAuthorityShadowWalProjectionMaxSeq, 10) || 0,
        Number.parseInt(coordinatorAuthorityShadowWalStore?.meta?.snapshotSeq, 10) || 0
    )
    const nextSeq = Math.max(
        Number.parseInt(coordinatorAuthorityShadowWalStore?.meta?.nextSeq, 10) || 0,
        snapshotSeq + 1
    )
    coordinatorAuthorityShadowWalStore = makePairedCheckpointStore(
        cloneCoordinatorAuthorityValue(coordinatorAuthorityShadowWalProjectedState || {queue: {}}),
        {
            snapshotSeq,
            nextSeq,
            createdAt: Date.now()
        }
    )
    coordinatorAuthorityShadowWalProjectionSnapshotSeq = snapshotSeq
    coordinatorAuthorityShadowWalAppliedIds = new Set()
    incrementQueueWakeupMetric('coordinatorAuthority.shadowWal.checkpointSwitched')
    recordQueueWakeupMetricMax('coordinatorAuthority.shadowWal.maxCheckpointSeq', snapshotSeq)

    return {
        checkpointSwitched: true,
        reason,
        snapshotSeq,
        retainedRecords: getCoordinatorAuthorityShadowWalRetainedRecordCount()
    }
}

function appendCoordinatorAuthorityShadowWalRecords(records = [], options = {}) {
    const normalizedRecords = (Array.isArray(records) ? records : [records])
        .filter(record => record && typeof record === 'object')
        .map(record => {
            const next = cloneCoordinatorAuthorityValue(record)
            delete next.id
            delete next.seq
            return next
        })
    if(!normalizedRecords.length) {
        return {appended: false, records: [], reason: 'no-records'}
    }

    const segmentId = `${options.segmentId || `coordinator-authority-shadow-${Date.now()}`}`
    const append = appendWalRecordsToGeneration(coordinatorAuthorityShadowWalStore, normalizedRecords, {
        segmentId
    })
    if(append?.rejected) {
        incrementQueueWakeupMetric('coordinatorAuthority.shadowWal.appendRejected')
        recordCoordinatorDiagnosticEvent(
            'coordinator-authority-shadow-wal-append-rejected',
            append.reason || 'Coordinator authority shadow WAL append was rejected'
        )
        return {
            appended: false,
            records: [],
            reason: append.reason || 'append-rejected'
        }
    }

    coordinatorAuthorityShadowWalStore = append.store
    const appendedRecords = append.records || []
    const bytes = getJsonByteSize(appendedRecords)
    incrementQueueWakeupMetric('coordinatorAuthority.shadowWal.appended', appendedRecords.length)
    incrementQueueWakeupMetric('coordinatorAuthority.shadowWal.appendBatches')
    incrementQueueWakeupMetric('coordinatorAuthority.shadowWal.appendBytes', bytes)
    recordQueueWakeupMetricMax('coordinatorAuthority.shadowWal.maxAppendBytes', bytes)

    let projectedState = cloneCoordinatorAuthorityValue(coordinatorAuthorityShadowWalProjectedState || {queue: {}})
    let matched = 0
    let mismatched = 0
    let recovered = true
    const appendResults = {}
    for(const record of appendedRecords) {
        try {
            const projection = applyWalRecord(projectedState, record, {
                snapshotSeq: coordinatorAuthorityShadowWalProjectionSnapshotSeq,
                appliedIds: coordinatorAuthorityShadowWalAppliedIds
            })
            if(projection?.applied === true) projectedState = projection.state
            const projectedRow = projection?.state?.queue?.[record.key] || null
            const rowMatched = projection?.applied === true &&
                JSON.stringify(projectedRow || null) === JSON.stringify(record.value || null)
            if(rowMatched) matched += 1
            else mismatched += 1
            appendResults[record.id] = {
                applied: projection?.applied === true,
                matched: rowMatched,
                reason: projection?.reason || '',
                projectedRow
            }
        }
        catch(error) {
            recovered = false
            mismatched += 1
            appendResults[record?.id || `append-error-${mismatched}`] = {
                applied: false,
                matched: false,
                reason: 'projection-error',
                error: `${error?.message || error || 'projection error'}`.slice(0, 240)
            }
        }
        coordinatorAuthorityShadowWalProjectionMaxSeq = Math.max(
            coordinatorAuthorityShadowWalProjectionMaxSeq,
            Number.parseInt(record.seq, 10) || 0
        )
    }
    coordinatorAuthorityShadowWalProjectedState = projectedState

    if(matched) incrementQueueWakeupMetric('coordinatorAuthority.shadowWal.appendProjectionMatched', matched)
    if(mismatched) {
        incrementQueueWakeupMetric('coordinatorAuthority.shadowWal.appendProjectionMismatched', mismatched)
        recordCoordinatorDiagnosticEvent(
            'coordinator-authority-shadow-wal-append-mismatch',
            'Coordinator authority shadow WAL replay did not match appended queue records'
        )
    }
    const recordsBeforeCheckpointSwitch = getCoordinatorAuthorityShadowWalRetainedRecordCount()
    const checkpointSwitch = recordsBeforeCheckpointSwitch > MAX_COORDINATOR_AUTHORITY_SHADOW_WAL_RECORDS
        ? switchCoordinatorAuthorityShadowWalCheckpoint('retention-limit')
        : null

    return {
        appended: true,
        records: appendedRecords,
        results: appendResults,
        generationId: append.generationId,
        segmentId,
        bytes,
        recovered,
        matched,
        mismatched,
        maxSeq: coordinatorAuthorityShadowWalProjectionMaxSeq,
        checkpointSwitched: checkpointSwitch?.checkpointSwitched === true,
        checkpointSwitch,
        recordsBeforeCheckpointSwitch,
        totalRecords: getCoordinatorAuthorityShadowWalRetainedRecordCount()
    }
}

function recordCoordinatorAuthorityShadowWalProjection(result = {}) {
    if(result?.durable !== true) {
        incrementQueueWakeupMetric('coordinatorAuthority.shadowWal.skippedNonDurable')
        return {
            checked: false,
            matched: false,
            reason: 'non-durable'
        }
    }

    const record = makeCoordinatorAuthorityShadowWalRecord(result)
    if(!record) return {checked: false, reason: 'not-row-mutation'}

    try {
        incrementQueueWakeupMetric('coordinatorAuthority.shadowWal.checked')
        incrementQueueWakeupMetric('coordinatorAuthority.shadowWal.bytes', getJsonByteSize(record))
        recordQueueWakeupMetricMax('coordinatorAuthority.shadowWal.maxBytes', getJsonByteSize(record))

        const baseState = {
            queue: {
                [result.rowKey]: cloneCoordinatorAuthorityValue(result.previousRow || {})
            }
        }
        const projection = applyWalRecord(baseState, record, {
            snapshotSeq: 0,
            appliedIds: new Set()
        })
        const projectedRow = projection?.state?.queue?.[result.rowKey] || null
        const matched = projection?.applied === true &&
            JSON.stringify(projectedRow || null) === JSON.stringify(result.nextRow || null)

        if(matched) {
            incrementQueueWakeupMetric('coordinatorAuthority.shadowWal.matched')
        }
        else {
            incrementQueueWakeupMetric('coordinatorAuthority.shadowWal.mismatched')
            recordCoordinatorDiagnosticEvent(
                'coordinator-authority-shadow-wal-mismatch',
                `${result.operationKind || 'authority-row-mutation'} did not project to the persisted row`
            )
        }

        const shadowResult = {
            checked: true,
            matched,
            reason: matched ? '' : projection?.reason || 'projection-mismatch',
            record: projection?.record || record,
            projectedRow
        }
        if(matched) {
            try {
                shadowResult.append = appendCoordinatorAuthorityShadowWalRecords([record], {
                    segmentId: `coordinator-authority-shadow-${result.operationKind || 'authority-row-mutation'}-${Date.now()}`
                })
            }
            catch(error) {
                incrementQueueWakeupMetric('coordinatorAuthority.shadowWal.appendFailed')
                recordCoordinatorDiagnosticEvent(
                    'coordinator-authority-shadow-wal-append-failed',
                    error?.message || 'Coordinator authority shadow WAL append diagnostic failed'
                )
                shadowResult.append = {
                    appended: false,
                    records: [],
                    reason: 'diagnostic-error',
                    error: `${error?.message || error || 'diagnostic error'}`.slice(0, 240)
                }
            }
        }
        return shadowResult
    }
    catch(error) {
        incrementQueueWakeupMetric('coordinatorAuthority.shadowWal.failed')
        recordCoordinatorDiagnosticEvent(
            'coordinator-authority-shadow-wal-failed',
            error?.message || 'Coordinator authority shadow WAL projection failed'
        )
        return {
            checked: true,
            matched: false,
            reason: 'projection-error',
            error: `${error?.message || error || 'projection error'}`.slice(0, 240),
            record
        }
    }
}

function safeRecordCoordinatorAuthorityShadowWalProjection(result = {}) {
    try {
        return recordCoordinatorAuthorityShadowWalProjection(result)
    }
    catch(error) {
        incrementQueueWakeupMetric('coordinatorAuthority.shadowWal.failed')
        recordCoordinatorDiagnosticEvent(
            'coordinator-authority-shadow-wal-failed',
            error?.message || 'Coordinator authority shadow WAL diagnostic failed'
        )
        return {
            checked: false,
            matched: false,
            reason: 'diagnostic-error',
            error: `${error?.message || error || 'diagnostic error'}`.slice(0, 240)
        }
    }
}

function makeProgressShadowWalRecord(profileHref = '', record = {}, options = {}) {
    const operation = options.operation && typeof options.operation === 'object' ? options.operation : null
    const operationRecord = operation?.nextRecord && typeof operation.nextRecord === 'object'
        ? operation.nextRecord
        : record
    const normalizedHref = normalizeQuoraProfileUrl(operation?.rowKey || profileHref || operationRecord?.profileHref || '')
    if(!normalizedHref || !operationRecord || typeof operationRecord !== 'object') return null

    const attemptId = getAttemptIdFromValue(operationRecord)
    const attemptNumber = getAttemptNumberFromValue(operationRecord)
    const runId = `${operationRecord?.runId || ''}`.trim()
    const operationKind = getCoordinatorRowEventMetricKind(operation?.operationKind || options.eventKind || 'progress')
    const status = `${operationRecord?.status || ''}`.trim()
    const at = Number.parseInt(operationRecord.updatedAt || operationRecord.terminalAt, 10) || Date.now()

    return {
        kind: 'map.set',
        area: 'progress',
        key: normalizedHref,
        id: [
            'progress',
            operationKind,
            normalizedHref,
            attemptId,
            attemptNumber || '',
            status,
            at
        ].filter(value => value !== '').join(':'),
        eventKind: operationKind,
        operationKind,
        reason: operation?.reason || options.reason || '',
        value: cloneCoordinatorAuthorityValue(operationRecord),
        runId,
        attemptId,
        attemptNumber,
        terminal: operation?.terminal === true || isTerminalProfileNukeRecord(operationRecord),
        at,
        seq: 1
    }
}

function cloneNormalizedProgressRecordsForShadowWal(records = {}) {
    const normalized = {}
    for(const [profileHref, record] of Object.entries(records || {})) {
        const href = normalizeQuoraProfileUrl(record?.profileHref || profileHref || '')
        if(!href || !record || typeof record !== 'object') continue
        normalized[href] = {
            ...cloneCoordinatorAuthorityValue(record),
            profileHref: href
        }
    }
    return normalized
}

function recordProgressShadowWalProjection(progressRecords = {}, options = {}) {
    const normalizedRecords = options.recordsAlreadyNormalized === true
        ? cloneNormalizedProgressRecordsForShadowWal(progressRecords || {})
        : normalizeStoredProfileNukeProgress(progressRecords || {})
    const previousRecords = options.previousRecordsAlreadyNormalized === true
        ? cloneNormalizedProgressRecordsForShadowWal(options.previousProgressRecords || {})
        : normalizeStoredProfileNukeProgress(options.previousProgressRecords || {})
    const progressOperations = options.progressOperations && typeof options.progressOperations === 'object'
        ? options.progressOperations
        : {}
    const entries = Object.entries(normalizedRecords)
    if(!entries.length) return {checked: 0, matched: 0, mismatched: 0, failed: 0, results: {}}

    const eventKind = getCoordinatorRowEventMetricKind(options.eventKind || 'progress')
    const eventPrefix = `rowEvent.${eventKind}.shadowWal`
    const summary = {checked: 0, matched: 0, mismatched: 0, failed: 0, withPrevious: 0, results: {}}

    for(const [profileHref, record] of entries) {
        const operation = progressOperations[profileHref] || null
        const walRecord = makeProgressShadowWalRecord(profileHref, record, {eventKind, operation})
        if(!walRecord) {
            summary.results[profileHref] = {
                checked: false,
                matched: false,
                reason: 'invalid-record'
            }
            continue
        }

        const previousRecord = previousRecords[profileHref] || null

        try {
            const bytes = getJsonByteSize(walRecord)
            incrementQueueWakeupMetric('progress.shadowWal.checked')
            incrementQueueWakeupMetric(`${eventPrefix}.checked`)
            incrementQueueWakeupMetric('progress.shadowWal.bytes', bytes)
            incrementQueueWakeupMetric(`${eventPrefix}.bytes`, bytes)
            recordQueueWakeupMetricMax('progress.shadowWal.maxBytes', bytes)
            recordQueueWakeupMetricMax(`${eventPrefix}.maxBytes`, bytes)

            if(previousRecord) {
                summary.withPrevious += 1
                incrementQueueWakeupMetric('progress.shadowWal.withPrevious')
                incrementQueueWakeupMetric(`${eventPrefix}.withPrevious`)
            }
            const projection = applyWalRecord({
                progress: previousRecord ? {
                    [profileHref]: cloneCoordinatorAuthorityValue(previousRecord)
                } : {}
            }, walRecord, {
                snapshotSeq: 0,
                appliedIds: new Set()
            })
            const projectedRecord = projection?.state?.progress?.[profileHref] || null
            const matched = projection?.applied === true &&
                JSON.stringify(projectedRecord || null) === JSON.stringify(record || null)

            summary.checked += 1
            if(matched) {
                summary.matched += 1
                incrementQueueWakeupMetric('progress.shadowWal.matched')
                incrementQueueWakeupMetric(`${eventPrefix}.matched`)
            }
            else {
                summary.mismatched += 1
                incrementQueueWakeupMetric('progress.shadowWal.mismatched')
                incrementQueueWakeupMetric(`${eventPrefix}.mismatched`)
                recordCoordinatorDiagnosticEvent(
                    'progress-shadow-wal-mismatch',
                    `${eventKind} did not project to the persisted progress record`
                )
            }

            summary.results[profileHref] = {
                checked: true,
                matched,
                reason: matched ? '' : projection?.reason || 'projection-mismatch',
                withPrevious: !!previousRecord,
                terminal: walRecord.terminal === true,
                operationKind: walRecord.operationKind,
                record: walRecord,
                projectedRecord
            }
        }
        catch(error) {
            summary.checked += 1
            summary.mismatched += 1
            summary.failed += 1
            incrementQueueWakeupMetric('progress.shadowWal.failed')
            incrementQueueWakeupMetric(`${eventPrefix}.failed`)
            recordCoordinatorDiagnosticEvent(
                'progress-shadow-wal-failed',
                error?.message || 'Progress shadow WAL projection failed'
            )
            summary.results[profileHref] = {
                checked: true,
                matched: false,
                reason: 'projection-error',
                withPrevious: !!previousRecord,
                error: `${error?.message || error || 'projection error'}`.slice(0, 240)
            }
        }
    }

    return summary
}

function safeRecordProgressShadowWalProjection(progressRecords = {}, options = {}) {
    try {
        return recordProgressShadowWalProjection(progressRecords, options)
    }
    catch(error) {
        const eventKind = getCoordinatorRowEventMetricKind(options.eventKind || 'progress')
        const eventPrefix = `rowEvent.${eventKind}.shadowWal`
        incrementQueueWakeupMetric('progress.shadowWal.failed')
        incrementQueueWakeupMetric(`${eventPrefix}.failed`)
        recordCoordinatorDiagnosticEvent(
            'progress-shadow-wal-failed',
            error?.message || 'Progress shadow WAL diagnostic failed'
        )
        return {
            checked: 0,
            matched: 0,
            mismatched: 0,
            failed: 1,
            reason: 'diagnostic-error',
            error: `${error?.message || error || 'diagnostic error'}`.slice(0, 240),
            results: {}
        }
    }
}

function getProgressShadowWalRetainedRecordCount() {
    return getWalRecordsForGeneration(
        progressShadowWalStore,
        progressShadowWalStore?.meta?.activeCheckpoint
    ).length
}

function switchProgressShadowWalCheckpoint(reason = 'retention-limit') {
    const snapshotSeq = Math.max(
        Number.parseInt(progressShadowWalProjectionMaxSeq, 10) || 0,
        Number.parseInt(progressShadowWalStore?.meta?.snapshotSeq, 10) || 0
    )
    const nextSeq = Math.max(
        Number.parseInt(progressShadowWalStore?.meta?.nextSeq, 10) || 0,
        snapshotSeq + 1
    )
    progressShadowWalStore = makePairedCheckpointStore(
        cloneCoordinatorAuthorityValue(progressShadowWalProjectedState || {progress: {}}),
        {
            snapshotSeq,
            nextSeq,
            createdAt: Date.now()
        }
    )
    progressShadowWalProjectionSnapshotSeq = snapshotSeq
    progressShadowWalAppliedIds = new Set()
    incrementQueueWakeupMetric('progress.shadowWal.checkpointSwitched')
    recordQueueWakeupMetricMax('progress.shadowWal.maxCheckpointSeq', snapshotSeq)

    return {
        checkpointSwitched: true,
        reason,
        snapshotSeq,
        retainedRecords: getProgressShadowWalRetainedRecordCount()
    }
}

function appendProgressShadowWalRecords(records = [], options = {}) {
    const normalizedRecords = (Array.isArray(records) ? records : [records])
        .filter(record => record && typeof record === 'object')
        .map(record => {
            const next = cloneCoordinatorAuthorityValue(record)
            delete next.id
            delete next.seq
            return next
        })
    if(!normalizedRecords.length) {
        return {appended: false, records: [], reason: 'no-records'}
    }

    const segmentId = `${options.segmentId || `progress-shadow-${Date.now()}`}`
    const append = appendWalRecordsToGeneration(progressShadowWalStore, normalizedRecords, {
        segmentId
    })
    if(append?.rejected) {
        incrementQueueWakeupMetric('progress.shadowWal.appendRejected')
        recordCoordinatorDiagnosticEvent(
            'progress-shadow-wal-append-rejected',
            append.reason || 'Progress shadow WAL append was rejected'
        )
        return {
            appended: false,
            records: [],
            reason: append.reason || 'append-rejected'
        }
    }
    progressShadowWalStore = append.store || progressShadowWalStore

    const appendedRecords = append.records || []
    const bytes = getJsonByteSize(appendedRecords)
    incrementQueueWakeupMetric('progress.shadowWal.appended', appendedRecords.length)
    incrementQueueWakeupMetric('progress.shadowWal.appendBatches')
    incrementQueueWakeupMetric('progress.shadowWal.appendBytes', bytes)
    recordQueueWakeupMetricMax('progress.shadowWal.maxAppendBytes', bytes)

    const projectedProgress = {
        ...((progressShadowWalProjectedState && progressShadowWalProjectedState.progress) || {})
    }
    let matched = 0
    let mismatched = 0
    let recovered = true
    const appendResults = {}
    for(const record of appendedRecords) {
        try {
            const existingRecord = projectedProgress[record.key] || null
            const projection = applyWalRecord({
                progress: existingRecord ? {
                    [record.key]: cloneCoordinatorAuthorityValue(existingRecord)
                } : {}
            }, record, {
                snapshotSeq: progressShadowWalProjectionSnapshotSeq,
                appliedIds: progressShadowWalAppliedIds
            })
            if(projection?.applied === true) {
                const projectedRecord = projection?.state?.progress?.[record.key] || null
                if(projectedRecord) projectedProgress[record.key] = projectedRecord
                else delete projectedProgress[record.key]
            }
            const projectedRecord = projection?.state?.progress?.[record.key] || null
            const rowMatched = projection?.applied === true &&
                JSON.stringify(projectedRecord || null) === JSON.stringify(record.value || null)
            if(rowMatched) matched += 1
            else mismatched += 1
            appendResults[record.id] = {
                applied: projection?.applied === true,
                matched: rowMatched,
                reason: projection?.reason || '',
                projectedRecord
            }
        }
        catch(error) {
            recovered = false
            mismatched += 1
            appendResults[record.id] = {
                applied: false,
                matched: false,
                reason: 'projection-error',
                error: `${error?.message || error || 'projection error'}`.slice(0, 240)
            }
        }
        progressShadowWalProjectionMaxSeq = Math.max(
            progressShadowWalProjectionMaxSeq,
            Number.parseInt(record.seq, 10) || 0
        )
    }
    progressShadowWalProjectedState = {
        ...(progressShadowWalProjectedState || {}),
        progress: projectedProgress
    }

    if(matched) incrementQueueWakeupMetric('progress.shadowWal.appendProjectionMatched', matched)
    if(mismatched) {
        incrementQueueWakeupMetric('progress.shadowWal.appendProjectionMismatched', mismatched)
        recordCoordinatorDiagnosticEvent(
            'progress-shadow-wal-append-mismatch',
            'Progress shadow WAL replay did not match appended progress records'
        )
    }
    const recordsBeforeCheckpointSwitch = getProgressShadowWalRetainedRecordCount()
    const checkpointSwitch = recordsBeforeCheckpointSwitch > MAX_PROGRESS_SHADOW_WAL_RECORDS
        ? switchProgressShadowWalCheckpoint('retention-limit')
        : null

    return {
        appended: true,
        records: appendedRecords,
        results: appendResults,
        generationId: append.generationId,
        segmentId,
        bytes,
        recovered,
        matched,
        mismatched,
        maxSeq: progressShadowWalProjectionMaxSeq,
        checkpointSwitched: checkpointSwitch?.checkpointSwitched === true,
        checkpointSwitch,
        recordsBeforeCheckpointSwitch,
        totalRecords: getProgressShadowWalRetainedRecordCount()
    }
}

function safeAppendProgressShadowWalRecords(records = [], options = {}) {
    try {
        return appendProgressShadowWalRecords(records, options)
    }
    catch(error) {
        incrementQueueWakeupMetric('progress.shadowWal.appendFailed')
        recordCoordinatorDiagnosticEvent(
            'progress-shadow-wal-append-failed',
            error?.message || 'Progress shadow WAL append diagnostic failed'
        )
        return {
            appended: false,
            records: [],
            reason: 'diagnostic-error',
            error: `${error?.message || error || 'diagnostic error'}`.slice(0, 240)
        }
    }
}

function makeProgressShadowWalRowAppendResult(append = null, profileHref = '') {
    if(!append || append.appended !== true) return append || null

    const normalizedHref = normalizeQuoraProfileUrl(profileHref || '')
    if(!normalizedHref) return append

    const rowRecords = (append.records || [])
        .filter(record => normalizeQuoraProfileUrl(record?.key || '') === normalizedHref)
    if(!rowRecords.length) {
        return {
            appended: false,
            records: [],
            reason: 'missing-row-append',
            generationId: append.generationId,
            segmentId: append.segmentId,
            totalRecords: append.totalRecords || 0
        }
    }

    const rowResults = rowRecords.map(record => append.results?.[record.id] || null)
    const rowMatched = rowResults.filter(result => result?.matched === true).length
    const rowMismatched = rowRecords.length - rowMatched

    return {
        ...append,
        records: rowRecords,
        bytes: getJsonByteSize(rowRecords),
        matched: rowMatched,
        mismatched: rowMismatched
    }
}

function isCoordinatorAuthorityRejectResult(value = null) {
    return !!value && typeof value === 'object' &&
        (value.__coordinatorAuthorityReject === true || value.accepted === false)
}

function normalizeCoordinatorAuthorityMutationRow(value, previousRow = null) {
    if(value === undefined) return previousRow
    if(value && typeof value === 'object' && Object.prototype.hasOwnProperty.call(value, 'nextRow')) {
        return value.nextRow
    }
    return value
}

function normalizeCoordinatorAuthorityStateInput(value = null) {
    if(!value || typeof value !== 'object') return null

    const stored = value.stored && typeof value.stored === 'object' ? value.stored : {}
    const queue = normalizeCoordinatorMap(cloneCoordinatorAuthorityValue(
        value.queue || {}
    ))
    const runs = normalizeCoordinatorMap(cloneCoordinatorAuthorityValue(
        value.runs || stored[COORDINATOR_RUNS_KEY] || {}
    ))

    return {
        stored: {
            [COORDINATOR_QUEUE_KEY]: cloneCoordinatorAuthorityValue(queue),
            ...getCoordinatorQueueWalPhysicalStoredPayload(stored),
            [COORDINATOR_QUEUE_WAL_KEY]: cloneCoordinatorAuthorityValue(stored[COORDINATOR_QUEUE_WAL_KEY] || null),
            [COORDINATOR_RUNS_KEY]: cloneCoordinatorAuthorityValue(runs)
        },
        queue,
        runs
    }
}

function createCoordinatorAuthority() {
    let hydrated = false
    let projection = makeCoordinatorAuthorityProjection()
    let applyTail = Promise.resolve()

    async function hydrate(defaults = {}) {
        projection = makeCoordinatorAuthorityProjection(await loadCoordinatorCurrentAuthorityState(defaults))
        closeRuntimeTabsReclaimedByAuthority(projection.queue, 'authority-hydrate-reclaimed-runtime')
        hydrated = true
        return current()
    }

    function current() {
        return makeCoordinatorAuthorityProjection(projection)
    }

    function seedResidentProjection(state = {}) {
        const normalized = normalizeCoordinatorAuthorityStateInput(state)
        if(!normalized?.queue) return false
        projection = makeCoordinatorAuthorityProjection({
            ...projection,
            queue: normalized.queue,
            runs: normalized.runs || projection.runs || {}
        })
        hydrated = true
        return true
    }

    function absorbPersistedSnapshot(payload = {}, options = {}) {
        if(!hydrated || !payload || typeof payload !== 'object') return false

        const next = makeCoordinatorAuthorityProjection(projection)
        let changed = false

        let queueSeededFromPayload = false
        if(options.allowRecoveredAuthorityQueueSeed === true &&
            Object.prototype.hasOwnProperty.call(payload, COORDINATOR_QUEUE_KEY)) {
            next.queue = normalizeCoordinatorMap(cloneCoordinatorAuthorityValue(payload[COORDINATOR_QUEUE_KEY] || {}))
            next.stored[COORDINATOR_QUEUE_KEY] = cloneCoordinatorAuthorityValue(payload[COORDINATOR_QUEUE_KEY] || {})
            changed = true
            queueSeededFromPayload = true
        }
        let physicalWalKeys = Object.keys(payload || {}).filter(isCoordinatorQueueWalPhysicalStorageKey)
        let hasLegacyWalPayload = payload[COORDINATOR_QUEUE_WAL_KEY] &&
            typeof payload[COORDINATOR_QUEUE_WAL_KEY] === 'object'
        const incomingWalMeta = payload[`${COORDINATOR_QUEUE_WAL_KEY}.meta`] ||
            payload[COORDINATOR_QUEUE_WAL_KEY]?.meta ||
            null
        const residentWalMeta = next.stored[`${COORDINATOR_QUEUE_WAL_KEY}.meta`] ||
            next.stored[COORDINATOR_QUEUE_WAL_KEY]?.meta ||
            null
        const incomingNextSeq = Number.parseInt(incomingWalMeta?.nextSeq, 10) || 0
        const residentNextSeq = Number.parseInt(residentWalMeta?.nextSeq, 10) || 0
        if((physicalWalKeys.length || hasLegacyWalPayload) &&
            incomingNextSeq > 0 &&
            residentNextSeq > 0 &&
            incomingNextSeq < residentNextSeq) {
            incrementQueueWakeupMetric('coordinatorAuthority.queueWal.staleObserverPayloadIgnored')
            physicalWalKeys = []
            hasLegacyWalPayload = false
        }
        if(physicalWalKeys.length) {
            for(const key of physicalWalKeys) {
                next.stored[key] = cloneCoordinatorAuthorityValue(payload[key])
            }
            const hydrated = hydrateSegmentedWalStore(next.stored, {
                baseKey: COORDINATOR_QUEUE_WAL_KEY,
                fallbackStore: next.stored[COORDINATOR_QUEUE_WAL_KEY] || null
            })
            if(hydrated?.ok === true && hydrated.store) {
                next.stored[COORDINATOR_QUEUE_WAL_KEY] = hydrated.store
            }
            else if(!hasLegacyWalPayload && physicalWalKeys.some(key => key !== COORDINATOR_QUEUE_WAL_KEY)) {
                incrementQueueWakeupMetric('coordinatorAuthority.queueWal.segmentedHydrateFailed')
                recordCoordinatorDiagnosticEvent(
                    'coordinator-authority-queue-wal-segmented-hydrate-failed',
                    hydrated?.reason || 'Coordinator authority queue WAL segmented hydrate failed'
                )
                return false
            }
            changed = true
        }
        if(hasLegacyWalPayload) {
            next.stored[COORDINATOR_QUEUE_WAL_KEY] = cloneCoordinatorAuthorityValue(payload[COORDINATOR_QUEUE_WAL_KEY] || null)
        }
        if(hasLegacyWalPayload || physicalWalKeys.length) {
            const hasUsableWalStore = next.stored[COORDINATOR_QUEUE_WAL_KEY] &&
                typeof next.stored[COORDINATOR_QUEUE_WAL_KEY] === 'object'
            // A payload can legitimately carry a present-but-null/unusable WAL key alongside
            // an already-correct raw queue seed from payload[COORDINATOR_QUEUE_KEY] above (e.g.
            // the fast-executor's own storage-projection fallback repairing a stale resident
            // view). Recovering from a WAL store that isn't actually there just reproduces
            // recoverCoordinatorQueueFromWal's own "missing-wal" empty-queue fallback, which
            // would silently clobber the correct seed this same call already applied. Only
            // fall back to that empty-reset when nothing else in this payload set the queue.
            if(hasUsableWalStore || !queueSeededFromPayload) {
                const recovered = recoverCoordinatorQueueFromWal(
                    {},
                    next.stored[COORDINATOR_QUEUE_WAL_KEY]
                )
                next.queue = recovered.queue
                closeRuntimeTabsReclaimedByAuthority(next.queue, 'authority-observer-reclaimed-runtime')
                changed = true
            }
        }
        if(Object.prototype.hasOwnProperty.call(payload, COORDINATOR_RUNS_KEY)) {
            next.runs = normalizeCoordinatorMap(cloneCoordinatorAuthorityValue(payload[COORDINATOR_RUNS_KEY] || {}))
            next.stored[COORDINATOR_RUNS_KEY] = cloneCoordinatorAuthorityValue(payload[COORDINATOR_RUNS_KEY] || {})
            changed = true
        }
        if(Object.prototype.hasOwnProperty.call(payload, COORDINATOR_EVENTS_KEY)) {
            next.events = normalizeCoordinatorEvents(cloneCoordinatorAuthorityValue(payload[COORDINATOR_EVENTS_KEY] || []))
            next.stored[COORDINATOR_EVENTS_KEY] = cloneCoordinatorAuthorityValue(payload[COORDINATOR_EVENTS_KEY] || [])
            changed = true
        }
        if(changed) projection = next
        return changed
    }

    async function persist(nextProjection = projection, changes = {}) {
        const requestedReason = normalizeSnapshotWriteReason(changes.reason || 'ordinaryMutation')
        if(requestedReason === 'displayRead') {
            return saveCoordinatorState(nextProjection, {
                ...changes,
                reason: 'displayRead'
            })
        }
        if(requestedReason === 'checkpointSwitch') {
            return saveCoordinatorState(nextProjection, {
                ...changes,
                reason: 'checkpointSwitch'
            })
        }
        if(requestedReason === 'userMemoryNonAuthority') {
            return saveCoordinatorState(nextProjection, {
                ...changes,
                reason: 'userMemoryNonAuthority'
            })
        }
        return saveCoordinatorState(nextProjection, {
            ...changes,
            reason: 'ordinaryMutation'
        })
    }

    async function applyLocked(operation = {}) {
        const rowKey = normalizeCoordinatorAuthorityRowKey(
            operation.rowKey || operation.coordinatorKey || operation.profileHref || ''
        )
        const operationKind = normalizeQueueWriteOperationName(operation.operationKind || operation.kind || 'authority-row-mutation')
        const reason = normalizeSnapshotWriteReason(operation.reason || 'ordinaryMutation')

        const storageContext = getActiveStorageContext()
        const providedAuthorityState = operation.allowCurrentAuthorityState === true ||
            (storageContext && operation.allowLockedProjection === true)
            ? normalizeCoordinatorAuthorityStateInput(
                operation.currentAuthorityState || operation.authorityState || operation.lockedProjection
            )
            : null
        const residentAuthorityRows = !providedAuthorityState && hydrated
            ? makeCoordinatorAuthorityProjection(projection)
            : null
        const freshAuthorityRows = providedAuthorityState ||
            residentAuthorityRows ||
            await loadCoordinatorQueueRunsProjection()
        if(residentAuthorityRows) {
            incrementQueueWakeupMetric('coordinatorAuthority.residentProjectionUsedForMutation')
        }
        const retainedStoredProjection = Object.fromEntries(
            Object.entries(projection.stored || {})
                .filter(([key]) => !isCoordinatorQueueWalPhysicalStorageKey(key))
        )
        projection = makeCoordinatorAuthorityProjection({
            ...projection,
            stored: {
                ...retainedStoredProjection,
                [COORDINATOR_QUEUE_KEY]: freshAuthorityRows.stored?.[COORDINATOR_QUEUE_KEY] || {},
                ...getCoordinatorQueueWalPhysicalStoredPayload(freshAuthorityRows.stored || {}),
                [COORDINATOR_QUEUE_WAL_KEY]: freshAuthorityRows.stored?.[COORDINATOR_QUEUE_WAL_KEY] || null,
                [COORDINATOR_RUNS_KEY]: freshAuthorityRows.stored?.[COORDINATOR_RUNS_KEY] || {}
            },
            queue: freshAuthorityRows.queue,
            runs: freshAuthorityRows.runs
        })
        hydrated = true

        const previousRow = rowKey ? projection.queue[rowKey] || null : null

        if(!rowKey) {
            return makeCoordinatorAuthorityApplyResult({...operation, operationKind, rowKey}, {
                accepted: false,
                changed: false,
                durable: false,
                reason: 'missing-row-key'
            })
        }

        if(!previousRow) {
            return makeCoordinatorAuthorityApplyResult({...operation, operationKind, rowKey}, {
                accepted: false,
                changed: false,
                durable: false,
                reason: 'missing-row',
                previousRow
            })
        }

        const expectedAttemptId = normalizeAttemptId(operation.expectedAttemptId || '')
        const previousAttemptId = getAttemptIdFromValue(previousRow)
        if(expectedAttemptId && previousAttemptId !== expectedAttemptId) {
            return makeCoordinatorAuthorityApplyResult({...operation, operationKind, rowKey}, {
                accepted: false,
                changed: false,
                durable: false,
                staleAttempt: true,
                reason: 'stale-attempt',
                previousRow
            })
        }

        const expectedAttemptNumber = Number.parseInt(operation.expectedAttemptNumber, 10) || 0
        const previousAttemptNumber = getAttemptNumberFromValue(previousRow)
        if(expectedAttemptNumber && previousAttemptNumber !== expectedAttemptNumber) {
            return makeCoordinatorAuthorityApplyResult({...operation, operationKind, rowKey}, {
                accepted: false,
                changed: false,
                durable: false,
                staleAttempt: true,
                reason: 'stale-attempt-number',
                previousRow
            })
        }

        const mutationContext = {
            operationKind,
            rowKey,
            reason,
            previousRow: cloneCoordinatorAuthorityValue(previousRow),
            now: Date.now(),
            reject(rejectReason = 'rejected', details = {}) {
                return {
                    __coordinatorAuthorityReject: true,
                    reason: `${rejectReason || 'rejected'}`.trim() || 'rejected',
                    ...details
                }
            }
        }
        const mutationResult = typeof operation.mutate === 'function'
            ? await operation.mutate(cloneCoordinatorAuthorityValue(previousRow), mutationContext)
            : previousRow

        if(isCoordinatorAuthorityRejectResult(mutationResult)) {
            return makeCoordinatorAuthorityApplyResult({...operation, operationKind, rowKey}, {
                accepted: false,
                changed: false,
                durable: false,
                reason: mutationResult.reason || 'rejected',
                previousRow,
                nextRow: previousRow,
                staleAttempt: mutationResult.staleAttempt === true
            })
        }

        const nextRow = normalizeCoordinatorAuthorityMutationRow(mutationResult, previousRow)
        const changed = JSON.stringify(nextRow) !== JSON.stringify(previousRow)
        if(!changed) {
            return makeCoordinatorAuthorityApplyResult({...operation, operationKind, rowKey}, {
                accepted: true,
                changed: false,
                durable: true,
                reason: 'unchanged',
                previousRow,
                nextRow: previousRow,
                persistence: {saved: false, noOp: true}
            })
        }

        const nextProjection = makeCoordinatorAuthorityProjection({
            ...projection,
            queue: {
                ...projection.queue,
                [rowKey]: cloneCoordinatorAuthorityValue(nextRow)
            }
        })

        let result = null
        try {
            const baseResult = makeCoordinatorAuthorityApplyResult({...operation, operationKind, rowKey}, {
                accepted: true,
                changed: true,
                durable: false,
                reason: 'persistence-pending',
                previousRow,
                nextRow,
                terminal: isTerminalCoordinatorStatus(nextRow?.status)
            })
            if(!shouldUseCoordinatorQueueWalBackend(operationKind, reason)) {
                incrementQueueWakeupMetric('coordinatorAuthority.nonWalOperationRejected')
                incrementQueueWakeupMetric(`coordinatorAuthority.nonWalOperationRejected.${normalizeStorageMetricPathName(operationKind)}`)
                return makeCoordinatorAuthorityApplyResult({...operation, operationKind, rowKey}, {
                    accepted: false,
                    changed: false,
                    durable: false,
                    reason: 'non-wal-authority-operation',
                    previousRow,
                    nextRow: previousRow,
                    persistence: {
                        backend: 'queue-wal',
                        saved: false,
                        reason: 'non-wal-authority-operation'
                    }
                })
            }
            const persistenceResult = await persistCoordinatorAuthorityQueueWalMutation({
                    ...baseResult,
                    previousProjectionQueue: projection.queue
                }, nextProjection, {
                    metricPath: operation.metricPath
                        ? `${operation.metricPath}.queueWal`
                        : `authority.${operationKind}.queueWal.save`,
                    projectionMetricPath: operation.metricPath
                        ? `${operation.metricPath}.projection`
                        : `authority.${operationKind}.projection.save`,
                    deferProjectionSave: operation.deferProjectionSave === true,
                    projectionPayload: operation.projectionPayload || '',
                    includeProjectionInWalSave: operation.includeProjectionInWalSave === true,
                    projectionDeferDelayMs: operation.projectionDeferDelayMs,
                    projectionReconcileDelayMs: operation.projectionReconcileDelayMs
                })
            const saved = persistenceResult?.saved === true
            if(saved) {
                if(persistenceResult?.authoritativeQueue) {
                    nextProjection.queue = normalizeCoordinatorMap(
                        cloneCoordinatorAuthorityValue(persistenceResult.authoritativeQueue)
                    )
                }
                if(persistenceResult?.append?.store) {
                    nextProjection.stored = {
                        ...(nextProjection.stored || {}),
                        [COORDINATOR_QUEUE_WAL_KEY]: persistenceResult.append.store,
                        ...(persistenceResult.physicalWal?.payload || {})
                    }
                }
                projection = nextProjection
                if(storageContext) {
                    storageContext.coordinatorAuthorityQueueMutationApplied = true
                    storageContext.coordinatorAuthorityQueueOperation = operationKind
                }
            }
            result = makeCoordinatorAuthorityApplyResult({...operation, operationKind, rowKey}, {
                accepted: true,
                changed: true,
                durable: saved === true,
                reason: saved ? 'persisted' : persistenceResult?.reason || 'persistence-failed',
                previousRow,
                nextRow,
                terminal: isTerminalCoordinatorStatus(nextRow?.status),
                persistence: {
                    backend: persistenceResult?.backend || 'snapshot',
                    saved: saved === true,
                    reason: persistenceResult?.reason || (saved ? 'persisted' : 'persistence-failed'),
                    walSaved: persistenceResult?.walSaved === true,
                    snapshotSaved: persistenceResult?.snapshotSaved === true,
                    projectionSaved: persistenceResult?.projectionSaved,
                    append: persistenceResult?.append || null
                }
            })
        }
        catch(error) {
            result = makeCoordinatorAuthorityApplyResult({...operation, operationKind, rowKey}, {
                accepted: true,
                changed: true,
                durable: false,
                reason: 'persistence-error',
                previousRow,
                nextRow,
                terminal: isTerminalCoordinatorStatus(nextRow?.status),
                persistence: {
                    saved: false,
                    error: `${error?.message || error || 'storage error'}`.slice(0, 240)
                }
            })
        }
        result.shadowWal = safeRecordCoordinatorAuthorityShadowWalProjection(result)
        return result
    }

    function enqueueApplyLocked(operation = {}) {
        const run = applyTail
            .catch(() => null)
            .then(() => applyLocked(operation))
        applyTail = run.catch(() => null)
        return run
    }

    async function apply(operation = {}) {
        const operationKind = normalizeQueueWriteOperationName(operation.operationKind || operation.kind || 'authority-row-mutation')
        const rowKey = normalizeCoordinatorAuthorityRowKey(
            operation.rowKey || operation.coordinatorKey || operation.profileHref || ''
        )
        const fallbackResult = makeCoordinatorAuthorityApplyResult({...operation, operationKind, rowKey}, {
            accepted: false,
            changed: false,
            durable: false,
            reason: 'storage-update-fallback',
            persistence: {
                saved: false,
                storageTimedOut: true,
                fallbackReturned: true
            }
        })

        return enqueueSpaceFeedStorageUpdate(
            () => enqueueApplyLocked({
                ...operation,
                currentAuthorityState: null,
                authorityState: null,
                lockedProjection: null,
                allowCurrentAuthorityState: false,
                allowLockedProjection: false
            }),
            {
                reason: `coordinator-authority.${operationKind}`,
                timeoutMs: operation.timeoutMs || QUEUE_CRITICAL_STORAGE_UPDATE_TIMEOUT_MS,
                failureValue: fallbackResult,
                suppressDurableIdleResume: operation.suppressDurableIdleResume === true
            }
        )
    }

    async function applyWithinStorageUpdate(operation = {}) {
        const operationKind = normalizeQueueWriteOperationName(operation.operationKind || operation.kind || 'authority-row-mutation')
        const rowKey = normalizeCoordinatorAuthorityRowKey(
            operation.rowKey || operation.coordinatorKey || operation.profileHref || ''
        )
        if(!getActiveStorageContext()) {
            return makeCoordinatorAuthorityApplyResult({...operation, operationKind, rowKey}, {
                accepted: false,
                changed: false,
                durable: false,
                reason: 'storage-update-required',
                persistence: {
                    saved: false,
                    requiresStorageUpdate: true
                }
            })
        }

        return enqueueApplyLocked({
            ...operation,
            allowCurrentAuthorityState: operation.forceFreshAuthorityState === true
                ? false
                : true,
            allowLockedProjection: operation.forceFreshAuthorityState === true
                ? false
                : true
        })
    }

    return {
        hydrate,
        current,
        seedResidentProjection,
        persist,
        apply,
        applyWithinStorageUpdate,
        absorbPersistedSnapshot,
        isHydrated() {
            return hydrated
        }
    }
}

const coordinatorQueueWal = createCoordinatorQueueWalStore({
    constants: {
        COORDINATOR_QUEUE_WAL_KEY,
        COORDINATOR_QUEUE_WAL_META_KEY,
        COORDINATOR_QUEUE_WAL_SEGMENT_SOFT_SWITCH_AT,
        COORDINATOR_QUEUE_WAL_SEGMENT_HARD_LIMIT,
        COORDINATOR_QUEUE_WAL_MIGRATED_OPERATIONS
    },
    metrics: {
        incrementQueueWakeupMetric,
        recordQueueWakeupMetricMax,
        getJsonByteSize
    },
    authority: {
        cloneCoordinatorAuthorityValue,
        normalizeCoordinatorAuthorityRowKey,
        normalizeSnapshotWriteReason,
        normalizeQueueWriteOperationName,
        getAttemptIdFromValue,
        getAttemptNumberFromValue,
        makeCoordinatorQueueWalCheckpoint
    },
    runtime: {
        Date
    }
})
const {
    shouldUseCoordinatorQueueWalBackend,
    normalizeCoordinatorQueueWalStore,
    isCoordinatorQueueWalPhysicalStorageKey,
    getCoordinatorQueueWalPhysicalStoredPayload,
    getCoordinatorQueueWalStorageDefaults,
    canUseResidentCoordinatorQueueWalStoreForMeta,
    getCoordinatorQueueWalPhysicalPayload,
    recordCoordinatorQueueWalPhysicalPayloadMetrics,
    getRetiredCoordinatorQueueWalPhysicalKeys,
    makeCoordinatorAuthorityQueueWalRemoveRecord
} = coordinatorQueueWal

const coordinatorAuthority = createCoordinatorAuthority()
coordinatorAuthoritySnapshotObserver = payload => coordinatorAuthority.absorbPersistedSnapshot(payload)

function getHydratedCoordinatorAuthorityState(metricName = '') {
    if(!coordinatorAuthority.isHydrated()) return null

    const currentAuthorityState = coordinatorAuthority.current()
    if(!currentAuthorityState?.queue || typeof currentAuthorityState.queue !== 'object') return null

    if(metricName) incrementQueueWakeupMetric(metricName)
    return currentAuthorityState
}

function refreshResidentCoordinatorAuthorityState(state = null, metricName = '') {
    const hasQueue = state && typeof state === 'object' &&
        Object.prototype.hasOwnProperty.call(state, 'queue')
    const hasStoredRawQueue = state?.stored && typeof state.stored === 'object' &&
        Object.prototype.hasOwnProperty.call(state.stored, COORDINATOR_QUEUE_KEY)
    const hasWalPayload = Object.keys(state?.stored || {}).some(isCoordinatorQueueWalPhysicalStorageKey) ||
        Object.prototype.hasOwnProperty.call(state?.stored || {}, COORDINATOR_QUEUE_WAL_KEY)
    if(!hasQueue && !hasStoredRawQueue && !hasWalPayload) return false

    const normalized = normalizeCoordinatorAuthorityStateInput(state)
    if(!normalized?.queue) return false
    if(!coordinatorAuthority.isHydrated()) return false

    const payload = hasWalPayload
        ? {
            ...(normalized.stored || {}),
            [COORDINATOR_RUNS_KEY]: normalized.runs || {}
        }
        : {
            ...(normalized.stored || {}),
            [COORDINATOR_QUEUE_KEY]: normalized.queue,
            [COORDINATOR_RUNS_KEY]: normalized.runs || {}
        }
    const changed = coordinatorAuthority.absorbPersistedSnapshot(payload, {
        allowRecoveredAuthorityQueueSeed: !hasWalPayload
    })
    if(changed && metricName) incrementQueueWakeupMetric(metricName)
    return changed
}

async function loadCoordinatorQueueProjection(options = {}) {
    return runQueueWakeupMetricPhase('loadCoordinatorQueueProjection', async () => {
        const stored = await metricStorageGet({
            ...getCoordinatorQueueWalStorageDefaults()
        }, {
            metricPath: options.metricPath || 'coordinatorQueueProjection.load'
        })
        const queueSnapshot = {}
        const walStore = await loadCoordinatorQueueWalStoreFromStorage(stored, queueSnapshot, {
            metricPath: `${options.metricPath || 'coordinatorQueueProjection.load'}.segments`
        })
        const queueRecovery = runQueueWakeupMetricPhase('recoverQueueWal', () => recoverCoordinatorQueueFromWal(
            queueSnapshot,
            walStore
        ))
        const queue = queueRecovery.queue
        recordActiveStorageWorkSnapshot(queue)
        closeRuntimeTabsReclaimedByAuthority(queue, 'queue-projection-reclaimed-runtime')

        return {
            stored,
            queue
        }
    })
}

