            mutateCoordinatorStaleRetryQueuedTabAdvance,
            mutateCoordinatorStoredWorkCancel,
            mutateCoordinatorStoredWorkItemCancel,
            mutateCoordinatorStoredWorkPause,
            requeueDurableActiveCoordinatorItemWithoutActor,
